'use client';

import { useState, useEffect } from 'react';
import { BarChart3, ExternalLink, TrendingUp, Users, Clock, Activity, Globe, Monitor, Link as LinkIcon, FileText } from 'lucide-react';
import { AdminAnalyticsChart } from '@/components/admin/AdminAnalyticsChart';
import { AdminStatCard } from '@/components/admin/AdminStatCard';

const POSTHOG_HOST = 'https://us.posthog.com';
const POSTHOG_PROJECT_ID = '275150';

interface DashboardStats {
    pageviews: { total: number; chart: any[] };
    uniques: { total: number };
    sessionStats: {
        avgDuration: number;
        bounceRate: number;
        count?: number;
    };
    topPages: Array<{ path: string; visitors: number; views: number }>;
    topSources: Array<{ source: string; visitors: number; views: number }>;
    devices: Array<{ name: string; visitors: number; views: number }>;
    geo: Array<{ country: string; count: number }>;
    debug?: any;
}

import { DateRangeSelector } from '@/components/admin/DateRangeSelector';

export default function AnalyticsPage() {
    const [analyticsData, setAnalyticsData] = useState<any[]>([]);
    const [stats, setStats] = useState<DashboardStats | null>(null);
    const [loading, setLoading] = useState(true);
    const [dateRange, setDateRange] = useState('-7d');

    useEffect(() => {
        const fetchAnalytics = async () => {
            setLoading(true);
            try {
                const res = await fetch(`/api/admin/analytics?from=${dateRange}`);
                if (res.ok) {
                    const data = await res.json();
                    setStats(data);
                    if (data.pageviews?.chart) {
                        setAnalyticsData(data.pageviews.chart.map((item: any) => ({
                            labels: item.label,
                            data: item.value
                        })));
                    }
                }
            } catch (error) {
                console.error('Failed to load analytics', error);
            } finally {
                setLoading(false);
            }
        };
        fetchAnalytics();
    }, [dateRange]);

    const formatDuration = (seconds?: number) => {
        if (seconds === undefined || seconds === null) return '0m 0s';
        const m = Math.floor(seconds / 60);
        const s = Math.floor(seconds % 60);
        return `${m}m ${s}s`;
    };

    return (
        <div className="p-6 max-w-7xl mx-auto space-y-8">
            <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
                <div className="flex items-center gap-3">
                    <div className="p-2 bg-indigo-500/10 rounded-lg">
                        <BarChart3 className="w-6 h-6 text-indigo-500" />
                    </div>
                    <div>
                        <h1 className="text-2xl font-bold text-white">Business Intelligence</h1>
                        <p className="text-slate-400 text-sm">Visión completa del rendimiento del negocio</p>
                    </div>
                </div>

                <div className="flex items-center gap-3">
                    <DateRangeSelector value={dateRange} onChange={setDateRange} />

                    <a
                        href={`${POSTHOG_HOST}/project/${POSTHOG_PROJECT_ID}`}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-xl hover:bg-indigo-700 transition-colors text-sm font-medium shadow-lg shadow-indigo-500/20"
                    >
                        <ExternalLink className="w-4 h-4" />
                        <span className="hidden sm:inline">PostHog Avanzado</span>
                        <span className="sm:hidden">PostHog</span>
                    </a>
                </div>
            </div>

            {/* KPI Grid */}
            <div className="grid grid-cols-1 md:grid-cols-3 lg:grid-cols-5 gap-4">
                <AdminStatCard
                    title="Visitantes (Usuarios)"
                    value={stats?.uniques?.total?.toLocaleString() || '0'}
                    icon={Users}
                    color="text-blue-400 bg-blue-400/10 border-blue-400/20"
                    loading={loading}
                    trend="Únicos"
                    trendUp={true}
                />
                <AdminStatCard
                    title="Vistas de Página"
                    value={stats?.pageviews?.total?.toLocaleString() || '0'}
                    icon={FileText}
                    color="text-emerald-400 bg-emerald-400/10 border-emerald-400/20"
                    loading={loading}
                    trend="Total"
                    trendUp={true}
                />
                <AdminStatCard
                    title="Sesiones Totales"
                    value={stats?.sessionStats?.count?.toLocaleString() || '0'}
                    icon={Activity}
                    color="text-indigo-400 bg-indigo-400/10 border-indigo-400/20"
                    loading={loading}
                    trend="Interacciones"
                    trendUp={true}
                />
                <AdminStatCard
                    title="Duración Sesión"
                    value={formatDuration(stats?.sessionStats?.avgDuration)}
                    icon={Clock}
                    color="text-purple-400 bg-purple-400/10 border-purple-400/20"
                    loading={loading}
                    trend="Promedio"
                    trendUp={true}
                />
                <AdminStatCard
                    title="Tasa de Rebote"
                    value={`${(stats?.sessionStats?.bounceRate || 0).toFixed(1)}%`}
                    icon={TrendingUp}
                    color="text-orange-400 bg-orange-400/10 border-orange-400/20"
                    loading={loading}
                    trend="Retención"
                    trendUp={(stats?.sessionStats?.bounceRate || 0) < 50} // Good if low
                />
            </div>

            {/* Main Traffic Chart */}
            <div className="space-y-4">
                <h3 className="text-lg font-bold text-white flex items-center gap-2">
                    <TrendingUp size={20} className="text-slate-400" />
                    Tendencia de Tráfico
                </h3>
                <AdminAnalyticsChart data={analyticsData} loading={loading} />
            </div>

            {/* Detailed Breakdowns Grid */}
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">

                {/* Top Pages Table */}
                <div className="bg-slate-900 border border-slate-800 rounded-2xl p-6 flex flex-col col-span-1 lg:col-span-2">
                    <h3 className="text-lg font-bold text-white mb-4 flex items-center gap-2">
                        <FileText size={18} className="text-blue-400" /> Páginas Más Visitadas
                    </h3>
                    <div className="flex-1 overflow-auto max-h-[400px] custom-scrollbar">
                        <table className="w-full text-left border-collapse">
                            <thead>
                                <tr className="text-xs text-slate-400 border-b border-slate-800">
                                    <th className="py-3 px-4 font-medium uppercase tracking-wider">Ruta (Path)</th>
                                    <th className="py-3 px-4 font-medium uppercase tracking-wider text-right">Visitantes</th>
                                    <th className="py-3 px-4 font-medium uppercase tracking-wider text-right">Vistas</th>
                                </tr>
                            </thead>
                            <tbody className="text-sm">
                                {loading ? (
                                    [...Array(5)].map((_, i) => (
                                        <tr key={i} className="border-b border-slate-800/50 animate-pulse">
                                            <td className="py-3 px-4"><div className="h-4 bg-slate-800 rounded w-48"></div></td>
                                            <td className="py-3 px-4"><div className="h-4 bg-slate-800 rounded w-12 ml-auto"></div></td>
                                            <td className="py-3 px-4"><div className="h-4 bg-slate-800 rounded w-12 ml-auto"></div></td>
                                        </tr>
                                    ))
                                ) : stats?.topPages?.length === 0 ? (
                                    <tr>
                                        <td colSpan={3} className="py-8 text-center text-slate-400">No hay datos disponibles.</td>
                                    </tr>
                                ) : (
                                    stats?.topPages?.map((page, i) => (
                                        <tr key={i} className="border-b border-slate-800 hover:bg-slate-800/50 transition-colors">
                                            <td className="py-3 px-4">
                                                <div className="text-indigo-400 font-mono text-xs">{page.path}</div>
                                            </td>
                                            <td className="py-3 px-4 text-right font-medium text-white">
                                                {(page.visitors || 0).toLocaleString()}
                                            </td>
                                            <td className="py-3 px-4 text-right font-medium text-emerald-400">
                                                {(page.views || 0).toLocaleString()}
                                            </td>
                                        </tr>
                                    ))
                                )}
                            </tbody>
                        </table>
                    </div>
                </div>

                {/* Top Sources */}
                <div className="bg-slate-900 border border-slate-800 rounded-2xl p-6 flex flex-col">
                    <h3 className="text-lg font-bold text-white mb-4 flex items-center gap-2">
                        <LinkIcon size={18} className="text-emerald-400" /> Canales de Tráfico
                    </h3>
                    <div className="flex-1 overflow-auto max-h-[300px] custom-scrollbar">
                        <table className="w-full text-left border-collapse">
                            <thead>
                                <tr className="text-xs text-slate-400 border-b border-slate-800">
                                    <th className="py-3 px-2 font-medium uppercase tracking-wider">Fuente</th>
                                    <th className="py-3 px-2 font-medium uppercase tracking-wider text-right">Visitas</th>
                                    <th className="py-3 px-2 font-medium uppercase tracking-wider text-right">Vistas</th>
                                </tr>
                            </thead>
                            <tbody className="text-sm">
                                {loading ? <tr className="animate-pulse"><td colSpan={3} className="h-20 bg-slate-800/50"></td></tr> :
                                    stats?.topSources?.length === 0 ? <tr><td colSpan={3} className="p-4 text-slate-400 text-center">Sin datos.</td></tr> :
                                        stats?.topSources?.map((src, i) => (
                                            <tr key={i} className="border-b border-slate-800 hover:bg-slate-800/30">
                                                <td className="py-3 px-2 text-slate-300 truncate max-w-[150px]">{src.source}</td>
                                                <td className="py-3 px-2 text-right text-white font-medium">{(src.visitors || 0).toLocaleString()}</td>
                                                <td className="py-3 px-2 text-right text-emerald-400 font-medium">{(src.views || 0).toLocaleString()}</td>
                                            </tr>
                                        ))}
                            </tbody>
                        </table>
                    </div>
                </div>

                {/* Geo Distribution (Kept as list/bar for visualization) */}
                <div className="bg-slate-900 border border-slate-800 rounded-2xl p-6 flex flex-col">
                    <h3 className="text-lg font-bold text-white mb-4 flex items-center gap-2">
                        <Globe size={18} className="text-purple-400" /> Ubicación Geográfica
                    </h3>
                    <div className="flex-1 overflow-auto max-h-[300px] custom-scrollbar space-y-3">
                        {loading ? <div className="animate-pulse h-20 bg-slate-800/50 rounded-lg"></div> :
                            stats?.geo?.length === 0 ? <p className="text-slate-400 text-sm">No hay datos geográficos disponibles.</p> :
                                stats?.geo?.map((g, i) => (
                                    <div key={i} className="flex justify-between items-center p-3 rounded-lg bg-slate-800/30 border border-slate-800 hover:bg-slate-800/50 transition">
                                        <span className="text-sm text-slate-300">{g.country}</span>
                                        <div className="w-24 h-2 bg-slate-800 rounded-full overflow-hidden relative">
                                            <div className="absolute top-0 left-0 h-full bg-purple-500" style={{ width: `${Math.min((g.count / (stats?.uniques?.total || 1)) * 100, 100)}%` }}></div>
                                        </div>
                                        <span className="text-xs font-bold text-slate-400 w-8 text-right">{g.count}</span>
                                    </div>
                                ))}
                    </div>
                </div>

                {/* Device Breakdown (Table) */}
                <div className="bg-slate-900 border border-slate-800 rounded-2xl p-6 flex flex-col col-span-1 lg:col-span-2">
                    <h3 className="text-lg font-bold text-white mb-4 flex items-center gap-2">
                        <Monitor size={18} className="text-orange-400" /> Dispositivos
                    </h3>
                    <div className="flex-1 overflow-auto max-h-[300px] custom-scrollbar">
                        <table className="w-full text-left border-collapse">
                            <thead>
                                <tr className="text-xs text-slate-400 border-b border-slate-800">
                                    <th className="py-3 px-4 font-medium uppercase tracking-wider">Tipo de Dispositivo</th>
                                    <th className="py-3 px-4 font-medium uppercase tracking-wider text-right">Visitantes</th>
                                    <th className="py-3 px-4 font-medium uppercase tracking-wider text-right">Vistas de Página</th>
                                </tr>
                            </thead>
                            <tbody className="text-sm">
                                {loading ? <tr className="animate-pulse"><td colSpan={3} className="h-20 bg-slate-800/50"></td></tr> :
                                    stats?.devices?.length === 0 ? <tr><td colSpan={3} className="p-4 text-slate-400 text-center">Sin datos.</td></tr> :
                                        stats?.devices?.map((d, i) => (
                                            <tr key={i} className="border-b border-slate-800 hover:bg-slate-800/30">
                                                <td className="py-3 px-4 text-slate-300 flex items-center gap-2">
                                                    {d.name === 'Desktop' ? <Monitor size={16} /> : <div className="w-4 h-4 rounded-sm bg-slate-700" />}
                                                    {d.name}
                                                </td>
                                                <td className="py-3 px-4 text-right text-white font-medium">{(d.visitors || 0).toLocaleString()}</td>
                                                <td className="py-3 px-4 text-right text-emerald-400 font-medium">{(d.views || 0).toLocaleString()}</td>
                                            </tr>
                                        ))}
                            </tbody>
                        </table>
                    </div>
                </div>

            </div>
            {/* Info Box */}
            <div className="bg-slate-900 border border-slate-800 rounded-2xl p-6 flex items-start gap-4">
                <div className="p-2 bg-blue-500/10 rounded-lg mt-1">
                    <BarChart3 className="w-5 h-5 text-blue-400" />
                </div>
                <div>
                    <h4 className="font-semibold text-white mb-1">Integración Activa</h4>
                    <p className="text-sm text-slate-400">
                        Los datos se están extrayendo directamente de la API de PostHog.
                        Para análisis más profundos como embudos, grabaciones de sesión o mapas de calor,
                        utiliza el botón "PostHog Avanzado".
                    </p>
                </div>
            </div>
            {/* Debug Info (Only visible if issues occur) */}
            {stats?.debug && (stats.debug.pageviews !== 'OK' || stats.debug.uniques !== 'OK') && (
                <div className="bg-slate-900 border border-slate-800 rounded-2xl p-6">
                    <h4 className="font-semibold text-rose-400 mb-2 flex items-center gap-2">
                        <span>⚠️ Errores de Conexión</span>
                        <span className="text-xs px-2 py-0.5 rounded bg-slate-800 text-slate-400 font-mono">
                            Project: {stats.debug.projectId || 'N/A'}
                        </span>
                    </h4>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4 text-sm font-mono">
                        <div className={`p-3 rounded border ${stats.debug.pageviews === 'OK' ? 'border-green-900 bg-green-900/10 text-green-400' : 'border-rose-900 bg-rose-900/10 text-rose-400'}`}>
                            <strong>Pageviews:</strong> {stats.debug.pageviews}
                        </div>
                        <div className={`p-3 rounded border ${stats.debug.uniques === 'OK' ? 'border-green-900 bg-green-900/10 text-green-400' : 'border-rose-900 bg-rose-900/10 text-rose-400'}`}>
                            <strong>Uniques:</strong> {stats.debug.uniques}
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
}

'use client';

import { useState, useEffect } from 'react';
import { contentService } from '@/services/content.service';
import { Loader2, Plus, Trash2, Edit2, X, FolderKanban } from 'lucide-react';
import Link from 'next/link';

export default function CategoriesPage() {
    const [categories, setCategories] = useState<{ id: string; name: string }[]>([]);
    const [loading, setLoading] = useState(true);
    const [isCreating, setIsCreating] = useState(false);
    const [newCategoryName, setNewCategoryName] = useState('');

    useEffect(() => {
        loadCategories();
    }, []);

    const loadCategories = async () => {
        try {
            const data = await contentService.getCategories();
            setCategories(data);
        } catch (error) {
            console.error(error);
        } finally {
            setLoading(false);
        }
    };

    const handleCreate = async (e: React.FormEvent) => {
        e.preventDefault();
        try {
            await contentService.createCategory(newCategoryName);
            setNewCategoryName('');
            setIsCreating(false);
            loadCategories();
        } catch (error) {
            alert('Failed to create category');
        }
    };

    const handleDelete = async (id: string) => {
        if (!confirm('Are you sure? Courses in this category will not be deleted but will lose their category association.')) return;
        try {
            await contentService.deleteCategory(id);
            loadCategories();
        } catch (error) {
            alert('Failed to delete category');
        }
    };

    return (
        <div className="max-w-4xl mx-auto p-6 space-y-8">
            <div className="flex items-center justify-between">
                <div>
                    <h1 className="text-2xl font-bold text-white mb-2">Categories</h1>
                    <p className="text-slate-400">Manage course categories</p>
                </div>
                <button
                    onClick={() => setIsCreating(true)}
                    className="flex items-center gap-2 bg-indigo-600 hover:bg-indigo-700 text-white px-4 py-2 rounded-lg transition-colors font-medium"
                >
                    <Plus size={20} />
                    New Category
                </button>
            </div>

            {/* Create Modal (Inline for simplicity) */}
            {isCreating && (
                <div className="bg-slate-800 border border-slate-700 rounded-xl p-6 shadow-xl mb-8 animate-in fade-in slide-in-from-top-4">
                    <h3 className="text-lg font-semibold text-white mb-4">Create Category</h3>
                    <form onSubmit={handleCreate} className="flex gap-4">
                        <input
                            type="text"
                            autoFocus
                            placeholder="Category Name"
                            value={newCategoryName}
                            onChange={(e) => setNewCategoryName(e.target.value)}
                            className="flex-1 bg-slate-900 border border-slate-700 rounded-lg px-4 py-2 text-white focus:ring-2 focus:ring-indigo-500"
                        />
                        <button type="submit" className="bg-indigo-600 text-white px-4 py-2 rounded-lg font-medium hover:bg-indigo-700">Save</button>
                        <button type="button" onClick={() => setIsCreating(false)} className="bg-slate-700 text-white px-4 py-2 rounded-lg font-medium hover:bg-slate-600">Cancel</button>
                    </form>
                </div>
            )}

            {loading ? (
                <div className="flex justify-center py-12">
                    <Loader2 className="animate-spin text-indigo-500" size={32} />
                </div>
            ) : (
                <div className="grid gap-4">
                    {categories.length === 0 ? (
                        <div className="text-center py-12 bg-slate-800/50 rounded-xl border border-dashed border-slate-700">
                            <FolderKanban className="mx-auto text-slate-500 mb-4" size={48} />
                            <h3 className="text-xl font-medium text-white mb-2">No categories found</h3>
                            <button onClick={() => setIsCreating(true)} className="text-indigo-400 hover:text-indigo-300">Create your first category</button>
                        </div>
                    ) : (
                        categories.map((cat) => (
                            <div key={cat.id} className="bg-slate-800 border border-slate-700 rounded-lg p-4 flex items-center justify-between group hover:border-slate-600 transition-colors">
                                <span className="font-medium text-white">{cat.name}</span>
                                <div className="flex gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                                    <button
                                        onClick={() => handleDelete(cat.id)}
                                        className="p-2 text-red-400 hover:bg-red-400/10 rounded-lg transition-colors"
                                        title="Delete Category"
                                    >
                                        <Trash2 size={18} />
                                    </button>
                                </div>
                            </div>
                        ))
                    )}
                </div>
            )}
        </div>
    );
}

'use client';

import Link from 'next/link';
import {
    LayoutDashboard,
    Users,
    BookOpen,
    Settings,
    Bell,
    CreditCard,
    LogOut,
    FileText,
    Home,
    BarChart3
} from 'lucide-react';
import React from 'react';
import { useAuth } from '@/contexts/AuthContext';
import { useRouter } from 'next/navigation';

const SidebarItem = ({ href, icon: Icon, label }: { href: string; icon: any; label: string }) => (
    <Link
        href={href}
        className="flex items-center gap-3 px-4 py-3 text-slate-300 hover:text-white hover:bg-slate-800 rounded-lg transition-colors"
    >
        <Icon size={20} />
        <span className="font-medium">{label}</span>
    </Link>
);

interface AdminSidebarProps {
    isOpen?: boolean;
    onClose?: () => void;
}

export function AdminSidebar({ isOpen = false, onClose }: AdminSidebarProps) {
    const { logout } = useAuth();
    const router = useRouter();

    const handleLogout = async () => {
        try {
            await logout();
            router.push('/');
        } catch (error) {
            console.error('Logout failed', error);
        }
    };

    return (
        <>
            {/* Mobile Overlay */}
            {isOpen && (
                <div
                    className="fixed inset-0 bg-black/50 z-40 md:hidden"
                    onClick={onClose}
                />
            )}

            {/* Sidebar */}
            <aside className={`
                w-64 bg-slate-950 border-r border-slate-800 flex flex-col fixed h-full z-50 transition-transform duration-300
                ${isOpen ? 'translate-x-0' : '-translate-x-full'} 
                md:translate-x-0
            `}>
                <div className="p-6 border-b border-slate-800 flex justify-between items-center">
                    <h1 className="text-xl font-bold bg-gradient-to-r from-blue-400 to-indigo-400 bg-clip-text text-transparent">
                        Tincadia Admin
                    </h1>
                    {/* Close button for mobile */}
                    <button onClick={onClose} className="md:hidden text-slate-400 hover:text-white">
                        <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M18 6 6 18" /><path d="m6 6 18 18" /></svg>
                    </button>
                </div>

                <nav className="flex-1 p-4 space-y-2 overflow-y-auto [&::-webkit-scrollbar]:hidden [-ms-overflow-style:'none'] [scrollbar-width:'none']">
                    <SidebarItem href="/admin" icon={LayoutDashboard} label="Panel" />
                    <SidebarItem href="/admin/users" icon={Users} label="Usuarios" />
                    <SidebarItem href="/admin/courses" icon={BookOpen} label="Cursos (CMS)" />
                    <SidebarItem href="/admin/notifications" icon={Bell} label="Notificaciones" />
                    <SidebarItem href="/admin/finance" icon={CreditCard} label="Finanzas" />
                    <SidebarItem href="/admin/pricing" icon={CreditCard} label="Precios" />
                    <SidebarItem href="/admin/forms" icon={FileText} label="Formularios" />
                    <SidebarItem href="/admin/landing" icon={Settings} label="Landing Page" />
                    <SidebarItem href="/admin/analytics" icon={BarChart3} label="Analytics" />
                </nav>

                <div className="p-4 border-t border-slate-800 space-y-2">
                    <Link
                        href="/"
                        className="flex items-center gap-3 px-4 py-3 w-full text-slate-300 hover:text-white hover:bg-slate-800 rounded-lg transition-colors"
                    >
                        <Home size={20} />
                        <span className="font-medium">Volver al Sitio</span>
                    </Link>
                    <button
                        onClick={handleLogout}
                        className="flex items-center gap-3 px-4 py-3 w-full text-red-400 hover:bg-red-950/30 rounded-lg transition-colors"
                    >
                        <LogOut size={20} />
                        <span className="font-medium">Cerrar Sesión</span>
                    </button>
                </div>
            </aside>
        </>
    );
}

'use client';

import { useState, useEffect } from 'react';
import { X, Loader2, UploadCloud } from 'lucide-react';
import { contentService } from '@/services/content.service';

interface CreateCourseModalProps {
    isOpen: boolean;
    onClose: () => void;
    onSuccess: () => void;
}

export default function CreateCourseModal({ isOpen, onClose, onSuccess }: CreateCourseModalProps) {
    const [categories, setCategories] = useState<{ id: string; name: string }[]>([]);
    const [title, setTitle] = useState('');
    const [description, setDescription] = useState('');
    const [categoryId, setCategoryId] = useState('');
    const [thumbnailFile, setThumbnailFile] = useState<File | null>(null);
    const [isLoading, setIsLoading] = useState(false);
const [accessScope, setAccessScope] = useState<'course' | 'module' | 'lesson'>('course');
const [isPaid, setIsPaid] = useState(false);
const [previewLimit, setPreviewLimit] = useState<number>(3);

    // Category creation state
    const [isCreatingCategory, setIsCreatingCategory] = useState(false);
    const [newCategoryName, setNewCategoryName] = useState('');

    useEffect(() => {
        if (isOpen) {
            loadCategories();
        }
    }, [isOpen]);

    const loadCategories = async () => {
        try {
            const data = await contentService.getCategories();
            setCategories(data);
            // Auto-select first if available and none selected
            if (data.length > 0 && !categoryId) {
                setCategoryId(data[0].id);
            }
        } catch (error) {
            console.error('Failed to load categories');
        }
    };

    const handleCreateCategory = async () => {
        if (!newCategoryName.trim()) return;
        try {
            const newCat = await contentService.createCategory(newCategoryName);
            await loadCategories();
            setCategoryId(newCat.id); // Auto select new category
            setIsCreatingCategory(false);
            setNewCategoryName('');
        } catch (error) {
            alert('Failed to create category');
        }
    };

    if (!isOpen) return null;

    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) {
            setThumbnailFile(e.target.files[0]);
        }
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setIsLoading(true);
        try {
            // 1. Create Course
            const newCourse = await contentService.createCourse({
                title,
                description,
                categoryId,
                isPublished: false,
                thumbnailUrl: '', // Will be updated after upload
                accessScope,
                isPaid: accessScope === 'course' ? isPaid : false,
                previewLimit,
            });

            // 2. Upload Thumbnail if exists
            if (thumbnailFile && newCourse.id) {
                await contentService.uploadThumbnail(newCourse.id, thumbnailFile);
            }

            onSuccess();
            onClose();
        } catch (error) {
            console.error(error);
            alert('Failed to create course. Ensure category is selected.');
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/80 backdrop-blur-md p-4">
            <div className="bg-slate-900 border border-slate-700 rounded-xl w-full max-w-md shadow-2xl max-h-[90vh] overflow-y-auto custom-scrollbar">
                <div className="sticky top-0 bg-slate-900 z-10 flex justify-between items-center p-6 border-b border-slate-700">
                    <h2 className="text-xl font-bold text-white">Create New Course</h2>
                    <button onClick={onClose} className="text-slate-400 hover:text-white transition-colors">
                        <X size={24} />
                    </button>
                </div>

                <form onSubmit={handleSubmit} className="p-6 space-y-4">
                    <div>
                        <label className="block text-sm font-medium text-slate-400 mb-1">Course Title</label>
                        <input
                            type="text"
                            required
                            value={title}
                            onChange={(e) => setTitle(e.target.value)}
                            className="w-full bg-slate-800 border border-slate-700 rounded-lg p-2.5 text-white focus:ring-2 focus:ring-blue-500"
                            placeholder="e.g. Advanced Medical Interpreting"
                        />
                    </div>

                    <div>
                        <label className="block text-sm font-medium text-slate-400 mb-1">Description</label>
                        <textarea
                            required
                            value={description}
                            onChange={(e) => setDescription(e.target.value)}
                            className="w-full bg-slate-800 border border-slate-700 rounded-lg p-2.5 text-white focus:ring-2 focus:ring-blue-500 h-24"
                            placeholder="Course summary..."
                        />
                    </div>

                    <div>
                        <label className="block text-sm font-medium text-slate-400 mb-1">Category</label>
                        {!isCreatingCategory ? (
                            <div className="flex gap-2">
                                <select
                                    required
                                    value={categoryId}
                                    onChange={(e) => setCategoryId(e.target.value)}
                                    className="w-full bg-slate-800 border border-slate-700 rounded-lg p-2.5 text-white focus:ring-2 focus:ring-blue-500"
                                >
                                    <option value="" disabled>Select a category</option>
                                    {categories.map(cat => (
                                        <option key={cat.id} value={cat.id}>{cat.name}</option>
                                    ))}
                                </select>
                                <button
                                    type="button"
                                    onClick={() => setIsCreatingCategory(true)}
                                    className="px-3 bg-slate-800 border border-slate-700 rounded-lg hover:bg-slate-700 text-white"
                                >
                                    +
                                </button>
                            </div>
                        ) : (
                            <div className="flex gap-2">
                                <input
                                    type="text"
                                    autoFocus
                                    value={newCategoryName}
                                    onChange={(e) => setNewCategoryName(e.target.value)}
                                    className="w-full bg-slate-800 border border-slate-700 rounded-lg p-2.5 text-white focus:ring-2 focus:ring-blue-500"
                                    placeholder="New Category Name"
                                />
                                <button
                                    type="button"
                                    onClick={handleCreateCategory}
                                    className="px-3 bg-indigo-600 rounded-lg hover:bg-indigo-700 text-white"
                                >
                                    Save
                                </button>
                                <button
                                    type="button"
                                    onClick={() => setIsCreatingCategory(false)}
                                    className="px-3 bg-slate-800 border border-slate-700 rounded-lg hover:bg-slate-700 text-white"
                                >
                                    Cancel
                                </button>
                            </div>
                        )}
                    </div>

                    <div className="grid sm:grid-cols-2 gap-4">
                        <div className="flex flex-col">
                            <label className="block text-sm font-medium text-slate-400 mb-1">Modo de acceso</label>
                            <select
                                value={accessScope}
                                onChange={(e) => setAccessScope(e.target.value as 'course' | 'module' | 'lesson')}
                                className="w-full bg-slate-800 border border-slate-700 rounded-lg p-2.5 text-white focus:ring-2 focus:ring-blue-500"
                            >
                                <option value="course">Curso completo (un pago)</option>
                                <option value="module">Por módulos</option>
                                <option value="lesson">Por lecciones/videos</option>
                            </select>
                        </div>

                        {accessScope === 'course' && (
                            <div className="flex flex-col">
                                <label className="block text-sm font-medium text-slate-400 mb-1">Curso de pago</label>
                                <div className="flex gap-3 h-[42px]">
                                    <button
                                        type="button"
                                        onClick={() => setIsPaid(!isPaid)}
                                        className={`flex-1 px-4 py-2 rounded-lg border font-medium transition-all duration-200 ${isPaid
                                            ? 'bg-amber-500/10 border-amber-500/50 text-amber-200 hover:bg-amber-500/20'
                                            : 'bg-emerald-500/10 border-emerald-500/50 text-emerald-200 hover:bg-emerald-500/20'
                                            }`}
                                    >
                                        {isPaid ? '🔒 De pago' : '🔓 Libre'}
                                    </button>

                                    {isPaid && (
                                        <div className="w-24 animate-in fade-in slide-in-from-right-2 duration-300">
                                            <input
                                                type="number"
                                                min={0}
                                                max={10}
                                                value={previewLimit}
                                                onChange={(e) => setPreviewLimit(Number(e.target.value))}
                                                className="w-full h-full bg-slate-800 border border-slate-700 rounded-lg px-3 text-white focus:ring-2 focus:ring-blue-500"
                                                title="Número de videos gratuitos"
                                                placeholder="0"
                                            />
                                        </div>
                                    )}
                                </div>
                                {isPaid ? (
                                    <p className="text-[10px] text-slate-500 mt-1 animate-in fade-in duration-300">
                                        Videos gratis recomendados: 3-4.
                                    </p>
                                ) : (
                                    <p className="text-[10px] text-slate-400 mt-1 animate-in fade-in duration-300 italic">
                                        Todo el contenido será gratuito.
                                    </p>
                                )}
                            </div>
                        )}
                    </div>

                    <div className="border border-slate-700 border-dashed rounded-lg p-6 flex flex-col items-center justify-center text-slate-500 hover:bg-slate-800/50 transition-colors cursor-pointer relative">
                        <input
                            type="file"
                            className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
                            accept="image/*"
                            onChange={handleFileChange}
                        />
                        <UploadCloud size={32} className="mb-2" />
                        <span className="text-sm">
                            {thumbnailFile ? thumbnailFile.name : 'Upload Thumbnail (Click or Drag)'}
                        </span>
                    </div>

                    <div className="pt-4 flex gap-3">
                        <button
                            type="button"
                            onClick={onClose}
                            className="flex-1 px-4 py-2 bg-slate-800 hover:bg-slate-700 text-white rounded-lg font-medium transition-colors"
                        >
                            Cancel
                        </button>
                        <button
                            type="submit"
                            disabled={isLoading}
                            className="flex-1 px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-lg font-medium transition-colors flex items-center justify-center gap-2"
                        >
                            {isLoading && <Loader2 className="animate-spin" size={18} />}
                            Create Course
                        </button>
                    </div>
                </form>
            </div>
        </div>
    );
}

'use client';

import { useState, useEffect } from 'react';
import { X, Loader2, Plus, Trash2 } from 'lucide-react';
import { contentService, Course } from '@/services/content.service';

interface EditCourseModalProps {
    isOpen: boolean;
    onClose: () => void;
    onSuccess: (updatedCourse: Course) => void;
    course: Course;
}

export default function EditCourseModal({ isOpen, onClose, onSuccess, course }: EditCourseModalProps) {
    const [categories, setCategories] = useState<{ id: string; name: string }[]>([]);
    const [title, setTitle] = useState(course.title);
    const [description, setDescription] = useState(course.description);
    const [categoryId, setCategoryId] = useState(course.categoryId);
    const [priceInCents, setPriceInCents] = useState(course.priceInCents || 0);
    const [priceLabel, setPriceLabel] = useState(course.priceLabel || 'Pago único, acceso de por vida');

    // Arrays for learning points and features
    const [learningPoints, setLearningPoints] = useState<string[]>(course.learningPoints || []);
    const [features, setFeatures] = useState<string[]>(course.features || []);

    const [isLoading, setIsLoading] = useState(false);

    useEffect(() => {
        if (isOpen) {
            loadCategories();
            // Sync with course data in case it changed externally
            setTitle(course.title);
            setDescription(course.description);
            setCategoryId(course.categoryId);
            setPriceInCents(course.priceInCents || 0);
            setPriceLabel(course.priceLabel || 'Pago único, acceso de por vida');
            setLearningPoints(course.learningPoints || []);
            setFeatures(course.features || []);
        }
    }, [isOpen, course]);

    const loadCategories = async () => {
        try {
            const data = await contentService.getCategories();
            setCategories(data);
        } catch (error) {
            console.error('Failed to load categories');
        }
    };

    if (!isOpen) return null;

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setIsLoading(true);
        try {
            const updatedCourse = await contentService.updateCourse(course.id, {
                title,
                description,
                categoryId,
                priceInCents,
                priceLabel,
                learningPoints: learningPoints.filter(p => p.trim() !== ''),
                features: features.filter(f => f.trim() !== ''),
            });

            onSuccess(updatedCourse);
            onClose();
        } catch (error) {
            console.error(error);
            alert('Failed to update course.');
        } finally {
            setIsLoading(false);
        }
    };

    const addLearningPoint = () => setLearningPoints([...learningPoints, '']);
    const updateLearningPoint = (index: number, value: string) => {
        const newPoints = [...learningPoints];
        newPoints[index] = value;
        setLearningPoints(newPoints);
    };
    const removeLearningPoint = (index: number) => {
        setLearningPoints(learningPoints.filter((_, i) => i !== index));
    };

    const addFeature = () => setFeatures([...features, '']);
    const updateFeature = (index: number, value: string) => {
        const newFeatures = [...features];
        newFeatures[index] = value;
        setFeatures(newFeatures);
    };
    const removeFeature = (index: number) => {
        setFeatures(features.filter((_, i) => i !== index));
    };

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/80 backdrop-blur-md p-4">
            <div className="bg-slate-900 border border-slate-700 rounded-xl w-full max-w-2xl shadow-2xl max-h-[90vh] overflow-y-auto custom-scrollbar">
                <div className="sticky top-0 bg-slate-900 z-10 flex justify-between items-center p-6 border-b border-slate-700">
                    <h2 className="text-xl font-bold text-white">Editar Información del Curso</h2>
                    <button onClick={onClose} className="text-slate-400 hover:text-white transition-colors">
                        <X size={24} />
                    </button>
                </div>

                <form onSubmit={handleSubmit} className="p-6 space-y-6">
                    <div className="grid md:grid-cols-2 gap-6">
                        {/* Basic Info */}
                        <div className="space-y-4">
                            <div>
                                <label className="block text-sm font-medium text-slate-400 mb-1">Título del Curso</label>
                                <input
                                    type="text"
                                    required
                                    value={title}
                                    onChange={(e) => setTitle(e.target.value)}
                                    className="w-full bg-slate-800 border border-slate-700 rounded-lg p-2.5 text-white focus:ring-2 focus:ring-indigo-500"
                                />
                            </div>

                            <div>
                                <label className="block text-sm font-medium text-slate-400 mb-1">Categoría</label>
                                <select
                                    required
                                    value={categoryId}
                                    onChange={(e) => setCategoryId(e.target.value)}
                                    className="w-full bg-slate-800 border border-slate-700 rounded-lg p-2.5 text-white focus:ring-2 focus:ring-indigo-500"
                                >
                                    {categories.map(cat => (
                                        <option key={cat.id} value={cat.id}>{cat.name}</option>
                                    ))}
                                </select>
                            </div>

                            <div>
                                <label className="block text-sm font-medium text-slate-400 mb-1">Descripción</label>
                                <textarea
                                    required
                                    value={description}
                                    onChange={(e) => setDescription(e.target.value)}
                                    className="w-full bg-slate-800 border border-slate-700 rounded-lg p-2.5 text-white focus:ring-2 focus:ring-indigo-500 h-32 resize-none"
                                />
                            </div>
                        </div>

                        {/* Pricing Info */}
                        <div className="space-y-4">
                            <div>
                                <label className="block text-sm font-medium text-slate-400 mb-1">Precio (en centavos)</label>
                                <input
                                    type="number"
                                    value={priceInCents}
                                    onChange={(e) => setPriceInCents(Number(e.target.value))}
                                    className="w-full bg-slate-800 border border-slate-700 rounded-lg p-2.5 text-white focus:ring-2 focus:ring-indigo-500"
                                    placeholder="Ej: 9900 para $99.00"
                                />
                                <p className="text-[10px] text-slate-500 mt-1">
                                    Precio actual: ${(priceInCents / 100).toFixed(2)}
                                </p>
                            </div>

                            <div>
                                <label className="block text-sm font-medium text-slate-400 mb-1">Etiqueta de Precio</label>
                                <input
                                    type="text"
                                    value={priceLabel}
                                    onChange={(e) => setPriceLabel(e.target.value)}
                                    className="w-full bg-slate-800 border border-slate-700 rounded-lg p-2.5 text-white focus:ring-2 focus:ring-indigo-500"
                                    placeholder="Ej: Pago único, acceso de por vida"
                                />
                            </div>
                        </div>
                    </div>

                    <hr className="border-slate-700" />

                    {/* Learning Points & Features */}
                    <div className="grid md:grid-cols-2 gap-6">
                        <div className="space-y-3">
                            <div className="flex justify-between items-center">
                                <label className="text-sm font-medium text-slate-400">Lo que aprenderás</label>
                                <button type="button" onClick={addLearningPoint} className="text-xs text-indigo-400 flex items-center gap-1 hover:text-indigo-300">
                                    <Plus size={14} /> Añadir
                                </button>
                            </div>
                            <div className="space-y-2">
                                {learningPoints.map((point, index) => (
                                    <div key={index} className="flex gap-2">
                                        <input
                                            type="text"
                                            value={point}
                                            onChange={(e) => updateLearningPoint(index, e.target.value)}
                                            className="flex-1 bg-slate-800 border border-slate-700 rounded-lg p-2 text-sm text-white"
                                            placeholder="Punto de aprendizaje..."
                                        />
                                        <button type="button" onClick={() => removeLearningPoint(index)} className="text-slate-500 hover:text-red-400 p-2">
                                            <Trash2 size={16} />
                                        </button>
                                    </div>
                                ))}
                                {learningPoints.length === 0 && <p className="text-xs text-slate-600 italic">No hay puntos definidos (usará defaults).</p>}
                            </div>
                        </div>

                        <div className="space-y-3">
                            <div className="flex justify-between items-center">
                                <label className="text-sm font-medium text-slate-400">Características / Beneficios</label>
                                <button type="button" onClick={addFeature} className="text-xs text-indigo-400 flex items-center gap-1 hover:text-indigo-300">
                                    <Plus size={14} /> Añadir
                                </button>
                            </div>
                            <div className="space-y-2">
                                {features.map((feature, index) => (
                                    <div key={index} className="flex gap-2">
                                        <input
                                            type="text"
                                            value={feature}
                                            onChange={(e) => updateFeature(index, e.target.value)}
                                            className="flex-1 bg-slate-800 border border-slate-700 rounded-lg p-2 text-sm text-white"
                                            placeholder="Ej: Certificado incluido"
                                        />
                                        <button type="button" onClick={() => removeFeature(index)} className="text-slate-500 hover:text-red-400 p-2">
                                            <Trash2 size={16} />
                                        </button>
                                    </div>
                                ))}
                                {features.length === 0 && <p className="text-xs text-slate-600 italic">No hay características definidas (usará defaults).</p>}
                            </div>
                        </div>
                    </div>

                    <div className="pt-4 flex gap-3">
                        <button
                            type="button"
                            onClick={onClose}
                            className="flex-1 px-4 py-2 bg-slate-800 hover:bg-slate-700 text-white rounded-lg font-medium transition-colors"
                        >
                            Cancelar
                        </button>
                        <button
                            type="submit"
                            disabled={isLoading}
                            className="flex-1 px-4 py-2 bg-indigo-600 hover:bg-indigo-700 text-white rounded-lg font-medium transition-colors flex items-center justify-center gap-2"
                        >
                            {isLoading && <Loader2 className="animate-spin" size={18} />}
                            Guardar Cambios
                        </button>
                    </div>
                </form>
            </div>
        </div>
    );
}

'use client';

import { Plus, Folder, Video, BookOpen, Loader2, FolderKanban, Trash2 } from 'lucide-react';
import { useEffect, useState } from 'react';
import { contentService, Course } from '@/services/content.service';
import Link from 'next/link';
import CreateCourseModal from './CreateCourseModal';

interface Category {
    id: string;
    name: string;
}

export default function CoursesPage() {
    const [courses, setCourses] = useState<Course[]>([]);
    const [categories, setCategories] = useState<Category[]>([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);
    const [isCreateModalOpen, setIsCreateModalOpen] = useState(false);

    useEffect(() => {
        fetchData();
    }, []);

    const fetchData = async () => {
        try {
            setLoading(true);
            const [coursesData, categoriesData] = await Promise.all([
                contentService.getAllCourses(),
                contentService.getCategories()
            ]);
            setCourses(coursesData);
            setCategories(categoriesData);
        } catch (err) {
            setError('Failed to load content library. Please try again later.');
            console.error(err);
        } finally {
            setLoading(false);
        }
    };

    if (loading) {
        return (
            <div className="flex items-center justify-center h-64">
                <Loader2 className="animate-spin text-indigo-500" size={32} />
            </div>
        );
    }

    if (error) {
        return (
            <div className="text-center py-12">
                <p className="text-red-400 mb-4">{error}</p>
                <button onClick={fetchData} className="text-indigo-400 hover:text-indigo-300 underline">
                    Retry
                </button>
            </div>
        );
    }

    // Group courses by category
    const groupedCourses = courses.reduce((acc, course) => {
        const catId = course.categoryId || 'uncategorized';
        if (!acc[catId]) {
            acc[catId] = [];
        }
        acc[catId].push(course);
        return acc;
    }, {} as Record<string, Course[]>);

    // Get sorted category IDs (known categories first, then uncategorized)
    const sortedCategoryIds = Object.keys(groupedCourses).sort((a, b) => {
        if (a === 'uncategorized') return 1;
        if (b === 'uncategorized') return -1;
        // Find names for sorting
        const nameA = categories.find(c => c.id === a)?.name || '';
        const nameB = categories.find(c => c.id === b)?.name || '';
        return nameA.localeCompare(nameB);
    });

    return (
        <div className="space-y-12 pb-12">
            <CreateCourseModal
                isOpen={isCreateModalOpen}
                onClose={() => setIsCreateModalOpen(false)}
                onSuccess={fetchData}
            />

            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                <div>
                    <h2 className="text-2xl font-bold text-white">Content Library</h2>
                    <p className="text-slate-400">Administra cursos, módulos y lecciones.</p>
                </div>
                <div className="flex gap-3">
                    <Link
                        href="/admin/categories"
                        className="flex items-center gap-2 bg-slate-800 hover:bg-slate-700 border border-slate-700 text-white px-4 py-2 rounded-lg transition-colors font-medium"
                    >
                        <FolderKanban size={18} />
                        <span>Categorías</span>
                    </Link>
                    <button
                        onClick={() => setIsCreateModalOpen(true)}
                        className="bg-indigo-600 hover:bg-indigo-700 text-white px-4 py-2 rounded-lg font-medium transition-colors flex items-center gap-2"
                    >
                        <Plus size={18} />
                        <span>Nuevo Curso</span>
                    </button>
                </div>
            </div>

            {courses.length === 0 ? (
                <div className="text-center py-20 bg-slate-800/50 rounded-2xl border border-slate-700 border-dashed">
                    <div className="inline-flex p-4 rounded-full bg-slate-800 mb-4">
                        <BookOpen size={32} className="text-slate-500" />
                    </div>
                    <h3 className="text-xl font-bold text-white mb-2">No tienes cursos creados</h3>
                    <p className="text-slate-400 mb-6 max-w-md mx-auto">Comienza creando tu primer curso para compartir conocimiento con tus usuarios.</p>
                    <button
                        onClick={() => setIsCreateModalOpen(true)}
                        className="text-indigo-400 hover:text-indigo-300 font-medium hover:underline"
                    >
                        Crear mi primer curso
                    </button>
                </div>
            ) : (
                <div className="space-y-12">
                    {sortedCategoryIds.map((categoryId) => {
                        const categoryName = categories.find(c => c.id === categoryId)?.name || (categoryId === 'uncategorized' ? 'Sin Categoría' : 'Categoría Desconocida');
                        const categoryCourses = groupedCourses[categoryId];

                        return (
                            <div key={categoryId} className="space-y-4">
                                <div className="flex items-center gap-3 border-b border-slate-800 pb-2">
                                    <div className={`p-1.5 rounded-lg ${categoryId === 'uncategorized' ? 'bg-slate-800 text-slate-400' : 'bg-indigo-500/10 text-indigo-400'}`}>
                                        <FolderKanban size={18} />
                                    </div>
                                    <h3 className="text-xl font-bold text-white capitalize">{categoryName}</h3>
                                    <span className="text-xs font-medium px-2 py-0.5 rounded-full bg-slate-800 text-slate-400 ml-auto md:ml-0">
                                        {categoryCourses.length} {categoryCourses.length === 1 ? 'curso' : 'cursos'}
                                    </span>
                                </div>

                                <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
                                    {categoryCourses.map((course) => (
                                        <Link href={`/admin/courses/${course.id}`} key={course.id} className="block group">
                                            <div className="bg-slate-800 rounded-xl border border-slate-700 overflow-hidden hover:border-indigo-500/50 hover:shadow-xl hover:shadow-indigo-500/10 transition-all cursor-pointer h-full flex flex-col relative">

                                                {/* Image Container */}
                                                <div className="h-44 bg-slate-900 relative flex items-center justify-center overflow-hidden">
                                                    {course.thumbnailUrl ? (
                                                        <img
                                                            src={course.thumbnailUrl}
                                                            alt={course.title}
                                                            className="w-full h-full object-cover opacity-80 group-hover:opacity-100 group-hover:scale-105 transition-all duration-500"
                                                        />
                                                    ) : (
                                                        <div className="absolute inset-0 bg-gradient-to-br from-slate-800 to-slate-900 flex items-center justify-center">
                                                            <Video size={48} className="text-slate-700 group-hover:text-slate-600 transition-colors" />
                                                        </div>
                                                    )}

                                                    {/* Delete Button */}
                                                    <div className="absolute top-3 right-3 z-20">
                                                        <button
                                                            onClick={(e) => {
                                                                e.preventDefault();
                                                                if (confirm('Delete this course?')) {
                                                                    contentService.deleteCourse(course.id).then(fetchData);
                                                                }
                                                            }}
                                                            className="p-2 bg-black/40 hover:bg-red-600/90 rounded-full text-white/70 hover:text-white backdrop-blur-md transition-all opacity-0 group-hover:opacity-100 transform scale-90 group-hover:scale-100"
                                                            title="Delete Course"
                                                        >
                                                            <Trash2 size={16} />
                                                        </button>
                                                    </div>

                                                    {/* Status Badge */}
                                                    <div className="absolute top-3 left-3">
                                                        <span className={`px-2.5 py-1 rounded-md text-[10px] font-bold uppercase tracking-wider ${course.isPublished
                                                                ? 'bg-emerald-500/90 text-white shadow-lg shadow-emerald-500/20'
                                                                : 'bg-amber-500/90 text-black shadow-lg shadow-amber-500/20'
                                                            }`}>
                                                            {course.isPublished ? 'Publicado' : 'Borrador'}
                                                        </span>
                                                    </div>
                                                </div>

                                                {/* Content */}
                                                <div className="p-5 flex-1 flex flex-col">
                                                    <div className="text-xs font-semibold text-indigo-400 mb-2 flex items-center gap-1.5 uppercase tracking-wide">
                                                        <FolderKanban size={12} />
                                                        {categoryName}
                                                    </div>

                                                    <h3 className="text-lg font-bold text-white mb-3 line-clamp-2 leading-tight group-hover:text-indigo-300 transition-colors">
                                                        {course.title}
                                                    </h3>

                                                    <div className="mt-auto flex items-center justify-between text-slate-400 text-xs border-t border-slate-700/50 pt-4">
                                                        <span className="flex items-center gap-1.5 font-medium">
                                                            <Folder size={14} className="text-slate-500" />
                                                            {course.modules?.length || 0} Módulos
                                                        </span>
                                                        <span className="flex items-center gap-1.5 text-indigo-400 group-hover:translate-x-1 transition-transform">
                                                            Gestionar
                                                            <BookOpen size={14} />
                                                        </span>
                                                    </div>
                                                </div>
                                            </div>
                                        </Link>
                                    ))}
                                </div>
                            </div>
                        );
                    })}
                </div>
            )}
        </div>
    );
}

'use client';

import { DollarSign, TrendingUp, CreditCard, Download, Loader2, Calendar, Filter, Search, X, ChevronLeft, ChevronRight, Eye } from 'lucide-react';
import { useEffect, useState } from 'react';
import { financeService, Payment, Subscription } from '@/services/finance.service';

const STATUS_COLORS: Record<string, string> = {
    APPROVED: 'bg-emerald-500/10 text-emerald-400 border border-emerald-500/20',
    PENDING: 'bg-amber-500/10 text-amber-400 border border-amber-500/20',
    DECLINED: 'bg-red-500/10 text-red-400 border border-red-500/20',
    ERROR: 'bg-red-500/10 text-red-400 border border-red-500/20',
    VOIDED: 'bg-slate-500/10 text-slate-400 border border-slate-500/20',
    active: 'bg-emerald-500/10 text-emerald-400 border border-emerald-500/20',
    past_due: 'bg-orange-500/10 text-orange-400 border border-orange-500/20',
    canceled: 'bg-slate-500/10 text-slate-400 border border-slate-500/20',
};

export default function FinancePage() {
    const [activeView, setActiveView] = useState<'transactions' | 'subscriptions'>('transactions');
    const [transactions, setTransactions] = useState<Payment[]>([]);
    const [subscriptions, setSubscriptions] = useState<Subscription[]>([]);
    const [loading, setLoading] = useState(true);
    const [totalRevenue, setTotalRevenue] = useState(0);
    const [activeSubscriptionsCount, setActiveSubscriptionsCount] = useState(0);

    // Filters & Pagination
    const [searchTerm, setSearchTerm] = useState('');
    const [statusFilter, setStatusFilter] = useState('all');
    const [planFilter, setPlanFilter] = useState('all');
    const [currentPage, setCurrentPage] = useState(1);
    const itemsPerPage = 10;

    // Modal
    const [selectedTransaction, setSelectedTransaction] = useState<Payment | null>(null);

    useEffect(() => {
        loadData();
    }, []);

    const loadData = async () => {
        setLoading(true);
        try {
            // Load ALL data initially to ensure KPIs are correct and client-side filtering works
            const [txData, subData] = await Promise.all([
                financeService.getAllPayments(),
                financeService.getAllSubscriptions()
            ]);

            const txItems = txData.items || [];
            const subItems = subData.items || [];

            setTransactions(txItems);
            setSubscriptions(subItems);

            // Calculate Metrics
            const revenue = txItems.reduce((acc, curr) =>
                curr.status === 'APPROVED' ? acc + Number(curr.amountInCents || 0) : acc, 0
            );
            setTotalRevenue(revenue / 100);

            const activeSubs = subItems.filter(s => s.status === 'active').length;
            setActiveSubscriptionsCount(activeSubs);

        } catch (error) {
            console.error('Failed to load data', error);
        } finally {
            setLoading(false);
        }
    };

    // Filter Logic
    const getFilteredData = () => {
        const sourceData = activeView === 'transactions' ? transactions : subscriptions;

        return sourceData.filter(item => {
            // Status Filter
            if (statusFilter !== 'all' && item.status !== statusFilter) return false;

            // Plan Filter
            // @ts-ignore
            const itemName = ((typeof item.plan === 'string' ? item.plan : item.plan?.name) || '').toLowerCase();
            // @ts-ignore
            if (planFilter !== 'all' && !itemName.includes(planFilter.toLowerCase())) return false;

            // Search Term
            if (searchTerm) {
                const term = searchTerm.toLowerCase();
                // @ts-ignore
                const searchString = `${item.id} ${item.userId} ${item.reference || ''} ${item.customerEmail || ''}`.toLowerCase();
                if (!searchString.includes(term)) return false;
            }

            return true;
        });
    };

    const filteredItems = getFilteredData();
    const totalPages = Math.ceil(filteredItems.length / itemsPerPage);
    const paginatedItems = filteredItems.slice((currentPage - 1) * itemsPerPage, currentPage * itemsPerPage);

    const formatCurrency = (amount: number) => {
        if (isNaN(amount)) return '$0.00';
        return new Intl.NumberFormat('es-CO', { style: 'currency', currency: 'COP', minimumFractionDigits: 0 }).format(amount);
    };

    const formatDate = (dateString: string) => {
        if (!dateString) return '-';
        return new Date(dateString).toLocaleDateString('es-ES', {
            year: 'numeric',
            month: 'long',
            day: 'numeric',
            hour: '2-digit',
            minute: '2-digit'
        });
    };

    // Extract Unique Plans for Filter
    const uniquePlans = Array.from(new Set([
        ...transactions.map(t => t.plan),
        ...subscriptions.map(s => s.plan?.name)
    ].filter(Boolean)));

    return (
        <div className="p-8 max-w-7xl mx-auto min-h-screen">
            <header className="mb-10 flex justify-between items-end">
                <div>
                    <h1 className="text-4xl font-bold bg-gradient-to-r from-emerald-400 via-teal-400 to-cyan-400 bg-clip-text text-transparent mb-2">
                        Finanzas & Suscripciones
                    </h1>
                    <p className="text-slate-400 text-lg">Control total de ingresos y membresías activas.</p>
                </div>
                <button className="flex items-center gap-2 bg-slate-800 text-slate-300 px-5 py-2.5 rounded-xl border border-slate-700 hover:bg-slate-700 hover:text-white transition-all shadow-lg">
                    <Download size={18} />
                    Exportar Informe
                </button>
            </header>

            {/* KPI Cards */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-10">
                <div className="relative overflow-hidden bg-slate-900/60 backdrop-blur-xl p-8 rounded-3xl border border-white/10 shadow-2xl group">
                    <div className="absolute -right-10 -top-10 w-40 h-40 bg-emerald-500/10 rounded-full blur-3xl group-hover:bg-emerald-500/20 transition-all duration-700"></div>
                    <div className="flex justify-between items-start mb-4 relative z-10">
                        <div>
                            <p className="text-slate-400 font-medium mb-1">Ingresos Totales (Histórico)</p>
                            <h3 className="text-4xl font-bold text-white tracking-tight">
                                {formatCurrency(totalRevenue)}
                            </h3>
                        </div>
                        <div className="p-3.5 rounded-2xl bg-gradient-to-br from-emerald-500/20 to-teal-500/20 text-emerald-400 border border-emerald-500/20 shadow-inner">
                            <DollarSign size={28} />
                        </div>
                    </div>
                    <div className="flex items-center gap-2 text-sm text-emerald-400/80 font-medium relative z-10">
                        <TrendingUp size={16} />
                        <span>Calculado de {transactions.filter(t => t.status === 'APPROVED').length} transacciones exitosas</span>
                    </div>
                </div>

                <div className="relative overflow-hidden bg-slate-900/60 backdrop-blur-xl p-8 rounded-3xl border border-white/10 shadow-2xl group">
                    <div className="absolute -right-10 -top-10 w-40 h-40 bg-blue-500/10 rounded-full blur-3xl group-hover:bg-blue-500/20 transition-all duration-700"></div>
                    <div className="flex justify-between items-start mb-4 relative z-10">
                        <div>
                            <p className="text-slate-400 font-medium mb-1">Suscripciones Activas</p>
                            <h3 className="text-4xl font-bold text-white tracking-tight">
                                {activeSubscriptionsCount}
                            </h3>
                        </div>
                        <div className="p-3.5 rounded-2xl bg-gradient-to-br from-blue-500/20 to-indigo-500/20 text-blue-400 border border-blue-500/20 shadow-inner">
                            <CreditCard size={28} />
                        </div>
                    </div>
                    <div className="flex items-center gap-2 text-sm text-blue-400/80 font-medium relative z-10">
                        <CreditCard size={16} />
                        <span>Usuarios con acceso vigente actualmente</span>
                    </div>
                </div>
            </div>

            {/* Main Content Area */}
            <div className="bg-slate-900/60 backdrop-blur-xl rounded-3xl border border-white/10 shadow-2xl overflow-hidden flex flex-col">

                {/* Controls Bar */}
                <div className="p-6 border-b border-white/5 flex flex-col xl:flex-row justify-between gap-6 bg-white/5">
                    {/* View Switcher */}
                    <div className="flex bg-slate-950/50 rounded-xl p-1.5 w-fit border border-white/5">
                        <button
                            onClick={() => { setActiveView('transactions'); setCurrentPage(1); }}
                            className={`px-6 py-2.5 rounded-lg text-sm font-bold transition-all ${activeView === 'transactions'
                                ? 'bg-slate-800 text-white shadow-md'
                                : 'text-slate-400 hover:text-white hover:bg-white/5'
                                }`}
                        >
                            Transacciones
                        </button>
                        <button
                            onClick={() => { setActiveView('subscriptions'); setCurrentPage(1); }}
                            className={`px-6 py-2.5 rounded-lg text-sm font-bold transition-all ${activeView === 'subscriptions'
                                ? 'bg-slate-800 text-white shadow-md'
                                : 'text-slate-400 hover:text-white hover:bg-white/5'
                                }`}
                        >
                            Suscripciones
                        </button>
                    </div>

                    {/* Filters */}
                    <div className="flex flex-wrap gap-4 flex-1 justify-end">
                        {/* Search */}
                        <div className="relative min-w-[240px]">
                            <Search className="absolute left-3.5 top-3 h-4 w-4 text-slate-500" />
                            <input
                                type="text"
                                placeholder="Buscar reference, email..."
                                value={searchTerm}
                                onChange={(e) => setSearchTerm(e.target.value)}
                                className="w-full bg-slate-950/50 border border-white/10 text-slate-200 text-sm rounded-xl pl-10 pr-4 py-2.5 focus:ring-2 focus:ring-emerald-500/50 focus:border-emerald-500/50 outline-none transition-all placeholder:text-slate-600"
                            />
                        </div>

                        {/* Plan Filter */}
                        <div className="relative">
                            <Filter className="absolute left-3.5 top-3 h-4 w-4 text-slate-500" />
                            <select
                                value={planFilter}
                                onChange={(e) => setPlanFilter(e.target.value)}
                                className="bg-slate-950/50 border border-white/10 text-slate-300 text-sm rounded-xl pl-10 pr-8 py-2.5 focus:ring-2 focus:ring-emerald-500/50 outline-none appearance-none cursor-pointer hover:bg-slate-900/80 transition-all"
                            >
                                <option value="all">Todos los planes</option>
                                {uniquePlans.map((plan: any) => (
                                    <option key={plan} value={plan}>{plan.replace(/_/g, ' ')}</option>
                                ))}
                            </select>
                        </div>

                        {/* Status Filter */}
                        <div className="relative">
                            <div className={`absolute top-3.5 left-3 w-2 h-2 rounded-full ${statusFilter === 'all' ? 'bg-slate-500' : 'bg-emerald-500'}`}></div>
                            <select
                                value={statusFilter}
                                onChange={(e) => setStatusFilter(e.target.value)}
                                className="bg-slate-950/50 border border-white/10 text-slate-300 text-sm rounded-xl pl-8 pr-8 py-2.5 focus:ring-2 focus:ring-emerald-500/50 outline-none appearance-none cursor-pointer hover:bg-slate-900/80 transition-all capitalize"
                            >
                                <option value="all">Todos ({filteredItems.length})</option>
                                {Object.keys(STATUS_COLORS).map(status => (
                                    <option key={status} value={status}>{status}</option>
                                ))}
                            </select>
                        </div>
                    </div>
                </div>

                {/* Table Area */}
                <div className="overflow-x-auto min-h-[400px]">
                    {loading ? (
                        <div className="h-full flex flex-col justify-center items-center p-20 gap-4">
                            <Loader2 className="animate-spin text-emerald-500 w-10 h-10" />
                            <p className="text-slate-500">Cargando datos financieros...</p>
                        </div>
                    ) : (
                        <table className="w-full text-left border-collapse">
                            <thead className="bg-slate-950/30 text-slate-400 uppercase text-xs font-bold tracking-wider">
                                <tr>
                                    <th className="px-8 py-5">
                                        {activeView === 'transactions' ? 'Referencia / Wompi ID' : 'ID Suscripción / Usuario'}
                                    </th>
                                    <th className="px-6 py-5">Cliente</th>
                                    <th className="px-6 py-5">Plan Adquirido</th>
                                    <th className="px-6 py-5">
                                        {activeView === 'transactions' ? 'Fecha Transacción' : 'Vencimiento'}
                                    </th>
                                    <th className="px-6 py-5 text-right">Monto</th>
                                    <th className="px-6 py-5 text-center">Estado</th>
                                    {activeView === 'transactions' && <th className="px-6 py-5 text-center">Acciones</th>}
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-white/5">
                                {paginatedItems.length === 0 ? (
                                    <tr>
                                        <td colSpan={7} className="p-12 text-center">
                                            <div className="flex flex-col items-center gap-3">
                                                <Search size={40} className="text-slate-700" />
                                                <p className="text-slate-400 font-medium">No se encontraron resultados</p>
                                                <p className="text-sm text-slate-500">Intenta ajustar los filtros de búsqueda</p>
                                            </div>
                                        </td>
                                    </tr>
                                ) : (
                                    paginatedItems.map((item: any) => (
                                        <tr key={item.id} className="hover:bg-white/[0.02] transition-colors group">
                                            {/* ID Column */}
                                            <td className="px-8 py-5">
                                                <div className="flex flex-col gap-1">
                                                    <span className="text-slate-200 font-mono text-xs tracking-wide">
                                                        {activeView === 'transactions'
                                                            ? (item.reference || 'N/A').substring(0, 20) + '...'
                                                            : item.id.substring(0, 12) + '...'
                                                        }
                                                    </span>
                                                    {activeView === 'transactions' && item.wompiTransactionId && (
                                                        <span className="text-xs text-emerald-500/60 font-mono flex items-center gap-1">
                                                            <div className="w-1.5 h-1.5 rounded-full bg-emerald-500/50"></div>
                                                            {item.wompiTransactionId}
                                                        </span>
                                                    )}
                                                </div>
                                            </td>

                                            {/* Customer Column */}
                                            <td className="px-6 py-5">
                                                {activeView === 'transactions' ? (
                                                    <div>
                                                        <div className="text-white font-medium text-sm">{item.customerName || 'Cliente Desconocido'}</div>
                                                        <div className="text-slate-500 text-xs">{item.customerEmail}</div>
                                                    </div>
                                                ) : (
                                                    <div className="text-slate-400 font-mono text-xs bg-slate-900/50 px-2 py-1 rounded w-fit border border-white/5">
                                                        User: {item.userId.substring(0, 8)}
                                                    </div>
                                                )}
                                            </td>

                                            {/* Plan Column */}
                                            <td className="px-6 py-5">
                                                <span className="text-slate-300 text-sm font-medium px-2.5 py-1 rounded bg-white/5 border border-white/5">
                                                    {((typeof item.plan === 'string' ? item.plan : item.plan?.name) || 'Standard').replace(/_/g, ' ')}
                                                </span>
                                            </td>

                                            {/* Date Column */}
                                            <td className="px-6 py-5 text-slate-400 text-sm">
                                                {activeView === 'transactions'
                                                    ? formatDate(item.createdAt)
                                                    : formatDate(item.currentPeriodEnd)
                                                }
                                            </td>

                                            {/* Amount Column */}
                                            <td className="px-6 py-5 text-right font-mono text-slate-200">
                                                {formatCurrency((item.amountInCents || item.amountCents || 0) / 100)}
                                            </td>

                                            {/* Status Column */}
                                            <td className="px-6 py-5">
                                                <div className="flex justify-center">
                                                    <span className={`px-3 py-1 rounded-full text-[10px] font-bold uppercase tracking-wider ${STATUS_COLORS[item.status] || 'bg-slate-500/10 text-slate-400'}`}>
                                                        {item.status}
                                                    </span>
                                                </div>
                                            </td>

                                            {/* Actions Column (Transactions Only) */}
                                            {activeView === 'transactions' && (
                                                <td className="px-6 py-5 text-center">
                                                    <button
                                                        onClick={() => setSelectedTransaction(item)}
                                                        className="p-2 text-slate-500 hover:text-emerald-400 hover:bg-emerald-500/10 rounded-lg transition-all"
                                                        title="Ver detalles"
                                                    >
                                                        <Eye size={18} />
                                                    </button>
                                                </td>
                                            )}
                                        </tr>
                                    ))
                                )}
                            </tbody>
                        </table>
                    )}
                </div>

                {/* Pagination Controls */}
                <div className="p-4 border-t border-white/5 flex items-center justify-between bg-slate-950/30">
                    <span className="text-sm text-slate-500">
                        Mostrando <span className="text-white font-medium">{paginatedItems.length}</span> de <span className="text-white font-medium">{filteredItems.length}</span> resultados
                    </span>

                    <div className="flex items-center gap-2">
                        <button
                            onClick={() => setCurrentPage(prev => Math.max(prev - 1, 1))}
                            disabled={currentPage === 1}
                            className="p-2 rounded-lg text-slate-400 hover:text-white hover:bg-white/5 disabled:opacity-30 disabled:hover:bg-transparent transition-all"
                        >
                            <ChevronLeft size={18} />
                        </button>

                        <div className="flex items-center gap-1">
                            {Array.from({ length: Math.min(5, totalPages) }, (_, i) => {
                                // Logic for simplified sliding window could go here, for now simple first 5
                                let pageNum = i + 1;
                                if (totalPages > 5 && currentPage > 3) {
                                    pageNum = currentPage - 2 + i;
                                }
                                if (pageNum > totalPages) return null;

                                return (
                                    <button
                                        key={pageNum}
                                        onClick={() => setCurrentPage(pageNum)}
                                        className={`w-8 h-8 rounded-lg text-xs font-bold transition-all ${currentPage === pageNum
                                            ? 'bg-emerald-600 text-white shadow-lg shadow-emerald-900/50'
                                            : 'text-slate-500 hover:bg-white/5 hover:text-slate-300'
                                            }`}
                                    >
                                        {pageNum}
                                    </button>
                                );
                            })}
                        </div>

                        <button
                            onClick={() => setCurrentPage(prev => Math.min(prev + 1, totalPages))}
                            disabled={currentPage === totalPages || totalPages === 0}
                            className="p-2 rounded-lg text-slate-400 hover:text-white hover:bg-white/5 disabled:opacity-30 disabled:hover:bg-transparent transition-all"
                        >
                            <ChevronRight size={18} />
                        </button>
                    </div>
                </div>
            </div>

            {/* Transaction Detail Modal */}
            {selectedTransaction && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
                    <div className="bg-slate-900 border border-white/10 rounded-2xl shadow-2xl w-full max-w-lg overflow-hidden animate-in fade-in zoom-in duration-200">
                        <div className="p-6 border-b border-white/5 flex justify-between items-center bg-white/5">
                            <div>
                                <h3 className="text-xl font-bold text-white">Detalle de Transacción</h3>
                                <p className="text-slate-400 text-sm mt-0.5 font-mono">{selectedTransaction.reference}</p>
                            </div>
                            <button
                                onClick={() => setSelectedTransaction(null)}
                                className="text-slate-500 hover:text-white transition-colors"
                            >
                                <X size={24} />
                            </button>
                        </div>

                        <div className="p-6 space-y-6">
                            <div className="grid grid-cols-2 gap-4">
                                <div className="p-4 rounded-xl bg-slate-950/50 border border-white/5">
                                    <span className="text-xs text-slate-500 uppercase font-bold tracking-wider">Monto</span>
                                    <p className="text-2xl font-mono text-white mt-1">
                                        {formatCurrency((selectedTransaction.amountInCents || 0) / 100)}
                                    </p>
                                </div>
                                <div className="p-4 rounded-xl bg-slate-950/50 border border-white/5">
                                    <span className="text-xs text-slate-500 uppercase font-bold tracking-wider">Estado</span>
                                    <div className="mt-2">
                                        <span className={`px-3 py-1 rounded-full text-xs font-bold uppercase tracking-wider ${STATUS_COLORS[selectedTransaction.status]}`}>
                                            {selectedTransaction.status}
                                        </span>
                                    </div>
                                </div>
                            </div>

                            <div className="space-y-4">
                                <DetailRow label="Fecha" value={formatDate(selectedTransaction.createdAt)} />
                                <DetailRow label="Wompi ID" value={selectedTransaction.wompiTransactionId || 'N/A'} isMono />
                                <DetailRow label="Plan Adquirido" value={selectedTransaction.plan} />
                                <div className="h-px bg-white/5 my-2"></div>
                                <h4 className="text-sm font-bold text-slate-300">Información del Cliente</h4>
                                <DetailRow label="Nombre" value={selectedTransaction.customerName || 'N/A'} />
                                <DetailRow label="Email" value={selectedTransaction.customerEmail || 'N/A'} />
                                <DetailRow label="Teléfono" value={selectedTransaction.customerPhone || 'N/A'} />
                            </div>
                        </div>

                        <div className="p-6 border-t border-white/5 bg-slate-950/30 flex justify-end">
                            <button
                                onClick={() => setSelectedTransaction(null)}
                                className="px-5 py-2 rounded-lg bg-slate-800 text-white font-medium hover:bg-slate-700 transition-colors"
                            >
                                Cerrar
                            </button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
}

function DetailRow({ label, value, isMono = false }: { label: string, value: string | undefined, isMono?: boolean }) {
    return (
        <div className="flex justify-between items-center group">
            <span className="text-slate-500 text-sm font-medium">{label}</span>
            <span className={`text-slate-200 text-sm ${isMono ? 'font-mono' : ''} select-all`}>
                {value}
            </span>
        </div>
    );
}

import { FileText } from 'lucide-react';

interface FormFieldRendererProps {
    fieldKey: string;
    value: any;
}

export function FormFieldRenderer({ fieldKey, value }: FormFieldRendererProps) {
    if (value === null || value === undefined) {
        return <span className="text-slate-500 italic">No especificado</span>;
    }

    // Handle arrays
    if (Array.isArray(value)) {
        return (
            <div className="flex flex-wrap gap-2">
                {value.map((item, index) => (
                    <span
                        key={index}
                        className="px-2 py-1 bg-blue-600/20 text-blue-300 rounded text-sm"
                    >
                        {String(item)}
                    </span>
                ))}
            </div>
        );
    }

    // Handle objects (like hojaVida, certificaciones)
    if (typeof value === 'object') {
        // Check if it's a file object (has name, size, type properties)
        if (value.name || value.size || value.type) {
            const fileName = value.name || 'Archivo sin nombre';
            const fileSize = value.size ? `${(value.size / 1024).toFixed(2)} KB` : '';
            const fileType = value.type || 'Tipo desconocido';
            
            return (
                <div className="space-y-2">
                    {value.url ? (
                        <a
                            href={value.url}
                            target="_blank"
                            rel="noopener noreferrer"
                            className="inline-flex items-center gap-2 text-blue-400 hover:text-blue-300 underline transition-colors"
                        >
                            <FileText size={16} />
                            <span>{fileName}</span>
                            <span className="text-xs text-slate-500">({fileSize})</span>
                        </a>
                    ) : (
                        <div className="flex items-center gap-2 text-slate-300">
                            <FileText size={16} className="text-slate-500" />
                            <span>{fileName}</span>
                            {fileSize && <span className="text-xs text-slate-500">({fileSize})</span>}
                        </div>
                    )}
                    {!value.url && fileType && (
                        <div className="text-xs text-slate-500">
                            Tipo: {fileType}
                        </div>
                    )}
                </div>
            );
        }
        // For other objects, show as formatted JSON
        return (
            <pre className="text-xs bg-slate-800 p-2 rounded overflow-x-auto">
                {JSON.stringify(value, null, 2)}
            </pre>
        );
    }

    // Handle boolean values
    if (typeof value === 'boolean') {
        return (
            <span className={`px-2 py-1 rounded text-sm ${value ? 'bg-green-600/20 text-green-300' : 'bg-red-600/20 text-red-300'}`}>
                {value ? 'Sí' : 'No'}
            </span>
        );
    }

    // Handle string values with special formatting
    const stringValue = String(value);
    if (stringValue.toLowerCase() === 'si' || stringValue.toLowerCase() === 'sí') {
        return (
            <span className="px-2 py-1 bg-green-600/20 text-green-300 rounded text-sm">
                Sí
            </span>
        );
    }
    if (stringValue.toLowerCase() === 'no') {
        return (
            <span className="px-2 py-1 bg-red-600/20 text-red-300 rounded text-sm">
                No
            </span>
        );
    }

    return <span>{stringValue}</span>;
}

import { useState } from 'react';
import { FormSubmission } from '../types';
import { formTypeLabels } from '../constants';
import { formatDate, exportToExcel } from '../utils';
import { OrganizedDataRenderer } from './OrganizedDataRenderer';
import { CheckCircle, AlertTriangle, UserCheck, XCircle } from 'lucide-react';
import { usersService } from '@/services/users.service';
import { FORMS_ENDPOINTS, buildUrl } from '@/config/api.config';

interface FormSubmissionModalProps {
    submission: FormSubmission;
    onClose: () => void;
    onDeleted?: () => void;
}

export function FormSubmissionModal({ submission, onClose, onDeleted }: FormSubmissionModalProps) {
    const [isPromoting, setIsPromoting] = useState(false);
    const [isRejecting, setIsRejecting] = useState(false);
    const [isDownloadingExcel, setIsDownloadingExcel] = useState(false);
    const [promoteError, setPromoteError] = useState<string | null>(null);
    const [rejectError, setRejectError] = useState<string | null>(null);
    const [promoteSuccess, setPromoteSuccess] = useState(false);
    const [rejectSuccess, setRejectSuccess] = useState(false);

    const isInterpreterForm = submission.form?.type === 'interpreter_registration';

    const handlePromote = async () => {
        const email = submission.email || submission.data?.correoElectronico;
        if (!email) {
            setPromoteError('No se encontró un email válido en el formulario para realizar la aprobación.');
            return;
        }

        if (!confirm(`¿Estás seguro de aprobar a ${submission.data?.nombreCompleto || email} como Intérprete? Esto actualizará su rol de usuario.`)) return;

        setIsPromoting(true);
        setPromoteError(null);
        try {
            await usersService.promoteToInterpreter(email);
            setPromoteSuccess(true);
        } catch (err: any) {
            setPromoteError(err.message || 'Error al promover usuario');
        } finally {
            setIsPromoting(false);
        }
    };

    const handleReject = async () => {
        if (!confirm(`¿Estás seguro de rechazar esta solicitud? Se eliminará el registro del formulario.`)) return;

        setIsRejecting(true);
        setRejectError(null);
        try {
            const response = await fetch(`${buildUrl(FORMS_ENDPOINTS.DELETE_SUBMISSION)}/${submission.id}`, {
                method: 'DELETE',
                headers: {
                    'Authorization': `Bearer ${localStorage.getItem('tincadia_token')}`
                }
            });

            if (!response.ok) {
                const data = await response.json();
                throw new Error(data.message || 'Error al eliminar la solicitud');
            }

            setRejectSuccess(true);
            if (onDeleted) {
                setTimeout(() => {
                    onDeleted();
                    onClose();
                }, 1500);
            }
        } catch (err: any) {
            setRejectError(err.message || 'Error al rechazar solicitud');
        } finally {
            setIsRejecting(false);
        }
    };

    const handleDownloadExcel = () => {
        setIsDownloadingExcel(true);
        try {
            const name = submission.fullName || submission.data?.nombreCompleto || 'submission';
            const safeDate = new Date().toISOString().split('T')[0];
            exportToExcel([submission], `tincadia_${name.replace(/\s+/g, '_')}_${safeDate}.xlsx`);
        } finally {
            setIsDownloadingExcel(false);
        }
    };

    return (
        <div className="fixed inset-0 bg-black/60 flex items-center justify-center z-50 p-4">
            <div className="bg-slate-800 rounded-xl border border-slate-700 max-w-4xl w-full max-h-[90vh] overflow-hidden flex flex-col">
                {/* Header */}
                <div className="flex items-center justify-between p-4 border-b border-slate-700 shrink-0">
                    <h2 className="text-lg font-semibold text-white">
                        {submission.form?.title || 'Detalles del Formulario'}
                    </h2>
                    <button
                        onClick={onClose}
                        className="text-slate-400 hover:text-white text-xl"
                    >
                        ✕
                    </button>
                </div>

                {/* Body */}
                <div className="p-6 overflow-y-auto grow">
                    <div className="space-y-6">
                        {/* Header Info */}
                        <div className="grid grid-cols-2 gap-4">
                            <div>
                                <span className="text-slate-400 text-sm">Tipo:</span>
                                <span className="ml-2 px-3 py-1 bg-blue-600/20 text-blue-400 rounded-full text-sm">
                                    {formTypeLabels[submission.form?.type] || submission.form?.type}
                                </span>
                            </div>
                            <div>
                                <span className="text-slate-400 text-sm">Fecha:</span>
                                <span className="ml-2 text-white">{formatDate(submission.createdAt)}</span>
                            </div>
                        </div>

                        {/* Quick info */}
                        <div className="grid grid-cols-2 gap-4 p-4 bg-slate-900/50 rounded-lg">
                            <div>
                                <span className="text-xs text-slate-500 uppercase">Nombre</span>
                                <p className="text-white font-medium">{submission.fullName || submission.data?.nombreCompleto || 'N/A'}</p>
                            </div>
                            <div>
                                <span className="text-xs text-slate-500 uppercase">Email</span>
                                <p className="text-white font-medium">{submission.email || submission.data?.correoElectronico || 'N/A'}</p>
                            </div>
                            <div>
                                <span className="text-xs text-slate-500 uppercase">Teléfono</span>
                                <p className="text-white font-medium">{submission.phone || submission.data?.telefono || submission.data?.telefonoWhatsapp || 'N/A'}</p>
                            </div>
                            <div>
                                <span className="text-xs text-slate-500 uppercase">Documento</span>
                                <p className="text-white font-medium">{submission.documentNumber || submission.data?.documentoIdentidad || 'N/A'}</p>
                            </div>
                        </div>

                        {/* Actions for Interpreter */}
                        {isInterpreterForm && (
                            <div className="bg-slate-900/50 p-4 rounded-lg border border-slate-700">
                                <h3 className="text-sm font-medium text-white mb-2 flex items-center gap-2">
                                    <UserCheck size={16} />
                                    Gestión de Solicitud
                                </h3>

                                {promoteSuccess ? (
                                    <div className="bg-green-900/30 text-green-400 p-3 rounded-lg flex items-center gap-2">
                                        <CheckCircle size={18} />
                                        <span>Solicitud aprobada. El usuario ahora es Intérprete.</span>
                                    </div>
                                ) : rejectSuccess ? (
                                    <div className="bg-red-900/30 text-red-400 p-3 rounded-lg flex items-center gap-2">
                                        <XCircle size={18} />
