        } finally {
            setLoading(false);
        }
    };

    const generateRandomColor = () => {
        const colors = [
            '#3b82f6', // blue
            '#ef4444', // red
            '#10b981', // green
            '#f59e0b', // yellow
            '#8b5cf6', // purple
            '#ec4899', // pink
            '#06b6d4', // cyan
            '#f97316'  // orange
        ];
        return colors[Math.floor(Math.random() * colors.length)];
    };

    const handleCreate = async () => {
        if (!label) return;
        try {
            setCreating(true);

            // Auto-generate ID from label
            // "Nueva Oferta" -> "nueva_oferta_" + random suffix to prevent collisions
            const generatedName = label.toLowerCase().replace(/[^a-z0-9]/g, '_') + '_' + Math.random().toString(36).substr(2, 4);
            const generatedColor = generateRandomColor();

            await notificationsService.createCategory({
                name: generatedName,
                label,
                color: generatedColor,
                icon: 'Tag'
            });
            setLabel('');
            fetchCategories();
            onUpdate();
        } catch (error) {
            alert('Error al crear categoría');
        } finally {
            setCreating(false);
        }
    };

    const handleDelete = async (id: string) => {
        if (!confirm('¿Eliminar este tipo de comunicación?')) return;
        try {
            await notificationsService.deleteCategory(id);
            setCategories(prev => prev.filter(c => c.id !== id));
            onUpdate();
        } catch (error) {
            alert('Error al eliminar');
        }
    };

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4 backdrop-blur-sm">
            <div className="bg-slate-900 rounded-xl border border-slate-700 w-full max-w-md shadow-2xl overflow-hidden">
                <div className="p-4 border-b border-slate-700 flex justify-between items-center bg-slate-800">
                    <h3 className="font-bold text-white flex items-center gap-2">
                        <Tag size={18} className="text-blue-400" />
                        Gestionar Tipos
                    </h3>
                    <button onClick={onClose} className="text-slate-400 hover:text-white">
                        <X size={20} />
                    </button>
                </div>

                <div className="p-4 space-y-4">
                    {/* Add Form */}
                    <div className="space-y-3 bg-slate-800/50 p-3 rounded-lg border border-slate-700">
                        <h4 className="text-xs font-bold text-slate-400 uppercase tracking-wider">Crear Nuevo Tipo</h4>
                        <div className="flex gap-2">
                            <input
                                placeholder="Nombre de la categoría (ej: Urgente)"
                                value={label}
                                onChange={e => setLabel(e.target.value)}
                                className="flex-1 bg-slate-950 border border-slate-700 rounded p-2 text-sm text-white focus:ring-1 focus:ring-blue-500 outline-none"
                            />
                            <button
                                onClick={handleCreate}
                                disabled={creating || !label}
                                className="bg-blue-600 hover:bg-blue-500 text-white text-sm px-4 rounded flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed"
                            >
                                {creating ? <Loader2 className="animate-spin" size={16} /> : <Plus size={16} />}
                                <span className="hidden sm:inline">Agregar</span>
                            </button>
                        </div>
                    </div>

                    {/* List */}
                    <div className="max-h-60 overflow-y-auto space-y-2">
                        {loading && <div className="text-center p-4"><Loader2 className="animate-spin text-blue-500 mx-auto" /></div>}

                        {!loading && categories.length === 0 && (
                            <p className="text-center text-slate-500 text-sm py-4">No hay tipos personalizados.</p>
                        )}

                        {!loading && categories.map(cat => (
                            <div key={cat.id} className="flex items-center justify-between p-3 bg-slate-800 rounded border border-slate-700">
                                <div className="flex items-center gap-3">
                                    <div className="w-3 h-3 rounded-full shadow-sm" style={{ backgroundColor: cat.color }} />
                                    <div>
                                        <p className="text-sm font-medium text-white">{cat.label}</p>
                                    </div>
                                </div>
                                <div className="flex items-center gap-2">
                                    {/* Could add valid color picker later if needed */}
                                    <button onClick={() => handleDelete(cat.id)} className="text-slate-500 hover:text-red-400 p-1">
                                        <Trash2 size={16} />
                                    </button>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            </div>
        </div>
    );
}

'use client';

import { Bell, Send, Clock, Trash2, Loader2, Megaphone, Info, Tag, Settings, Plus } from 'lucide-react';
import { useEffect, useState } from 'react';
import { notificationsService, AppNotification, NotificationCategory } from '@/services/notifications.service';
import ManageCategoriesModal from './ManageCategoriesModal';

export default function NotificationsPage() {
    const [notifications, setNotifications] = useState<AppNotification[]>([]);
    const [categories, setCategories] = useState<NotificationCategory[]>([]);
    const [loading, setLoading] = useState(true);

    // Form State
    const [title, setTitle] = useState('');
    const [message, setMessage] = useState('');
    const [selectedCategoryId, setSelectedCategoryId] = useState('');
    const [type, setType] = useState('news'); // Fallback type
    const [isPush, setIsPush] = useState(false);
    const [sending, setSending] = useState(false);

    // Modal State
    const [showManageModal, setShowManageModal] = useState(false);

    useEffect(() => {
        fetchData();
    }, []);

    const fetchData = async () => {
        try {
            setLoading(true);
            const [notifsData, catsData] = await Promise.all([
                notificationsService.getAllNotifications(),
                notificationsService.getCategories()
            ]);
            setNotifications(notifsData);
            setCategories(catsData);

            // Set default category if available
            if (catsData.length > 0 && !selectedCategoryId) {
                setSelectedCategoryId(catsData[0].id);
            }
        } catch (error) {
            console.error('Error al cargar datos', error);
        } finally {
            setLoading(false);
        }
    };

    const refreshCategories = async () => {
        const cats = await notificationsService.getCategories();
        setCategories(cats);
    };

    const handleSend = async () => {
        if (!title || !message) return;
        try {
            setSending(true);
            // Find selected category to get fallback type name
            const selectedCat = categories.find(c => c.id === selectedCategoryId);

            await notificationsService.createNotification({
                title,
                message,
                categoryId: selectedCategoryId,
                type: 'news', // Strict Type for DB Constraint
                priority: isPush ? 10 : 0,
                sendPush: isPush,
            });

            // Reset form
            setTitle('');
            setMessage('');
            setIsPush(false);
            fetchData(); // Refresh list
        } catch (error) {
            alert('Error al enviar la notificación');
        } finally {
            setSending(false);
        }
    };

    const handleDelete = async (id: string) => {
        if (!confirm('¿Estás seguro de eliminar esta notificación?')) return;
        try {
            await notificationsService.deleteNotification(id);
            setNotifications(prev => prev.filter(n => n.id !== id));
        } catch (error) {
            alert('Error al eliminar');
        }
    };

    return (
        <div className="p-8 max-w-7xl mx-auto">
            <header className="mb-10 flex flex-col gap-2">
                <h1 className="text-4xl font-bold bg-gradient-to-r from-blue-400 via-indigo-400 to-purple-400 bg-clip-text text-transparent">
                    Centro de Comunicaciones
                </h1>
                <p className="text-slate-400 text-lg">Gestiona y envía notificaciones a todos tus usuarios.</p>
            </header>

            <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
                {/* Create Notification Form - Takes up 4 columns */}
                <div className="lg:col-span-4 space-y-6">
                    <div className="bg-slate-900/60 backdrop-blur-xl p-8 rounded-3xl border border-white/10 shadow-2xl relative overflow-hidden group">
                        {/* Decorative gradient blob */}
                        <div className="absolute -top-20 -right-20 w-40 h-40 bg-indigo-500/20 rounded-full blur-3xl group-hover:bg-indigo-500/30 transition-all duration-1000"></div>

                        <h2 className="text-2xl font-bold text-white mb-6 flex items-center gap-3 relative z-10">
                            <div className="p-2.5 bg-indigo-500/20 rounded-xl text-indigo-400 border border-indigo-500/20">
                                <Send size={22} />
                            </div>
                            Nueva Comunicación
                        </h2>

                        <div className="space-y-6 relative z-10">
                            <div className="space-y-2">
                                <label className="text-sm font-medium text-slate-300 ml-1">Título del Mensaje</label>
                                <input
                                    type="text"
                                    value={title}
                                    onChange={(e) => setTitle(e.target.value)}
                                    className="w-full bg-slate-950/50 border border-white/10 rounded-xl p-3.5 text-white placeholder:text-slate-600 focus:ring-2 focus:ring-indigo-500/50 focus:border-indigo-500/50 transition-all outline-none"
                                    placeholder="Ej: ¡Nueva Actualización Disponible!"
                                />
                            </div>

                            <div className="space-y-2">
                                <label className="text-sm font-medium text-slate-300 ml-1">Contenido</label>
                                <textarea
                                    value={message}
                                    onChange={(e) => setMessage(e.target.value)}
                                    className="w-full bg-slate-950/50 border border-white/10 rounded-xl p-3.5 text-white placeholder:text-slate-600 focus:ring-2 focus:ring-indigo-500/50 focus:border-indigo-500/50 h-32 resize-none transition-all outline-none"
                                    placeholder="Escribe aquí tu mensaje..."
                                />
                            </div>

                            <div className="space-y-2">
                                <div className="flex justify-between items-center px-1">
                                    <label className="text-sm font-medium text-slate-300">Categoría</label>
                                    <button
                                        onClick={() => setShowManageModal(true)}
                                        className="text-xs text-indigo-400 hover:text-indigo-300 flex items-center gap-1 font-medium hover:underline transition-all"
                                    >
                                        <Settings size={12} /> Gestionar
                                    </button>
                                </div>
                                <div className="relative group/select">
                                    <Tag className="absolute left-3.5 top-3.5 text-slate-500 group-focus-within/select:text-indigo-400 transition-colors" size={18} />
                                    <select
                                        value={selectedCategoryId}
                                        onChange={(e) => setSelectedCategoryId(e.target.value)}
                                        className="w-full bg-slate-950/50 border border-white/10 rounded-xl p-3.5 pl-11 text-white appearance-none focus:ring-2 focus:ring-indigo-500/50 focus:border-indigo-500/50 transition-all outline-none cursor-pointer"
                                    >
                                        <option value="">📰 General (Por defecto)</option>
                                        {categories.map(cat => (
                                            <option key={cat.id} value={cat.id}>
                                                {cat.label}
                                            </option>
                                        ))}
                                    </select>
                                    <div className="absolute right-3.5 top-3.5 pointer-events-none text-slate-500">
                                        <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polyline points="6 9 12 15 18 9"></polyline></svg>
                                    </div>
                                </div>
                            </div>

                            <div className="p-4 bg-indigo-900/10 rounded-xl border border-indigo-500/20 hover:bg-indigo-900/20 transition-colors cursor-pointer" onClick={() => setIsPush(!isPush)}>
                                <div className="flex items-start gap-4">
                                    <div className={`mt-0.5 w-5 h-5 rounded border flex items-center justify-center transition-colors ${isPush ? 'bg-indigo-500 border-indigo-500' : 'border-slate-500 bg-transparent'}`}>
                                        {isPush && <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" className="text-white"><polyline points="20 6 9 17 4 12"></polyline></svg>}
                                    </div>
                                    <div className="flex-1">
                                        <span className="block text-white font-medium text-sm">Notificación Push</span>
                                        <span className="block text-indigo-200/60 text-xs mt-1 leading-relaxed">
                                            Envía una alerta instantánea a los dispositivos móviles de todos los usuarios.
                                        </span>
                                    </div>
                                </div>
                            </div>

                            <button
                                onClick={handleSend}
                                disabled={sending || !title || !message}
                                className="w-full bg-gradient-to-r from-blue-600 to-violet-600 hover:from-blue-500 hover:to-violet-500 text-white font-bold py-4 rounded-xl flex items-center justify-center gap-2.5 transition-all disabled:opacity-50 disabled:cursor-not-allowed shadow-lg shadow-indigo-500/20 hover:shadow-indigo-500/40 active:scale-[0.98] mt-4"
                            >
                                {sending ? <Loader2 className="animate-spin" size={20} /> : <Megaphone size={20} />}
                                {sending ? 'Enviando...' : 'Publicar Ahora'}
                            </button>
                        </div>
                    </div>
                </div>

                {/* History List - Takes up 8 columns */}
                <div className="lg:col-span-8 space-y-6">
                    <div className="bg-slate-900/60 backdrop-blur-xl rounded-3xl border border-white/10 shadow-2xl flex flex-col h-[700px] overflow-hidden relative">
                        {/* Header */}
                        <div className="p-6 border-b border-white/5 flex justify-between items-center bg-white/5 backdrop-blur-md sticky top-0 z-20">
                            <h2 className="text-lg font-bold text-white flex items-center gap-2">
                                <Clock size={18} className="text-indigo-400" />
                                Historial Reciente
                            </h2>
                            <span className="text-xs font-bold px-3 py-1 bg-slate-800 text-slate-300 rounded-full border border-white/5">
                                {notifications.length} Mensajes
                            </span>
                        </div>

                        {/* List Area */}
                        <div className="flex-1 overflow-y-auto p-6 scrollbar-thin scrollbar-thumb-slate-700 scrollbar-track-transparent">
                            {loading ? (
                                <div className="h-full flex flex-col items-center justify-center gap-4 text-slate-500">
                                    <Loader2 className="animate-spin text-indigo-500" size={40} />
                                    <p className="text-sm font-medium">Sincronizando historial...</p>
                                </div>
                            ) : (
                                <div className="space-y-4">
                                    {notifications.map((notif) => {
                                        const cat = notif.category;
                                        const catLabel = cat?.label || notif.type;
                                        const catColor = cat?.color || '#6366f1'; // Default Indigo

                                        return (
                                            <div
                                                key={notif.id}
                                                className="group relative bg-slate-950/40 hover:bg-slate-900/60 border border-white/5 hover:border-indigo-500/30 rounded-2xl p-5 transition-all duration-300 hover:shadow-lg hover:shadow-indigo-500/5"
                                            >
                                                <div className="flex items-start gap-5">
                                                    {/* Category Icon Box */}
                                                    <div
                                                        className="p-3.5 rounded-2xl flex-shrink-0 transition-transform group-hover:scale-105 duration-300 shadow-inner"
                                                        style={{
                                                            backgroundColor: `${catColor}15`, // 15% opacity bg
                                                            color: catColor
                                                        }}
                                                    >
                                                        <Bell size={24} strokeWidth={2} />
                                                    </div>

                                                    <div className="flex-1 min-w-0 pt-1">
                                                        <div className="flex justify-between items-start mb-2">
                                                            <h4 className="text-white font-bold text-lg truncate pr-8 group-hover:text-indigo-200 transition-colors">
                                                                {notif.title}
                                                            </h4>
                                                            <span className="text-[11px] font-medium text-slate-500 whitespace-nowrap bg-slate-950 px-2.5 py-1 rounded-lg border border-white/5">
                                                                {notif.createdAt && new Date(notif.createdAt).toLocaleDateString('es-ES', {
                                                                    day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit'
                                                                })}
                                                            </span>
                                                        </div>

                                                        <p className="text-slate-400 text-sm leading-relaxed mb-4 line-clamp-2 group-hover:text-slate-300 transition-colors">
                                                            {notif.message}
                                                        </p>

                                                        <div className="flex items-center gap-3">
                                                            <span
                                                                className="px-3 py-1 rounded-md text-[10px] font-bold uppercase tracking-wider border mb-0.5 inline-block"
                                                                style={{
                                                                    borderColor: `${catColor}30`,
                                                                    color: catColor,
                                                                    backgroundColor: `${catColor}10`
                                                                }}
                                                            >
                                                                {catLabel}
                                                            </span>

                                                            {notif.priority > 0 && (
                                                                <span className="flex items-center gap-1.5 text-[10px] text-emerald-400 font-bold uppercase tracking-wider bg-emerald-500/10 px-3 py-1 rounded-md border border-emerald-500/20">
                                                                    <Send size={10} /> Push Enviado
                                                                </span>
                                                            )}
                                                        </div>
                                                    </div>

                                                    <button
                                                        onClick={() => handleDelete(notif.id)}
                                                        className="absolute top-4 right-4 p-2 text-slate-600 hover:text-red-400 hover:bg-red-500/10 rounded-xl transition-all opacity-0 group-hover:opacity-100 translate-x-2 group-hover:translate-x-0"
                                                        title="Eliminar"
                                                    >
                                                        <Trash2 size={18} />
                                                    </button>
                                                </div>
                                            </div>
                                        );
                                    })}
                                    {notifications.length === 0 && (
                                        <div className="py-20 flex flex-col items-center justify-center text-center">
                                            <div className="w-20 h-20 bg-slate-800/50 rounded-full flex items-center justify-center mb-4">
                                                <Info size={32} className="text-slate-600" />
                                            </div>
                                            <h3 className="text-white font-medium text-lg">Sin comunicaciones</h3>
                                            <p className="text-slate-500 text-sm max-w-xs mt-2">
                                                No has enviado ninguna comunicación todavía. ¡Crea la primera ahora!
                                            </p>
                                        </div>
                                    )}
                                </div>
                            )}
                        </div>
                    </div>
                </div>
            </div>

            <ManageCategoriesModal
                isOpen={showManageModal}
                onClose={() => setShowManageModal(false)}
                onUpdate={refreshCategories}
            />
        </div>
    );
}

'use client';

import { useState, useEffect } from 'react';
import Link from 'next/link';
import { Users, BookOpen, FileText, TrendingUp, RefreshCw, Activity, ArrowUpRight } from 'lucide-react';
import { useAuth } from '@/contexts/AuthContext';
import { usersService } from '@/services/users.service';
import { AdminStatCard } from '@/components/admin/AdminStatCard';
import { AdminAnalyticsChart } from '@/components/admin/AdminAnalyticsChart';

interface DashboardStats {
    totalUsers: number;
    totalSubmissions: number;
    totalCourses: number;
    pageviews: number;
    uniques: number;
    recentUsers: Array<{
        id: string;
        firstName: string;
        lastName: string;
        email: string;
        createdAt: string;
    }>;
}

export default function AdminDashboard() {
    const { user: currentUser } = useAuth();
    const [stats, setStats] = useState<DashboardStats | null>(null);
    const [analyticsData, setAnalyticsData] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);

    const fetchDashboardData = async () => {
        if (!currentUser?.id) return;

        setLoading(true);
        setError(null);
        try {
            const apiUrl = process.env.NEXT_PUBLIC_API_URL || 'http://localhost:3001';

            // 1. Fetch Basic Stats (Parallel)
            const [usersRes, coursesRes] = await Promise.allSettled([
                usersService.getAllUsers(currentUser.id),
                fetch(`${apiUrl}/content/courses`)
            ]);

            // Process Users
            let users: any[] = [];
            if (usersRes.status === 'fulfilled') {
                users = usersRes.value;
            }

            // Process Courses
            let coursesCount = 0;
            if (coursesRes.status === 'fulfilled' && coursesRes.value.ok) {
                const courses = await coursesRes.value.json();
                coursesCount = Array.isArray(courses) ? courses.length : 0;
            }

            // Sort Users by Date (Newest first)
            const sortedUsers = [...users].sort((a: any, b: any) =>
                new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
            );

            // 2. Fetch Advanced Analytics (PostHog via Proxy)
            let pageviews = 0;
            let uniques = 0;
            try {
                const analyticsRes = await fetch('/api/admin/analytics');
                if (analyticsRes.ok) {
                    const data = await analyticsRes.json();

                    pageviews = data.pageviews?.total || 0;
                    uniques = data.uniques?.total || 0;

                    // Process PostHog response to match Recharts format if chart data exists
                    if (data.pageviews?.chart) {
                        setAnalyticsData(data.pageviews.chart.map((item: any) => ({
                            labels: item.label,
                            data: item.value
                        })));
                    }
                }
            } catch (authErr) {
                console.warn('Analytics fetch failed:', authErr);
            }

            setStats({
                totalUsers: users.length,
                totalSubmissions: 0, // Placeholder
                totalCourses: coursesCount,
                pageviews,
                uniques,
                recentUsers: sortedUsers.slice(0, 5).map((u: any) => ({
                    id: u.id,
                    firstName: u.firstName || 'N/A',
                    lastName: u.lastName || '',
                    email: u.email || 'N/A',
                    createdAt: u.createdAt,
                })),
            });

        } catch (err) {
            console.error('Error fetching dashboard data:', err);
            setError('Error loading dashboard data');
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        if (currentUser?.id) {
            fetchDashboardData();
        }
    }, [currentUser?.id]);

    const formatDate = (dateString: string) => {
        if (!dateString) return 'N/A';
        return new Date(dateString).toLocaleDateString('es-CO', {
            year: 'numeric',
            month: 'short',
            day: 'numeric',
        });
    };

    return (
        <div className="space-y-8 p-2">
            {/* Header with Glassmorphism */}
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 bg-slate-900/40 backdrop-blur-xl p-6 rounded-3xl border border-slate-800/50">
                <div>
                    <h2 className="text-3xl font-bold text-white tracking-tight">Panel Principal</h2>
                    <p className="text-slate-400 mt-1 flex items-center gap-2">
                        <span className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse" />
                        Sistema operativo y monitoreando en tiempo real
                    </p>
                </div>
                <button
                    onClick={fetchDashboardData}
                    disabled={loading}
                    className="flex items-center gap-2 px-5 py-2.5 bg-gradient-to-r from-blue-600 to-indigo-600 hover:from-blue-700 hover:to-indigo-700 disabled:opacity-50 text-white rounded-xl transition-all shadow-lg shadow-blue-500/20 font-medium"
                >
                    <RefreshCw size={18} className={loading ? 'animate-spin' : ''} />
                    <span>Actualizar Datos</span>
                </button>
            </div>

            {error && (
                <div className="bg-rose-500/10 border border-rose-500/20 rounded-2xl p-4 text-rose-300 flex items-center gap-3">
                    <div className="p-2 bg-rose-500/20 rounded-lg">
                        <Activity size={18} />
                    </div>
                    {error}
                </div>
            )}

            {/* Stats Grid - Modern Cards */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                <AdminStatCard
                    title="Total Usuarios"
                    value={stats?.totalUsers?.toLocaleString() || '0'}
                    icon={Users}
                    color="text-blue-400 bg-blue-400/10 border-blue-400/20"
                    loading={loading}
                    trend="+12%"
                    trendUp={true}
                />
                <AdminStatCard
                    title="Usuarios Únicos (7d)"
                    value={stats?.uniques?.toLocaleString() || '0'}
                    icon={Users}
                    color="text-indigo-400 bg-indigo-400/10 border-indigo-400/20"
                    loading={loading}
                    trend="Activos"
                    trendUp={true}
                />
                <AdminStatCard
                    title="Cursos Activos"
                    value={stats?.totalCourses?.toLocaleString() || '0'}
                    icon={BookOpen}
                    color="text-emerald-400 bg-emerald-400/10 border-emerald-400/20"
                    loading={loading}
                    trend="Publicados"
                    trendUp={true}
                />
                <AdminStatCard
                    title="Vistas de Página (7d)"
                    value={stats?.pageviews?.toLocaleString() || '0'}
                    icon={TrendingUp}
                    color="text-orange-400 bg-orange-400/10 border-orange-400/20"
                    loading={loading}
                    trend="Total"
                    trendUp={true}
                />
            </div>

            {/* Main Content Layout */}
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">

                {/* Analytics Chart (Takes up 2 cols) */}
                <div className="lg:col-span-2 space-y-6">
                    <AdminAnalyticsChart data={analyticsData} loading={loading} />

                    {/* Quick Actions Row */}
                    <div className="grid grid-cols-2 gap-4">
                        <Link href="/admin/users" className="block">
                            <div className="bg-slate-900 border border-slate-800 p-5 rounded-2xl hover:border-slate-700 transition cursor-pointer group h-full">
                                <div className="flex justify-between mb-2">
                                    <div className="p-2 bg-purple-500/10 rounded-lg text-purple-400"><Users size={20} /></div>
                                    <ArrowUpRight className="text-slate-600 group-hover:text-white transition" />
                                </div>
                                <h4 className="text-white font-medium">Gestionar Usuarios</h4>
                                <p className="text-slate-500 text-sm">Ver detalles y permisos</p>
                            </div>
                        </Link>

                        <Link href="/admin/courses" className="block">
                            <div className="bg-slate-900 border border-slate-800 p-5 rounded-2xl hover:border-slate-700 transition cursor-pointer group h-full">
                                <div className="flex justify-between mb-2">
                                    <div className="p-2 bg-pink-500/10 rounded-lg text-pink-400"><BookOpen size={20} /></div>
                                    <ArrowUpRight className="text-slate-600 group-hover:text-white transition" />
                                </div>
                                <h4 className="text-white font-medium">Gestionar Cursos</h4>
                                <p className="text-slate-500 text-sm">Editar contenido</p>
                            </div>
                        </Link>
                    </div>
                </div>

                {/* Recent Users List (Side Panel) */}
                <div className="bg-slate-900 rounded-2xl border border-slate-800 overflow-hidden flex flex-col h-full">
                    <div className="p-6 border-b border-slate-800 flex justify-between items-center">
                        <h3 className="text-lg font-bold text-white">Usuarios Recientes</h3>
                        <Link href="/admin/users">
                            <button className="text-xs text-blue-400 hover:text-blue-300 font-medium tracking-wide uppercase">Ver Todos</button>
                        </Link>
                    </div>

                    <div className="p-4 space-y-3 overflow-auto max-h-[500px] custom-scrollbar">
                        {loading ? (
                            [1, 2, 3, 4].map((i) => (
                                <div key={i} className="flex items-center gap-3 p-3 rounded-xl border border-slate-800 bg-slate-800/20 animate-pulse">
                                    <div className="w-10 h-10 rounded-full bg-slate-800" />
                                    <div className="flex-1 space-y-2">
                                        <div className="h-4 w-24 bg-slate-800 rounded" />
                                        <div className="h-3 w-32 bg-slate-800 rounded" />
                                    </div>
                                </div>
                            ))
                        ) : stats?.recentUsers && stats.recentUsers.length > 0 ? (
                            stats.recentUsers.map((user) => (
                                <div
                                    key={user.id}
                                    className="flex items-center gap-4 p-3 rounded-xl hover:bg-slate-800/50 transition-colors group cursor-default"
                                >
                                    <div className="w-10 h-10 rounded-full bg-gradient-to-br from-slate-700 to-slate-800 flex items-center justify-center text-white font-bold text-sm shadow-inner ring-2 ring-slate-800 group-hover:ring-slate-700 transition-all">
                                        {user.firstName?.charAt(0) || '?'}{user.lastName?.charAt(0) || ''}
                                    </div>
                                    <div className="flex-1 min-w-0">
                                        <p className="text-slate-200 font-medium truncate text-sm">
                                            {user.firstName} {user.lastName}
                                        </p>
                                        <p className="text-slate-500 text-xs truncate">{user.email}</p>
                                    </div>
                                    <div className="text-right">
                                        <span className="text-slate-600 text-[10px] font-medium bg-slate-900 px-2 py-1 rounded-full border border-slate-800">
                                            {formatDate(user.createdAt)}
                                        </span>
                                    </div>
                                </div>
                            ))
                        ) : (
                            <div className="h-48 flex flex-col items-center justify-center text-slate-500 text-center p-4">
                                <Users size={32} className="mb-2 opacity-20" />
                                <p className="text-sm">No hay usuarios nuevos recientemente</p>
                            </div>
                        )}
                    </div>

                    <div className="p-4 border-t border-slate-800 mt-auto bg-slate-900/50">
                        <button className="w-full py-2 text-sm text-slate-400 hover:text-white transition-colors border border-dashed border-slate-700 hover:border-slate-500 rounded-lg">
                            Descargar Reporte CSV
                        </button>
                    </div>
                </div>
            </div>
        </div>
    );
}

// Add simple CSS for custom scrollbar if not present
const style = `
  .custom-scrollbar::-webkit-scrollbar {
    width: 4px;
  }
  .custom-scrollbar::-webkit-scrollbar-track {
    background: transparent; 
  }
  .custom-scrollbar::-webkit-scrollbar-thumb {
    background: #334155; 
    border-radius: 2px;
  }
  .custom-scrollbar::-webkit-scrollbar-thumb:hover {
    background: #475569; 
  }
`;

'use client';

import { Search, MoreVertical, Loader2, Edit, Trash2, Check, X, ChevronLeft, ChevronRight, Filter, ListFilter, Mail, Phone, Calendar, User as UserIcon, Shield } from 'lucide-react';
import { useEffect, useState, useRef } from 'react';
import { usersService, User } from '@/services/users.service';
import { useAuth } from '@/contexts/AuthContext';

export default function UsersPage() {
    const { user: currentUser } = useAuth();
    const [users, setUsers] = useState<User[]>([]);
    const [loading, setLoading] = useState(true);

    // Filters & Search
    const [searchTerm, setSearchTerm] = useState('');
    const [roleFilter, setRoleFilter] = useState<string>('all');
    const [statusFilter, setStatusFilter] = useState<string>('all');

    // Pagination
    const [currentPage, setCurrentPage] = useState(1);
    const [usersPerPage, setUsersPerPage] = useState(10);

    // Interaction State
    const [editingUserId, setEditingUserId] = useState<string | null>(null);
    const [selectedRole, setSelectedRole] = useState<string>('');
    const [activeMenuUserId, setActiveMenuUserId] = useState<string | null>(null);
    const [selectedUser, setSelectedUser] = useState<User | null>(null);

    const menuRef = useRef<HTMLDivElement>(null);
    const panelRef = useRef<HTMLDivElement>(null);

    // Close menu when clicking outside
    useEffect(() => {
        function handleClickOutside(event: MouseEvent) {
            if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
                setActiveMenuUserId(null);
            }
            // Close panel if clicked outside (optional, maybe better not to closing accidentally)
            // if (panelRef.current && !panelRef.current.contains(event.target as Node) && selectedUser) {
            //    setSelectedUser(null);
            // }
        }
        document.addEventListener("mousedown", handleClickOutside);
        return () => {
            document.removeEventListener("mousedown", handleClickOutside);
        };
    }, [selectedUser]);

    useEffect(() => {
        if (currentUser?.id) {
            fetchUsers();
        }
    }, [currentUser]);

    // Reset page on filter/size change
    useEffect(() => {
        setCurrentPage(1);
    }, [searchTerm, roleFilter, statusFilter, usersPerPage]);

    const fetchUsers = async () => {
        try {
            setLoading(true);
            const data = await usersService.getAllUsers(currentUser!.id);
            setUsers(data);
        } catch (error) {
            console.error('Failed to fetch users', error);
        } finally {
            setLoading(false);
        }
    };

    // Filter Logic
    const filteredUsers = users.filter(user => {
        const matchesSearch =
            user.firstName.toLowerCase().includes(searchTerm.toLowerCase()) ||
            user.lastName?.toLowerCase().includes(searchTerm.toLowerCase()) ||
            user.email.toLowerCase().includes(searchTerm.toLowerCase());

        const matchesRole = roleFilter === 'all' || user.role?.toLowerCase() === roleFilter.toLowerCase();

        const matchesStatus = statusFilter === 'all' ||
            user.status === statusFilter ||
            user.status?.toLowerCase() === statusFilter.toLowerCase();

        return matchesSearch && matchesRole && matchesStatus;
    });

    // Pagination Logic
    const indexOfLastUser = currentPage * usersPerPage;
    const indexOfFirstUser = indexOfLastUser - usersPerPage;
    const currentUsers = filteredUsers.slice(indexOfFirstUser, indexOfLastUser);
    const totalPages = Math.ceil(filteredUsers.length / usersPerPage);

    const handleUpdateRole = async (userId: string) => {
        try {
            await usersService.updateUserRole(userId, selectedRole);
            // Update local state and selected user if needed
            setUsers(users.map(u => u.id === userId ? { ...u, role: selectedRole } : u));
            if (selectedUser?.id === userId) {
                setSelectedUser(prev => prev ? ({ ...prev, role: selectedRole }) : null);
            }
            setEditingUserId(null);
            setActiveMenuUserId(null);
        } catch (error) {
            console.error('Failed to update role', error);
            alert('Error al actualizar el rol');
        }
    };

    const [deletingUserId, setDeletingUserId] = useState<string | null>(null);

    const handleDeleteUser = async (user: User) => {
        const confirmed = window.confirm(
            `¿Estás seguro de que deseas eliminar a ${user.firstName} ${user.lastName}?\n\nEsta acción es irreversible y eliminará todos sus datos.`
        );

        if (!confirmed) return;

        try {
            setDeletingUserId(user.id);
            await usersService.deleteUser(user.id);
            setUsers(prev => prev.filter(u => u.id !== user.id));
            if (selectedUser?.id === user.id) setSelectedUser(null);
            setActiveMenuUserId(null);
        } catch (error) {
            console.error('Failed to delete user', error);
            alert('Error al eliminar el usuario');
        } finally {
            setDeletingUserId(null);
        }
    };

    const startEditing = (user: User) => {
        setEditingUserId(user.id);
        setSelectedRole(user.role);
        setActiveMenuUserId(null);
    };

    const formatDate = (dateString: string) => {
        if (!dateString) return '-';
        return new Date(dateString).toLocaleDateString('es-CO');
    };

    const handleGmailRedirect = (email: string) => {
        window.open(`https://mail.google.com/mail/?view=cm&fs=1&to=${email}`, '_blank');
    };

    return (
        <div className="space-y-6 p-2 relative">
            <div className="flex flex-col xl:flex-row xl:items-center justify-between gap-4">
                <div>
                    <h2 className="text-2xl font-bold text-white">Gestión de Usuarios</h2>
                    <p className="text-slate-400 text-sm">Administra roles, estados y accesos</p>
                </div>

                <div className="flex flex-col sm:flex-row gap-3 items-start sm:items-center">

                    <div className="flex gap-3 w-full sm:w-auto">
                        {/* Role Filter */}
                        <div className="relative flex-1 sm:flex-none">
                            <Filter className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
                            <select
                                value={roleFilter}
                                onChange={(e) => setRoleFilter(e.target.value)}
                                className="w-full sm:w-auto pl-10 pr-8 py-2 bg-slate-800 border border-slate-700 rounded-lg text-white text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 appearance-none cursor-pointer hover:border-slate-600 transition-colors"
                            >
                                <option value="all">Roles (Todos)</option>
                                <option value="User">Usuarios</option>
                                <option value="Admin">Admin</option>
                                <option value="Interpreter">Intérpretes</option>
                            </select>
                        </div>

                        {/* Status Filter */}
                        <div className="relative flex-1 sm:flex-none">
                            <ListFilter className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
                            <select
                                value={statusFilter}
                                onChange={(e) => setStatusFilter(e.target.value)}
                                className="w-full sm:w-auto pl-10 pr-8 py-2 bg-slate-800 border border-slate-700 rounded-lg text-white text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 appearance-none cursor-pointer hover:border-slate-600 transition-colors"
                            >
                                <option value="all">Estado (Todos)</option>
                                <option value="Active">Activo</option>
                                <option value="Inactive">Inactivo</option>
                                <option value="Pending">Pendiente</option>
                            </select>
                        </div>
                    </div>

                    {/* Search */}
                    <div className="relative w-full sm:w-auto">
                        <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                        <input
                            type="text"
                            placeholder="Buscar..."
                            value={searchTerm}
                            onChange={(e) => setSearchTerm(e.target.value)}
                            className="pl-10 pr-4 py-2 w-full sm:w-64 bg-slate-800 border border-slate-700 rounded-lg text-white text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
                        />
                    </div>
                </div>
            </div>

            <div className="flex gap-6 items-start">
                {/* Users Table */}
                <div className={`flex-1 bg-slate-800 rounded-xl border border-slate-700 overflow-hidden shadow-xl transition-all duration-300`}>
                    {loading ? (
                        <div className="flex justify-center p-12">
                            <Loader2 className="animate-spin text-blue-500" size={32} />
                        </div>
                    ) : (
                        <>
                            <div className="overflow-x-auto">
                                <table className="w-full text-left">
                                    <thead className="bg-slate-900/50 border-b border-slate-700 text-slate-400 uppercase text-xs font-semibold">
                                        <tr>
                                            <th className="px-6 py-4">Usuario</th>
                                            <th className="px-6 py-4 hidden md:table-cell">Rol</th>
                                            <th className="px-6 py-4 hidden lg:table-cell">Estado</th>
                                            <th className="px-6 py-4 hidden xl:table-cell">Registro</th>
                                            <th className="px-6 py-4 text-right">Acciones</th>
                                        </tr>
                                    </thead>
                                    <tbody className="divide-y divide-slate-700/50">
                                        {currentUsers.length === 0 ? (
                                            <tr>
                                                <td colSpan={5} className="text-center py-12 text-slate-500">
                                                    No se encontraron usuarios con los filtros actuales.
                                                </td>
                                            </tr>
                                        ) : (
                                            currentUsers.map((user) => (
                                                <tr
                                                    key={user.id}
                                                    onClick={() => setSelectedUser(user)}
                                                    className={`cursor-pointer transition-colors ${selectedUser?.id === user.id ? 'bg-slate-700/60 border-l-2 border-blue-500' : 'hover:bg-slate-700/30 border-l-2 border-transparent'}`}
                                                >
                                                    <td className="px-6 py-4">
                                                        <div className="flex items-center gap-3">
                                                            <div className="w-9 h-9 rounded-full bg-gradient-to-br from-blue-500 to-indigo-600 flex items-center justify-center text-white font-bold text-sm shadow-md shrink-0">
                                                                {user.firstName.charAt(0)}
                                                            </div>
                                                            <div className="min-w-0">
                                                                <div className="font-medium text-white truncate max-w-[150px] md:max-w-none">{user.firstName} {user.lastName}</div>
                                                                <div className="text-xs text-slate-400 truncate max-w-[150px] md:max-w-none">{user.email}</div>
                                                            </div>
                                                        </div>
                                                    </td>
                                                    <td className="px-6 py-4 hidden md:table-cell">
                                                        {editingUserId === user.id ? (
                                                            <div className="flex items-center gap-2 bg-slate-900 p-1 rounded-lg border border-slate-600 w-fit" onClick={e => e.stopPropagation()}>
                                                                <select
                                                                    value={selectedRole}
                                                                    onChange={(e) => setSelectedRole(e.target.value)}
                                                                    className="bg-transparent text-white text-xs rounded px-1 py-1 focus:outline-none"
                                                                >
                                                                    <option value="User">User</option>
                                                                    <option value="Admin">Admin</option>
                                                                    <option value="interpreter">Interpreter</option>
                                                                </select>
                                                                <button onClick={() => handleUpdateRole(user.id)} className="p-1 hover:bg-emerald-500/20 text-emerald-400 rounded transition">
                                                                    <Check size={14} />
                                                                </button>
                                                                <button onClick={() => setEditingUserId(null)} className="p-1 hover:bg-rose-500/20 text-rose-400 rounded transition">
                                                                    <X size={14} />
                                                                </button>
                                                            </div>
                                                        ) : (
                                                            <span className={`inline-flex px-2.5 py-1 rounded-md text-xs font-semibold border ${user.role === 'Admin' ? 'bg-purple-500/10 text-purple-400 border-purple-500/20' :
                                                                    (user.role === 'Interpreter' || user.role === 'interpreter') ? 'bg-orange-500/10 text-orange-400 border-orange-500/20' :
                                                                        'bg-blue-500/10 text-blue-400 border-blue-500/20'
                                                                }`}>
                                                                {user.role}
                                                            </span>
                                                        )}
                                                    </td>
                                                    <td className="px-6 py-4 hidden lg:table-cell">
                                                        <div className="flex items-center gap-2">
                                                            <span className={`w-2 h-2 rounded-full ${user.status === 'Active' || user.status === 'active' ? 'bg-emerald-400 shadow-[0_0_8px_rgba(52,211,153,0.5)]' : 'bg-slate-500'}`} />
                                                            <span className="text-sm text-slate-300 capitalize">{user.status}</span>
                                                        </div>
                                                    </td>
                                                    <td className="px-6 py-4 text-slate-400 text-sm hidden xl:table-cell">
                                                        {formatDate(user.createdAt)}
                                                    </td>
                                                    <td className="px-6 py-4 text-right relative">
                                                        <button
                                                            onClick={(e) => {
                                                                e.stopPropagation();
                                                                setActiveMenuUserId(activeMenuUserId === user.id ? null : user.id);
                                                            }}
                                                            className={`p-1.5 rounded-lg transition-colors ${activeMenuUserId === user.id ? 'bg-slate-700 text-white' : 'text-slate-400 hover:text-white hover:bg-slate-700/50'}`}
                                                        >
                                                            <MoreVertical size={16} />
                                                        </button>

                                                        {activeMenuUserId === user.id && (
                                                            <div
                                                                ref={menuRef}
                                                                onClick={(e) => e.stopPropagation()}
                                                                className="absolute right-8 top-8 z-50 w-48 bg-slate-900 rounded-xl shadow-2xl border border-slate-700 p-1"
                                                            >
                                                                <button
                                                                    onClick={() => startEditing(user)}
                                                                    className="w-full text-left px-3 py-2 text-sm text-slate-300 hover:bg-slate-800 hover:text-white rounded-lg flex items-center gap-2 transition-colors"
                                                                >
                                                                    <Edit size={14} />
                                                                    Cambiar Rol
                                                                </button>
                                                                <button
                                                                    onClick={() => handleGmailRedirect(user.email)}
                                                                    className="w-full text-left px-3 py-2 text-sm text-slate-300 hover:bg-slate-800 hover:text-white rounded-lg flex items-center gap-2 transition-colors"
                                                                >
                                                                    <Mail size={14} />
                                                                    Enviar Email
                                                                </button>
                                                                <div className="border-t border-slate-700 my-1" />
                                                                <button
                                                                    onClick={() => handleDeleteUser(user)}
                                                                    disabled={deletingUserId === user.id}
                                                                    className="w-full text-left px-3 py-2 text-sm text-rose-400 hover:bg-rose-500/10 hover:text-rose-300 rounded-lg flex items-center gap-2 transition-colors disabled:opacity-50"
                                                                >
                                                                    {deletingUserId === user.id ? (
                                                                        <Loader2 size={14} className="animate-spin" />
                                                                    ) : (
                                                                        <Trash2 size={14} />
                                                                    )}
                                                                    Eliminar Usuario
                                                                </button>
                                                            </div>
                                                        )}
                                                    </td>
                                                </tr>
                                            ))
                                        )}
                                    </tbody>
                                </table>
                            </div>

                            {/* Pagination Footer */}
                            <div className="border-t border-slate-700 p-4 bg-slate-900/30 flex flex-col md:flex-row justify-between items-center gap-4">
                                <div className="flex items-center gap-4 text-sm text-slate-400">
                                    <span className="hidden sm:inline">Mostrar:</span>
                                    <select
                                        value={usersPerPage}
                                        onChange={(e) => setUsersPerPage(Number(e.target.value))}
                                        className="bg-slate-800 border border-slate-700 rounded px-2 py-1 text-white focus:outline-none focus:ring-2 focus:ring-blue-500 text-sm"
                                    >
                                        <option value={5}>5</option>
                                        <option value={10}>10</option>
                                        <option value={20}>20</option>
                                        <option value={50}>50</option>
                                    </select>
                                    <span>
                                        <span className="font-medium text-white">{filteredUsers.length > 0 ? indexOfFirstUser + 1 : 0}</span> - <span className="font-medium text-white">{Math.min(indexOfLastUser, filteredUsers.length)}</span> de <span className="font-medium text-white">{filteredUsers.length}</span>
                                    </span>
                                </div>

                                <div className="flex items-center gap-2">
                                    <button
                                        onClick={() => setCurrentPage(prev => Math.max(prev - 1, 1))}
                                        disabled={currentPage === 1}
                                        className="p-2 rounded-lg bg-slate-800 border border-slate-700 text-slate-300 hover:bg-slate-700 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
                                    >
                                        <ChevronLeft size={16} />
                                    </button>

                                    <div className="hidden sm:flex items-center gap-1">
                                        {Array.from({ length: totalPages }, (_, i) => i + 1).map(number => {
                                            const shouldShow = number === 1 || number === totalPages || (number >= currentPage - 1 && number <= currentPage + 1);
                                            if (!shouldShow) {
                                                if (number === currentPage - 2 || number === currentPage + 2) return <span key={number} className="text-slate-600 px-1">...</span>;
                                                return null;
                                            }

                                            return (
                                                <button
                                                    key={number}
                                                    onClick={() => setCurrentPage(number)}
                                                    className={`w-8 h-8 rounded-lg text-sm font-medium transition-colors ${currentPage === number
                                                            ? 'bg-blue-600 text-white shadow-lg shadow-blue-500/20'
                                                            : 'bg-slate-800 border border-slate-700 text-slate-400 hover:bg-slate-700 hover:text-white'
                                                        }`}
                                                >
                                                    {number}
                                                </button>
                                            );
                                        })}
                                    </div>

                                    <button
                                        onClick={() => setCurrentPage(prev => Math.min(prev + 1, totalPages))}
                                        disabled={currentPage === totalPages || totalPages === 0}
                                        className="p-2 rounded-lg bg-slate-800 border border-slate-700 text-slate-300 hover:bg-slate-700 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
                                    >
                                        <ChevronRight size={16} />
                                    </button>
                                </div>
                            </div>
                        </>
                    )}
                </div>

                {/* User Detail Side Panel */}
                <div
                    className={`fixed inset-y-0 right-0 w-full md:w-96 bg-slate-900 border-l border-slate-800 shadow-2xl transform transition-transform duration-300 ease-in-out z-50 flex flex-col ${selectedUser ? 'translate-x-0' : 'translate-x-full'}`}
                    ref={panelRef}
                >
                    {selectedUser ? (
                        <>
                            {/* Header */}
                            <div className="p-6 border-b border-slate-800 flex justify-between items-center bg-slate-900">
                                <h3 className="text-xl font-bold text-white">Perfil de Usuario</h3>
                                <button
                                    onClick={() => setSelectedUser(null)}
                                    className="p-2 hover:bg-slate-800 rounded-full text-slate-400 hover:text-white transition-colors"
                                >
                                    <X size={20} />
                                </button>
                            </div>

                            {/* Content */}
                            <div className="flex-1 overflow-y-auto p-6 space-y-8">
                                {/* Profile Header */}
                                <div className="flex flex-col items-center text-center">
                                    <div className="w-24 h-24 rounded-full bg-gradient-to-br from-blue-500 to-indigo-600 flex items-center justify-center text-white font-bold text-4xl shadow-lg ring-4 ring-slate-800 mb-4">
                                        {selectedUser.firstName.charAt(0)}
                                    </div>
                                    <h4 className="text-2xl font-bold text-white max-w-full break-words">
