'use client';

import { useState, useEffect } from 'react';
import { Course } from '@/services/content.service';
import { ChevronDown, ChevronRight, PlayCircle, Lock, Menu, ArrowLeft } from 'lucide-react';
import Link from 'next/link';
import { useRouter } from 'next/navigation';

interface CoursePlayerViewProps {
    course: Course;
}

export function CoursePlayerView({ course }: CoursePlayerViewProps) {
    const router = useRouter();
    const [activeLesson, setActiveLesson] = useState<any | null>(null);
    const [expandedModules, setExpandedModules] = useState<string[]>([]);
    const [showSidebar, setShowSidebar] = useState(true);

    useEffect(() => {
        // Auto-select first accessible lesson
        const firstAccessible = findFirstAccessibleLesson(course);
        if (firstAccessible) {
            setExpandedModules([firstAccessible.moduleId]);
            setActiveLesson(firstAccessible.lesson);
        } else if (course.modules && course.modules.length > 0) {
            setExpandedModules([course.modules[0].id]);
        }
    }, [course]);

    const findFirstAccessibleLesson = (c: Course) => {
        for (const mod of c.modules || []) {
            for (const les of mod.lessons || []) {
                if (les.videoUrl) { // Simple check since we are in "Player View" implies access
                    return { lesson: les, moduleId: mod.id };
                }
            }
        }
        return null;
    };

    const toggleModule = (moduleId: string) => {
        setExpandedModules(prev =>
            prev.includes(moduleId)
                ? prev.filter(id => id !== moduleId)
                : [...prev, moduleId]
        );
    };

    return (
        <div className="h-screen flex flex-col bg-white">
            {/* Header */}
            <header className="h-16 border-b border-gray-200 flex items-center px-4 bg-white z-10 shadow-sm flex-shrink-0 justify-between">
                <div className="flex items-center">
                    <Link href="/cursos" className="mr-4 p-2 hover:bg-gray-100 rounded-full transition-colors text-gray-500 hover:text-gray-900">
                        <ArrowLeft size={20} />
                    </Link>
                    <h1 className="text-lg font-bold text-gray-900 line-clamp-1">
                        {course.title}
                    </h1>
                </div>

                <button
                    onClick={() => setShowSidebar(!showSidebar)}
                    className="md:hidden p-2 hover:bg-gray-100 rounded-full"
                >
                    <Menu size={20} />
                </button>
            </header>

            <div className="flex-1 flex overflow-hidden">
                {/* Main Content (Video Player) */}
                <main className="flex-1 bg-black flex flex-col relative overflow-y-auto">
                    {activeLesson ? (
                        <div className="flex-1 flex flex-col">
                            {/* Video Container */}
                            <div className="w-full bg-black aspect-video max-h-[70vh] flex items-center justify-center relative">
                                {activeLesson.videoUrl ? (
                                    <video
                                        src={activeLesson.videoUrl}
                                        controls
                                        className="w-full h-full"
                                        poster={course.thumbnailUrl}
                                        autoPlay={false}
                                    />
                                ) : (
                                    <div className="text-center p-8 bg-zinc-900 rounded-lg max-w-md">
                                        <Lock className="w-12 h-12 text-zinc-600 mx-auto mb-4" />
                                        <p className="text-zinc-400">Este video no está disponible.</p>
                                    </div>
                                )}
                            </div>

                            {/* Lesson Info */}
                            <div className="p-6 md:p-8 bg-white flex-1">
                                <h2 className="text-2xl font-bold text-gray-900 mb-2">{activeLesson.title}</h2>
                                <p className="text-gray-600 leading-relaxed">
                                    {activeLesson.description || 'Sin descripción adicional para esta lección.'}
                                </p>
                            </div>
                        </div>
                    ) : (
                        <div className="flex-1 flex flex-col items-center justify-center text-white p-8 text-center bg-zinc-900">
                            <PlayCircle size={64} className="text-[#83A98A] mb-4 opacity-50" />
                            <h2 className="text-xl font-medium">Selecciona una lección para comenzar</h2>
                        </div>
                    )}
                </main>

                {/* Sidebar (Curriculum) */}
                <aside className={`
                    w-80 border-l border-gray-200 bg-gray-50 overflow-y-auto flex-shrink-0 
                    fixed inset-y-0 right-0 z-20 transition-transform duration-300 transform
                    ${showSidebar ? 'translate-x-0' : 'translate-x-full'}
                    md:relative md:translate-x-0 md:block
                `}>
                    <div className="p-4 border-b border-gray-200 sticky top-0 bg-gray-50 z-10 flex justify-between items-center">
                        <h3 className="font-bold text-gray-900">Contenido</h3>
                        <button onClick={() => setShowSidebar(false)} className="md:hidden">
                            <ChevronRight />
                        </button>
                    </div>

                    <div className="space-y-1 p-2">
                        {course.modules?.map((module: any) => (
                            <div key={module.id} className="bg-white rounded-lg border border-gray-200 overflow-hidden">
                                <button
                                    onClick={() => toggleModule(module.id)}
                                    className="w-full flex items-center justify-between p-4 hover:bg-gray-50 transition-colors text-left"
                                >
                                    <span className="font-semibold text-sm text-gray-800 line-clamp-1">{module.title}</span>
                                    {expandedModules.includes(module.id) ? <ChevronDown size={16} className="text-gray-400" /> : <ChevronRight size={16} className="text-gray-400" />}
                                </button>

                                {expandedModules.includes(module.id) && (
                                    <div className="border-t border-gray-100 bg-gray-50">
                                        {module.lessons?.map((lesson: any) => (
                                            <button
                                                key={lesson.id}
                                                onClick={() => {
                                                    setActiveLesson(lesson);
                                                    if (window.innerWidth < 768) setShowSidebar(false);
                                                }}
                                                className={`w-full flex items-center gap-3 p-3 text-left transition-all border-l-4 ${activeLesson?.id === lesson.id
                                                    ? 'bg-[#83A98A]/10 border-[#83A98A]'
                                                    : 'border-transparent hover:bg-gray-100'
                                                    }`}
                                            >
                                                <div className={`flex-shrink-0 w-6 h-6 rounded-full flex items-center justify-center ${activeLesson?.id === lesson.id ? 'text-[#83A98A]' : 'text-gray-400'
                                                    }`}>
                                                    <PlayCircle size={16} />
                                                </div>
                                                <div className="flex-1 min-w-0">
                                                    <p className={`text-sm font-medium truncate ${activeLesson?.id === lesson.id ? 'text-[#83A98A]' : 'text-gray-700'
                                                        }`}>
                                                        {lesson.title}
                                                    </p>
                                                    <span className="text-xs text-gray-400">{lesson.durationSeconds ? `${Math.round(lesson.durationSeconds / 60)} min` : 'Video'}</span>
                                                </div>
                                            </button>
                                        ))}
                                    </div>
                                )}
                            </div>
                        ))}
                    </div>
                </aside>
            </div>
        </div>
    );
}

'use client';

import { useEffect, useState, useCallback } from 'react';
import { useParams } from 'next/navigation';
import Link from 'next/link';
import { contentService, Course } from '@/services/content.service';
import { paymentsService } from '@/services/payments.service';
import { useAuth } from '@/contexts/AuthContext';
import { useUI } from '@/contexts/UIContext';
import { Loader2 } from 'lucide-react';
import { CourseLandingView } from './CourseLandingView';
import { CoursePlayerView } from './CoursePlayerView';

export default function CoursePlayerPage() {
    const params = useParams();
    const courseId = params.id as string;
    const { user, isAuthenticated, isLoading: authLoading } = useAuth();
    const { setIsRegistrationPanelOpen } = useUI();

    // State
    const [course, setCourse] = useState<Course | null>(null);
    const [loading, setLoading] = useState(true);
    const [hasAccess, setHasAccess] = useState(false);
    const [subscriptionStatus, setSubscriptionStatus] = useState<any>(null);

    const checkAccess = useCallback(async (courseData: Course) => {
        // If course is not paid, anyone has access
        if (!courseData.isPaid) return true;

        // If not authenticated and course is paid, no access
        if (!isAuthenticated || !user) return false;

        // Admins always have access
        if (user.role === 'Admin') return true;

        try {
            // Check real subscription status from backend
            const status = await paymentsService.getSubscriptionStatus(user.id);
            setSubscriptionStatus(status);

            // Check if user has an active personal or corporate plan
            if (status.hasSubscription && (status.planType?.includes('premium') || status.planType?.includes('corporate') || status.planType?.includes('business'))) {
                return true;
            }

            // TODO: Also check if user bought THIS specific course (if we implement individual course purchases)
            // if (user.purchasedCourses?.includes(courseId)) return true;

            return false;
        } catch (error) {
            console.error('Error checking subscription status:', error);
            return false;
        }
    }, [isAuthenticated, user]);

    const fetchCourseData = useCallback(async () => {
        try {
            setLoading(true);

            // Initial fetch to get course metadata (isPaid, description, etc)
            const initialData = await contentService.getCourseById(courseId);

            // Check if user should have full access
            const access = await checkAccess(initialData);
            setHasAccess(access);

            // Fetch again with hasAccess=true if they have it, to get unmasked video URLs
            if (access) {
                const fullData = await contentService.getCourseById(courseId, { hasAccess: true });
                setCourse(fullData);
            } else {
                setCourse(initialData);
            }
        } catch (error) {
            console.error('Failed to load course', error);
        } finally {
            setLoading(false);
        }
    }, [courseId, checkAccess]);

    useEffect(() => {
        if (courseId && !authLoading) {
            fetchCourseData();
        }
    }, [courseId, authLoading, fetchCourseData]);

    const handleBuy = () => {
        if (!isAuthenticated) {
            setIsRegistrationPanelOpen(true);
        } else {
            // Redirect to pricing or start checkout flow
            window.location.href = '/pricing';
        }
    };

    if (loading || authLoading) return (
        <div className="min-h-screen flex items-center justify-center bg-gray-50">
            <Loader2 className="animate-spin text-[#83A98A]" size={48} />
        </div>
    );

    if (!course) return (
        <div className="p-10 text-center py-20 bg-slate-50 min-h-screen">
            <h2 className="text-xl font-bold text-slate-800">Curso no encontrado</h2>
            <Link href="/cursos" className="text-indigo-600 hover:underline mt-4 inline-block">
                Volver al catálogo
            </Link>
        </div>
    );

    // If no access, show the beautiful Landing View (Presentation)
    if (!hasAccess) {
        return (
            <CourseLandingView 
                course={course} 
                onBuy={handleBuy} 
                isAuthenticated={isAuthenticated} 
            />
        );
    }

    // If has access, show the Player View
    return <CoursePlayerView course={course} />;
}

'use client';

import { useEffect, useState, useMemo } from 'react';
import { contentService, Course } from '@/services/content.service';
import { Loader2, BookOpen, Search, PlayCircle, Grid, Layers } from 'lucide-react';
import Link from 'next/link';

export default function CoursesPage() {
    const [courses, setCourses] = useState<Course[]>([]);
    const [loading, setLoading] = useState(true);
    const [searchTerm, setSearchTerm] = useState('');
    const [selectedCategory, setSelectedCategory] = useState<string | null>(null);

    useEffect(() => {
        const fetchCourses = async () => {
            try {
                const data = await contentService.getAllCourses();
                // Filter only published courses
                setCourses(data.filter(c => c.isPublished));
            } catch (error) {
                console.error(error);
            } finally {
                setLoading(false);
            }
        };
        fetchCourses();
    }, []);

    // Get unique categories from courses
    const categories = useMemo(() => {
        const cats = new Map<string, string>();
        courses.forEach(c => {
            if (c.category) {
                cats.set(c.category.id, c.category.name);
            } else {
                cats.set('uncategorized', 'Sin Categoría');
            }
        });
        return Array.from(cats.entries()).map(([id, name]) => ({ id, name }));
    }, [courses]);

    // Filter and Group Courses
    const groupedCourses = useMemo(() => {
        let filtered = courses;

        // Apply Search
        if (searchTerm) {
            const lowerTerm = searchTerm.toLowerCase();
            filtered = filtered.filter(c =>
                c.title.toLowerCase().includes(lowerTerm) ||
                c.description?.toLowerCase().includes(lowerTerm)
            );
        }

        // Apply Category Filter
        if (selectedCategory) {
            filtered = filtered.filter(c =>
                (selectedCategory === 'uncategorized' && !c.category) ||
                c.category?.id === selectedCategory
            );
        }

        // Group by Category
        const groups: { [key: string]: { name: string; courses: Course[] } } = {};

        filtered.forEach(course => {
            const catId = course.category?.id || 'uncategorized';
            const catName = course.category?.name || 'Sin Categoría';

            if (!groups[catId]) {
                groups[catId] = { name: catName, courses: [] };
            }
            groups[catId].courses.push(course);
        });

        return Object.values(groups).sort((a, b) => a.name.localeCompare(b.name));
    }, [courses, searchTerm, selectedCategory]);

    if (loading) {
        return (
            <div className="min-h-screen bg-slate-50 flex items-center justify-center">
                <Loader2 className="animate-spin text-indigo-600" size={32} />
            </div>
        );
    }

    return (
        <main className="min-h-screen bg-slate-50 text-slate-900 pt-24 pb-20 px-6">
            <div className="max-w-7xl mx-auto space-y-12">

                {/* Header & Controls */}
                <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6">
                    <div>
                        <h1 className="text-3xl font-bold mb-2 text-slate-900">Catálogo de Cursos</h1>
                        <p className="text-slate-500">Domina nuevas habilidades con nuestros cursos estructurados.</p>
                    </div>

                    <div className="flex flex-col sm:flex-row gap-4 w-full md:w-auto">
                        {/* Search Bar */}
                        <div className="relative group">
                            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-indigo-600 transition-colors" size={18} />
                            <input
                                type="text"
                                placeholder="Buscar cursos..."
                                value={searchTerm}
                                onChange={(e) => setSearchTerm(e.target.value)}
                                className="bg-white border border-slate-200 rounded-full py-2.5 pl-10 pr-4 w-full sm:w-64 text-sm focus:outline-none focus:border-indigo-500 focus:ring-1 focus:ring-indigo-500 transition-all placeholder:text-slate-400 shadow-sm"
                            />
                        </div>
                    </div>
                </div>

                {/* Category Filter Pills */}
                <div className="flex flex-wrap gap-2">
                    <button
                        onClick={() => setSelectedCategory(null)}
                        className={`px-4 py-1.5 rounded-full text-sm font-medium transition-all shadow-sm border ${selectedCategory === null
                                ? 'bg-slate-900 text-white border-slate-900'
                                : 'bg-white text-slate-600 border-slate-200 hover:bg-slate-50 hover:border-slate-300'
                            }`}
                    >
                        Todos
                    </button>
                    {categories.map(cat => (
                        <button
                            key={cat.id}
                            onClick={() => setSelectedCategory(cat.id === selectedCategory ? null : cat.id)}
                            className={`px-4 py-1.5 rounded-full text-sm font-medium transition-all shadow-sm border ${selectedCategory === cat.id
                                    ? 'bg-slate-900 text-white border-slate-900'
                                    : 'bg-white text-slate-600 border-slate-200 hover:bg-slate-50 hover:border-slate-300'
                                }`}
                        >
                            {cat.name}
                        </button>
                    ))}
                </div>

                {/* Content Groups */}
                <div className="space-y-16">
                    {groupedCourses.length > 0 ? (
                        groupedCourses.map((group) => (
                            <section key={group.name} className="animate-in fade-in slide-in-from-bottom-4 duration-500">
                                <div className="flex items-center gap-2 mb-6 border-b border-slate-200 pb-4">
                                    <Layers className="text-indigo-600" size={20} />
                                    <h2 className="text-xl font-bold text-slate-800">{group.name}</h2>
                                    <span className="text-xs font-mono bg-slate-100 text-slate-500 px-2 py-0.5 rounded ml-2 font-medium">
                                        {group.courses.length}
                                    </span>
                                </div>

                                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
                                    {group.courses.map(course => (
                                        <Link href={`/cursos/${course.id}`} key={course.id} className="group block h-full">
                                            <div className="bg-white border border-slate-200 rounded-xl overflow-hidden hover:border-indigo-500/50 hover:shadow-lg hover:shadow-indigo-500/10 transition-all duration-300 h-full flex flex-col">
                                                {/* Thumbnail */}
                                                <div className="aspect-video bg-slate-100 relative overflow-hidden">
                                                    {course.thumbnailUrl ? (
                                                        <img
                                                            src={course.thumbnailUrl}
                                                            alt={course.title}
                                                            className="w-full h-full object-cover group-hover:scale-105 transition-all duration-500"
                                                        />
                                                    ) : (
                                                        <div className="w-full h-full flex items-center justify-center text-slate-300">
                                                            <div className="w-12 h-12 rounded-full bg-slate-200 flex items-center justify-center text-slate-400">
                                                                <Grid size={24} />
                                                            </div>
                                                        </div>
                                                    )}

                                                    {/* Play Overlay */}
                                                    <div className="absolute inset-0 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity bg-black/10 backdrop-blur-[1px]">
                                                        <div className="bg-white/90 backdrop-blur-md rounded-full p-3 text-indigo-600 shadow-lg transform scale-90 group-hover:scale-100 transition-transform">
                                                            <PlayCircle size={32} className="fill-current" />
                                                        </div>
                                                    </div>
                                                </div>

                                                {/* Content */}
                                                <div className="p-5 flex-1 flex flex-col">
                                                    <h3 className="font-semibold text-slate-800 mb-2 line-clamp-2 leading-snug group-hover:text-indigo-600 transition-colors">
                                                        {course.title}
                                                    </h3>
                                                    <div className="mt-auto pt-4 flex items-center justify-between text-xs text-slate-500 border-t border-slate-50">
                                                        <span className="flex items-center gap-1.5 font-medium">
                                                            <BookOpen size={14} className="text-indigo-500/70" />
                                                            {course.modules?.length || 0} Módulos
                                                        </span>
                                                        {/* Optional: Add duration if available */}
                                                    </div>
                                                </div>
                                            </div>
                                        </Link>
                                    ))}
                                </div>
                            </section>
                        ))
                    ) : (
                        <div className="text-center py-20 bg-slate-50 rounded-2xl border border-dashed border-slate-200">
                            <p className="text-slate-500">No se encontraron cursos que coincidan con tu búsqueda.</p>
                            <button
                                onClick={() => { setSearchTerm(''); setSelectedCategory(null); }}
                                className="mt-4 text-indigo-600 hover:text-indigo-500 text-sm font-medium"
                            >
                                Limpiar filtros
                            </button>
                        </div>
                    )}
                </div>
            </div>
        </main>
    );
}

'use client';

import { Suspense, useEffect, useState } from 'react';
import { useSearchParams } from 'next/navigation';
import Link from 'next/link';
import { CheckCircle2, XCircle, Clock, AlertCircle, ArrowLeft, Home, Loader2 } from 'lucide-react';
import { paymentsService } from '@/services/payments.service';

type PaymentStatus = 'APPROVED' | 'DECLINED' | 'PENDING' | 'ERROR' | 'VOIDED' | 'loading';

interface TransactionDetails {
    id: string;
    reference: string;
    status: string;
    amount_in_cents: number;
    currency: string;
    payment_method_type: string;
    customer_email?: string;
    finalized_at?: string;
}

const STATUS_CONFIG: Record<string, {
    icon: React.ReactNode;
    title: string;
    description: string;
    color: string;
    bgColor: string;
}> = {
    APPROVED: {
        icon: <CheckCircle2 className="w-20 h-20" />,
        title: '¡Pago Exitoso!',
        description: 'Tu pago ha sido procesado correctamente. Recibirás un correo de confirmación en breve.',
        color: 'text-green-500',
        bgColor: 'bg-green-500/10',
    },
    DECLINED: {
        icon: <XCircle className="w-20 h-20" />,
        title: 'Pago Rechazado',
        description: 'Tu pago no pudo ser procesado. Por favor, verifica los datos e intenta nuevamente.',
        color: 'text-red-500',
        bgColor: 'bg-red-500/10',
    },
    PENDING: {
        icon: <Clock className="w-20 h-20" />,
        title: 'Pago Pendiente',
        description: 'Tu pago está siendo procesado. Te notificaremos cuando se complete.',
        color: 'text-yellow-500',
        bgColor: 'bg-yellow-500/10',
    },
    ERROR: {
        icon: <AlertCircle className="w-20 h-20" />,
        title: 'Error en el Pago',
        description: 'Ocurrió un error al procesar tu pago. Por favor, intenta nuevamente.',
        color: 'text-red-500',
        bgColor: 'bg-red-500/10',
    },
    VOIDED: {
        icon: <XCircle className="w-20 h-20" />,
        title: 'Pago Anulado',
        description: 'Este pago ha sido anulado.',
        color: 'text-gray-500',
        bgColor: 'bg-gray-500/10',
    },
    loading: {
        icon: <Loader2 className="w-20 h-20 animate-spin" />,
        title: 'Verificando pago...',
        description: 'Por favor espera mientras verificamos el estado de tu transacción.',
        color: 'text-blue-500',
        bgColor: 'bg-blue-500/10',
    },
};

function formatCurrency(cents: number, currency: string = 'COP'): string {
    const amount = cents / 100;
    return new Intl.NumberFormat('es-CO', {
        style: 'currency',
        currency,
        minimumFractionDigits: 0,
    }).format(amount);
}

function formatDate(dateString: string): string {
    return new Date(dateString).toLocaleString('es-CO', {
        dateStyle: 'long',
        timeStyle: 'short',
    });
}

// Componente interno que usa useSearchParams
function PaymentResponseContent() {
    const searchParams = useSearchParams();
    const [status, setStatus] = useState<PaymentStatus>('loading');
    const [transaction, setTransaction] = useState<TransactionDetails | null>(null);
    const [error, setError] = useState<string | null>(null);

    const transactionId = searchParams.get('id');
    const statusParam = searchParams.get('status');
    const reasonParam = searchParams.get('reason');

    useEffect(() => {
        const verifyPayment = async () => {
            if (!transactionId || transactionId === 'approved' || transactionId === 'failed') {
                // If it's a placeholder ID, use the status param directly
                if (statusParam === 'success') setStatus('APPROVED');
                else if (statusParam === 'failed') {
                    setStatus('DECLINED');
                    if (reasonParam) setError(`Razón: ${decodeURIComponent(reasonParam)}`);
                }
                else {
                    setStatus('ERROR');
                    setError('No se encontró el ID de la transacción');
                }
                return;
            }

            try {
                // Verificar el estado con Wompi a través de nuestro backend
                const data = await paymentsService.verifyPayment(transactionId);

                setTransaction(data);
                setStatus(data.status as PaymentStatus);
            } catch (err) {
                // Si falla la verificación, usar el status del parámetro si existe
                if (statusParam === 'success') {
                    setStatus('APPROVED');
                    // No logueamos error porque tenemos fallback
                } else if (statusParam === 'failed') {
                    setStatus('DECLINED');
                    // No logueamos error porque tenemos fallback
                } else {
                    console.error('Error verifying payment:', err);
                    setStatus('ERROR');
                    setError('No se pudo verificar el estado del pago');
                }
            }
        };

        verifyPayment();
    }, [transactionId, statusParam]);

    const config = STATUS_CONFIG[status] || STATUS_CONFIG.ERROR;

    return (
        <div className="max-w-2xl mx-auto">
            {/* Card principal */}
            <div className="bg-gray-800 rounded-2xl p-8 border border-gray-700 shadow-2xl">
                {/* Icono y estado */}
                <div className="text-center mb-8">
                    <div className={`inline-flex items-center justify-center w-32 h-32 rounded-full ${config.bgColor} ${config.color} mb-6`}>
                        {config.icon}
                    </div>
                    <h1 className="text-3xl font-bold text-white mb-2">
                        {config.title}
                    </h1>
                    <p className="text-gray-400">
                        {config.description}
                    </p>
                </div>

                {/* Detalles de la transacción */}
                {transaction && status !== 'loading' && (
                    <div className="bg-gray-900/50 rounded-xl p-6 mb-8">
                        <h2 className="text-lg font-semibold text-white mb-4">
                            Detalles de la Transacción
                        </h2>
                        <dl className="space-y-3">
                            <div className="flex justify-between">
                                <dt className="text-gray-400">ID de Transacción:</dt>
                                <dd className="text-white font-mono text-sm">{transaction.id}</dd>
                            </div>
                            <div className="flex justify-between">
                                <dt className="text-gray-400">Referencia:</dt>
                                <dd className="text-white font-mono text-sm">{transaction.reference}</dd>
                            </div>
                            <div className="flex justify-between">
                                <dt className="text-gray-400">Monto:</dt>
                                <dd className="text-white font-semibold">
                                    {formatCurrency(transaction.amount_in_cents, transaction.currency)}
                                </dd>
                            </div>
                            {transaction.payment_method_type && (
                                <div className="flex justify-between">
                                    <dt className="text-gray-400">Método de pago:</dt>
                                    <dd className="text-white">{transaction.payment_method_type}</dd>
                                </div>
                            )}
                            {transaction.customer_email && (
                                <div className="flex justify-between">
                                    <dt className="text-gray-400">Email:</dt>
                                    <dd className="text-white">{transaction.customer_email}</dd>
                                </div>
                            )}
                            {transaction.finalized_at && (
                                <div className="flex justify-between">
                                    <dt className="text-gray-400">Fecha:</dt>
                                    <dd className="text-white">{formatDate(transaction.finalized_at)}</dd>
                                </div>
                            )}
                        </dl>
                    </div>
                )}

                {/* Error message */}
                {error && (
                    <div className="bg-red-500/10 border border-red-500/30 rounded-xl p-4 mb-8">
                        <p className="text-red-400 text-sm text-center">{error}</p>
                    </div>
                )}

                {/* Botones de acción */}
                <div className="flex flex-col sm:flex-row gap-4">
                    {status === 'APPROVED' ? (
                        <>
                            <Link
                                href="/perfil"
                                className="flex-1 flex items-center justify-center gap-2 bg-[#83A98A] text-white rounded-lg px-6 py-3 font-semibold hover:bg-[#6B8E71] transition-colors"
                            >
                                Ir a Mi Perfil
                            </Link>
                            <Link
                                href="/"
                                className="flex-1 flex items-center justify-center gap-2 bg-gray-700 text-white rounded-lg px-6 py-3 font-semibold hover:bg-gray-600 transition-colors"
                            >
                                <Home className="w-4 h-4" />
                                Volver al Inicio
                            </Link>
                        </>
                    ) : status === 'DECLINED' || status === 'ERROR' ? (
                        <>
                            <Link
                                href="/pricing"
                                className="flex-1 flex items-center justify-center gap-2 bg-[#83A98A] text-white rounded-lg px-6 py-3 font-semibold hover:bg-[#6B8E71] transition-colors"
                            >
                                <ArrowLeft className="w-4 h-4" />
                                Intentar de Nuevo
                            </Link>
                            <Link
                                href="/"
                                className="flex-1 flex items-center justify-center gap-2 bg-gray-700 text-white rounded-lg px-6 py-3 font-semibold hover:bg-gray-600 transition-colors"
                            >
                                <Home className="w-4 h-4" />
                                Volver al Inicio
                            </Link>
                        </>
                    ) : status === 'PENDING' ? (
                        <Link
                            href="/"
                            className="w-full flex items-center justify-center gap-2 bg-gray-700 text-white rounded-lg px-6 py-3 font-semibold hover:bg-gray-600 transition-colors"
                        >
                            <Home className="w-4 h-4" />
                            Volver al Inicio
                        </Link>
                    ) : null}
                </div>
            </div>

            {/* Información de contacto */}
            <div className="mt-8 text-center">
                <p className="text-gray-400 text-sm">
                    ¿Tienes algún problema con tu pago?{' '}
                    <Link href="/contacto" className="text-[#83A98A] hover:underline">
                        Contáctanos
                    </Link>
                </p>
            </div>
        </div>
    );
}

// Loading fallback
function LoadingFallback() {
    return (
        <div className="max-w-2xl mx-auto">
            <div className="bg-gray-800 rounded-2xl p-8 border border-gray-700 shadow-2xl">
                <div className="text-center">
                    <div className="inline-flex items-center justify-center w-32 h-32 rounded-full bg-blue-500/10 text-blue-500 mb-6">
                        <Loader2 className="w-20 h-20 animate-spin" />
                    </div>
                    <h1 className="text-3xl font-bold text-white mb-2">
                        Cargando...
                    </h1>
                    <p className="text-gray-400">
                        Por favor espera mientras cargamos la información.
                    </p>
                </div>
            </div>
        </div>
    );
}

// Componente principal con Suspense
export default function PaymentResponsePage() {
    return (
        <div className="min-h-screen bg-gradient-to-br from-gray-900 via-gray-800 to-gray-900 py-12 px-4 sm:px-6 lg:px-8">
            <Suspense fallback={<LoadingFallback />}>
                <PaymentResponseContent />
            </Suspense>
        </div>
    );
}

'use client';

import { useRouter } from 'next/navigation';
import { useUserProfile } from '@/hooks/useUserProfile';
import { InterpreterRegistrationForm } from '@/components/landing/InterpreterRegistrationForm';
import { JobSeekerRegistrationForm } from '@/components/landing/JobSeekerRegistrationForm';
import {
    User as UserIcon,
    CreditCard,
    Loader2,
    FileText,
    LogOut,
    Crown
} from 'lucide-react';

// Sub-components
import { ProfileInfo } from '@/components/profile/ProfileInfo';
import { ApplicationsList } from '@/components/profile/ApplicationsList';
import { SubscriptionCard } from '@/components/profile/SubscriptionCard';
import { TransactionsList } from '@/components/profile/TransactionsList';

export default function ProfilePage() {
    const router = useRouter();
    const {
        user,
        transactions,
        subscription,
        applications,
        loading,
        activeTab,
        setActiveTab,
        editingApplication,
        setEditingApplication,
        handleLogout,
        refresh
    } = useUserProfile();

    const onLogout = async () => {
        await handleLogout();
        router.push('/');
    };

    if (loading) {
        return (
            <div className="min-h-screen bg-gray-900 flex items-center justify-center">
                <Loader2 className="w-8 h-8 text-[#83A98A] animate-spin" />
            </div>
        );
    }

    return (
        <div className="min-h-screen bg-gray-900 text-gray-100 font-sans">
            {/* Edit Modal Overlay */}
            {editingApplication && (
                <div className="fixed inset-0 z-50 flex items-center justify-center px-4 py-6 bg-black/80 backdrop-blur-sm overflow-y-auto">
                    <div className="w-full max-w-4xl max-h-full overflow-y-auto rounded-2xl relative">
                        {editingApplication.form?.type === 'interpreter_registration' ? (
                            <InterpreterRegistrationForm
                                initialData={editingApplication.data}
                                submissionId={editingApplication.id}
                                onSuccess={() => {
                                    setEditingApplication(null);
                                    refresh();
                                }}
                                onCancel={() => setEditingApplication(null)}
                            />
                        ) : editingApplication.form?.type === 'job_seeker_registration' ? (
                            <JobSeekerRegistrationForm
                                initialData={editingApplication.data}
                                submissionId={editingApplication.id}
                                onSuccess={() => {
                                    setEditingApplication(null);
                                    refresh();
                                }}
                                onCancel={() => setEditingApplication(null)}
                            />
                        ) : (
                            <div className="bg-white p-8 rounded-xl text-center">
                                <h3 className="text-xl font-bold text-gray-900 mb-2">Edición no disponible</h3>
                                <p className="text-gray-600 mb-6">
                                    Por el momento solo se puede editar el formulario de registro de intérprete o aspirante.
                                </p>
                                <button
                                    onClick={() => setEditingApplication(null)}
                                    className="bg-gray-900 text-white px-6 py-2 rounded-lg"
                                >
                                    Cerrar
                                </button>
                            </div>
                        )}
                    </div>
                </div>
            )}

            <div className="max-w-6xl mx-auto px-4 py-12">
                <header className="mb-10 flex flex-col md:flex-row md:items-center justify-between gap-6">
                    <div>
                        <h1 className="text-3xl font-bold text-white">Mi Cuenta</h1>
                        <p className="text-gray-400 mt-1">Administra tu perfil, suscripción y aplicaciones</p>
                    </div>
                </header>

                <div className="flex flex-col lg:flex-row gap-8">
                    {/* Sidebar / Tabs */}
                    <div className="w-full lg:w-64 flex-shrink-0">
                        <nav className="space-y-2 bg-gray-800 p-4 rounded-xl border border-gray-700">
                            {[
                                { id: 'profile', label: 'Perfil Personal', icon: UserIcon },
                                { id: 'applications', label: 'Mis Solicitudes', icon: FileText },
                                { id: 'subscription', label: 'Mi Suscripción', icon: Crown },
                                { id: 'transactions', label: 'Historial de Pagos', icon: CreditCard },
                            ].map((tab) => {
                                const Icon = tab.icon;
                                return (
                                    <button
                                        key={tab.id}
                                        onClick={() => setActiveTab(tab.id as any)}
                                        className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg transition-colors ${activeTab === tab.id
                                            ? 'bg-[#83A98A] text-white font-medium'
                                            : 'text-gray-400 hover:bg-gray-700/50 hover:text-white'
                                            }`}
                                    >
                                        <Icon className="w-5 h-5" />
                                        {tab.label}
                                    </button>
                                );
                            })}

                            <div className="pt-4 mt-4 border-t border-gray-700">
                                <button
                                    onClick={onLogout}
                                    className="w-full flex items-center gap-3 px-4 py-3 rounded-lg text-red-400 hover:bg-red-500/10 transition-colors"
                                >
                                    <LogOut className="w-5 h-5" />
                                    Cerrar Sesión
                                </button>
                            </div>
                        </nav>
                    </div>

                    {/* Main Content */}
                    <div className="flex-1">
                        {activeTab === 'profile' && <ProfileInfo user={user} />}
                        {activeTab === 'applications' && <ApplicationsList applications={applications} onEdit={setEditingApplication} />}
                        {activeTab === 'subscription' && <SubscriptionCard subscription={subscription} user={user} onUpdate={refresh} />}
                        {activeTab === 'transactions' && <TransactionsList transactions={transactions} />}
                    </div>
                </div>
            </div>
        </div>
    );
}

'use client';

import { useState, useEffect, Suspense } from 'react';
import { useSearchParams } from 'next/navigation';
import Link from 'next/link';

// Modular components
import { LockIcon, CheckCircleIcon, WarningIcon, SpinnerIcon } from '@/components/auth/Icons';
import { PasswordInput } from '@/components/auth/PasswordInput';
import { PasswordStrengthIndicator, getPasswordStrength } from '@/components/auth/PasswordStrengthIndicator';
import { StatusCard } from '@/components/auth/StatusCard';

// =============================================================================
// Constants
// =============================================================================

const API_URL = process.env.NEXT_PUBLIC_API_URL || '';

// =============================================================================
// Main Component
// =============================================================================

function ResetPasswordContent() {
    const searchParams = useSearchParams();

    // Form state
    const [password, setPassword] = useState('');
    const [confirmPassword, setConfirmPassword] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState<string | null>(null);

    // Screen state
    const [isSuccess, setIsSuccess] = useState(false);
    const [tokenError, setTokenError] = useState(false);

    // URL params from Supabase
    // URL params from Supabase (query params)
    const queryAccessToken = searchParams.get('access_token');
    const queryErrorDescription = searchParams.get('error_description');
    const type = searchParams.get('type');

    // State for the token (can come from query or hash)
    const [accessToken, setAccessToken] = useState<string | null>(queryAccessToken);

    // Validate token on mount and check hash
    useEffect(() => {
        // 1. Check for errors in query params
        if (queryErrorDescription) {
            setTokenError(true);
            setError(decodeURIComponent(queryErrorDescription));
            return;
        }

        // 2. Check hash for token if not in query params
        const checkHash = () => {
            if (typeof window !== 'undefined' && window.location.hash) {
                const hashParams = new URLSearchParams(window.location.hash.substring(1));
                const hashToken = hashParams.get('access_token');
                const hashError = hashParams.get('error_description');

                if (hashError) {
                    setTokenError(true);
                    setError(decodeURIComponent(hashError));
                    return true; // handled
                }

                if (hashToken) {
                    setAccessToken(hashToken);
                    return true; // found token
                }
            }
            return false;
        };

        const foundInHash = checkHash();

        // 3. Validation fallback logic
        // If we didn't find a token in hash AND we don't have one from query...
        if (!foundInHash && !queryAccessToken) {
            // Only show error if we are sure we needed one (e.g. type=recovery implies we expect a token)
            // Or if we just want to be strict that this page requires a token.
            // However, Supabase sometimes redirects without 'type' in hash mode.
            // Let's assume if no token is found at all, it's invalid.
            setTokenError(true);
            setError('El enlace de recuperación no es válido o está incompleto.');
        } else {
            // If we found a token (either query or hash), clear any previous token error
            setTokenError(false);
        }

    }, [queryAccessToken, queryErrorDescription, type]);

    // Form validation
    const passwordStrength = getPasswordStrength(password);
    const passwordsMatch = password === confirmPassword;
    const canSubmit = password && confirmPassword && passwordsMatch && passwordStrength >= 2;

    // Form submission
    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setError(null);

        if (password.length < 6) {
            setError('La contraseña debe tener al menos 6 caracteres');
            return;
        }

        if (!passwordsMatch) {
            setError('Las contraseñas no coinciden');
            return;
        }

        if (passwordStrength < 2) {
            setError('Por favor, usa una contraseña más segura');
            return;
        }

        setIsLoading(true);

        try {
            const response = await fetch(`${API_URL}/auth/update-password`, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'Authorization': `Bearer ${accessToken}`,
                },
                body: JSON.stringify({ password }),
            });

            const data = await response.json();

            if (!response.ok) {
                throw new Error(data.message || 'Error al actualizar la contraseña');
            }

            setIsSuccess(true);
        } catch (err: any) {
            console.error('Error updating password:', err);
            setError(err.message || 'Ocurrió un error al actualizar la contraseña');
        } finally {
            setIsLoading(false);
        }
    };

    // ==========================================================================
    // Render: Success Screen
    // ==========================================================================
    if (isSuccess) {
        return (
            <StatusCard
                type="success"
                icon={<CheckCircleIcon />}
                title="¡Contraseña Actualizada!"
                message="Tu contraseña ha sido cambiada exitosamente. Ya puedes iniciar sesión con tu nueva contraseña."
                buttonText="Ir al inicio"
                buttonHref="/"
            />
        );
    }

    // ==========================================================================
    // Render: Token Error Screen
    // ==========================================================================
    if (tokenError) {
        return (
            <StatusCard
                type="error"
                icon={<WarningIcon />}
                title="Enlace Inválido"
                message={error || 'El enlace de recuperación no es válido o ha expirado. Por favor, solicita uno nuevo.'}
                buttonText="Volver al inicio"
                buttonHref="/"
            />
        );
    }

    // ==========================================================================
    // Render: Main Form
    // ==========================================================================
    return (
        <div className="fixed inset-0 z-50 bg-gradient-to-br from-gray-50 via-white to-tincadia-green-light/20 flex items-center justify-center p-4 overflow-y-auto">
            {/* Decorative background */}
            <BackgroundDecorations />

            <div className="relative w-full max-w-md">
                {/* Brand */}
                <div className="text-center mb-8">
                    <h1 className="text-3xl font-bold text-tincadia-green">Tincadia</h1>
                    <p className="text-gray-500 mt-2">Comunicación sin barreras</p>
                </div>

                {/* Form Card */}
                <div className="bg-white border border-gray-200 rounded-3xl p-8 shadow-xl">
                    {/* Header */}
                    <div className="text-center mb-8">
                        <div className="mx-auto w-16 h-16 bg-tincadia-green/10 border border-tincadia-green/30 rounded-2xl flex items-center justify-center mb-4">
                            <div className="text-tincadia-green">
                                <LockIcon />
                            </div>
                        </div>
                        <h2 className="text-2xl font-bold text-gray-800 mb-2">Nueva Contraseña</h2>
                        <p className="text-gray-500 text-sm">Crea una contraseña segura para tu cuenta</p>
                    </div>

                    {/* Form */}
                    <form onSubmit={handleSubmit} className="space-y-5">
                        {/* Password field */}
                        <div>
                            <PasswordInput
                                label="Nueva contraseña"
                                value={password}
                                onChange={(val) => {
                                    setPassword(val);
                                    setError(null);
                                }}
                                disabled={isLoading}
                            />
                            <PasswordStrengthIndicator password={password} />
                        </div>

                        {/* Confirm password field */}
                        <div>
                            <PasswordInput
                                label="Confirmar contraseña"
                                value={confirmPassword}
                                onChange={(val) => {
                                    setConfirmPassword(val);
                                    setError(null);
                                }}
                                disabled={isLoading}
                                error={!!confirmPassword && !passwordsMatch}
                                success={!!confirmPassword && passwordsMatch}
                            />
                            {confirmPassword && !passwordsMatch && (
                                <p className="text-red-500 text-xs mt-1">Las contraseñas no coinciden</p>
                            )}
                            {confirmPassword && passwordsMatch && (
                                <p className="text-tincadia-green text-xs mt-1">✓ Las contraseñas coinciden</p>
                            )}
                        </div>

                        {/* Error message */}
                        {error && (
                            <div className="p-4 bg-red-50 border border-red-200 rounded-xl">
                                <p className="text-red-600 text-sm text-center">{error}</p>
                            </div>
                        )}

                        {/* Submit button */}
                        <SubmitButton isLoading={isLoading} disabled={!canSubmit} />
                    </form>

                    {/* Footer link */}
                    <div className="mt-6 text-center">
                        <Link href="/" className="text-gray-500 hover:text-tincadia-green transition-colors text-sm">
                            ← Volver al inicio
                        </Link>
                    </div>
                </div>

                {/* Security note */}
                <p className="text-center text-gray-400 text-xs mt-6">
                    Tu conexión está protegida con encriptación
                </p>
            </div>
        </div>
    );
}

// =============================================================================
// Sub-components
// =============================================================================

function BackgroundDecorations() {
    return (
        <>
            <div className="absolute inset-0 overflow-hidden">
                <div className="absolute -top-40 -right-40 w-80 h-80 bg-tincadia-green/15 rounded-full blur-3xl" />
                <div className="absolute -bottom-40 -left-40 w-80 h-80 bg-tincadia-green-light/25 rounded-full blur-3xl" />
                <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-96 h-96 bg-tincadia-green/5 rounded-full blur-3xl" />
            </div>
            <div className="absolute inset-0 bg-[linear-gradient(rgba(131,169,138,0.03)_1px,transparent_1px),linear-gradient(90deg,rgba(131,169,138,0.03)_1px,transparent_1px)] bg-[size:50px_50px]" />
        </>
    );
}

function SubmitButton({ isLoading, disabled }: { isLoading: boolean; disabled: boolean }) {
    return (
        <button
            type="submit"
            disabled={isLoading || disabled}
            className="w-full py-4 px-6 bg-gradient-to-r from-[#83A98A] to-[#6D8F75] text-white font-semibold rounded-xl hover:shadow-lg hover:shadow-[#83A98A]/25 transition-all duration-300 hover:scale-[1.02] disabled:opacity-50 disabled:cursor-not-allowed disabled:hover:scale-100 relative overflow-hidden group"
        >
            {isLoading ? (
                <div className="flex items-center justify-center gap-2">
                    <SpinnerIcon />
                    <span>Actualizando...</span>
                </div>
            ) : (
                <>
                    <span className="relative z-10">Actualizar Contraseña</span>
                    <div className="absolute inset-0 bg-gradient-to-r from-[#6D8F75] to-[#83A98A] opacity-0 group-hover:opacity-100 transition-opacity duration-300" />
                </>
            )}
        </button>
    );
}

// =============================================================================
// Page Export
// =============================================================================

export default function ResetPasswordPage() {
    return (
        <Suspense fallback={<LoadingSpinner />}>
            <ResetPasswordContent />
        </Suspense>
    );
}

function LoadingSpinner() {
    return (
        <div className="fixed inset-0 z-50 bg-gradient-to-br from-gray-50 via-white to-tincadia-green-light/20 flex items-center justify-center">
            <div className="animate-spin h-8 w-8 border-2 border-tincadia-green border-t-transparent rounded-full" />
        </div>
    );
}

'use client';

import React from 'react';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';

interface AdminAnalyticsChartProps {
    data: any[];
    loading?: boolean;
}

export function AdminAnalyticsChart({ data, loading }: AdminAnalyticsChartProps) {
    // Mock data if empty or loading to show skeleton/placeholder
    const chartData = data && data.length > 0 ? data : [
        { labels: 'Mon', value: 0 },
        { labels: 'Tue', value: 0 },
        { labels: 'Wed', value: 0 },
        { labels: 'Thu', value: 0 },
        { labels: 'Fri', value: 0 },
        { labels: 'Sat', value: 0 },
        { labels: 'Sun', value: 0 },
    ];

    if (loading) {
        return (
            <div className="w-full h-[300px] bg-slate-900 border border-slate-800 rounded-2xl animate-pulse flex items-center justify-center">
                <span className="text-slate-700 font-medium">Cargando métricas...</span>
            </div>
        );
    }

    return (
        <div className="w-full bg-slate-900 border border-slate-800 rounded-2xl p-6 shadow-xl">
            <div className="mb-6">
                <h3 className="text-lg font-bold text-white">Actividad de Usuarios</h3>
                <p className="text-slate-500 text-sm">Visitas únicas en los últimos 7 días</p>
            </div>

            <div className="h-[300px] w-full">
                <ResponsiveContainer width="100%" height="100%">
                    <AreaChart
                        data={chartData}
                        margin={{
                            top: 10,
                            right: 30,
                            left: 0,
                            bottom: 0,
                        }}
                    >
                        <defs>
                            <linearGradient id="colorValue" x1="0" y1="0" x2="0" y2="1">
                                <stop offset="5%" stopColor="#83A98A" stopOpacity={0.3} />
                                <stop offset="95%" stopColor="#83A98A" stopOpacity={0} />
                            </linearGradient>
                        </defs>
                        <CartesianGrid strokeDasharray="3 3" stroke="#1e293b" vertical={false} />
                        <XAxis
                            dataKey="labels" // Posthog usually returns 'labels' or 'days'
                            stroke="#64748b"
                            fontSize={12}
                            tickLine={false}
                            axisLine={false}
                        />
                        <YAxis
                            stroke="#64748b"
                            fontSize={12}
                            tickLine={false}
                            axisLine={false}
                            tickFormatter={(value) => `${value}`}
                        />
                        <Tooltip
                            contentStyle={{
                                backgroundColor: '#0f172a',
                                borderColor: '#1e293b',
                                color: '#f8fafc',
                                borderRadius: '8px'
                            }}
                            itemStyle={{ color: '#83A98A' }}
                        />
                        <Area
                            type="monotone"
                            dataKey="data" // Posthog trend data
                            stroke="#83A98A"
                            strokeWidth={3}
                            fillOpacity={1}
                            fill="url(#colorValue)"
                        />
                    </AreaChart>
                </ResponsiveContainer>
            </div>
        </div>
    );
}

