                                    visibility: initialOpacity > 0 ? 'visible' : 'hidden',
                                }}
                            >
                                <div className="mx-auto max-w-7xl px-6 lg:px-8 w-full flex flex-col lg:flex-row items-start lg:items-center gap-12 pointer-events-auto">
