            </p>
          </div>
        </div>
      </div>
    </footer>
  );
}

'use client';

import { useState } from 'react';
import { X, Loader2, ArrowLeft, Mail } from 'lucide-react';
import { useTranslation } from '@/hooks/useTranslation';
import { GridBackground } from '@/components/ui/GridBackground';
import { authService } from '@/services/auth.service';
import { useUI } from '@/contexts/UIContext';

interface ForgotPasswordPanelProps {
    isOpen: boolean;
    onClose: () => void;
}

export function ForgotPasswordPanel({ isOpen, onClose }: ForgotPasswordPanelProps) {
    const t = useTranslation();
    const { openLoginPanel } = useUI();

    // States
    const [email, setEmail] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const [success, setSuccess] = useState(false);

    const handleBackToLogin = () => {
        onClose();
        openLoginPanel();
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setError(null);
        setIsLoading(true);

        try {
            await authService.forgotPassword({ email });
            setSuccess(true);
        } catch (err) {
            console.error(err);
            // Default error message if the service call fails
            setError('Error al enviar el correo. Por favor verifica que el email sea correcto.');
        } finally {
            setIsLoading(false);
        }
    };

    const handleClose = () => {
        setEmail('');
        setError(null);
        setSuccess(false);
        onClose();
    };

    return (
        <>
            {isOpen && (
                <div
                    className="fixed inset-0 bg-black/50 z-40 lg:bg-black/30 transition-opacity"
                    onClick={handleClose}
                    aria-hidden="true"
                />
            )}

            <div
                className={`fixed top-0 right-0 h-full w-full lg:w-1/3 bg-white shadow-2xl z-50 transform transition-transform duration-300 ease-out ${isOpen ? 'translate-x-0' : 'translate-x-full'
                    } overflow-hidden`}
            >
                <GridBackground className="absolute inset-0 -z-10" />
                <div className="h-full flex flex-col overflow-y-auto relative z-10">
                    <div className="flex items-center justify-between p-6">
                        <button
                            onClick={handleBackToLogin}
                            className="p-2 hover:bg-gray-100 rounded-full transition-colors flex items-center gap-2 text-gray-600 font-medium"
                        >
                            <ArrowLeft className="w-5 h-5" />
                            <span>Volver</span>
                        </button>
                        <button
                            onClick={handleClose}
                            className="p-2 hover:bg-gray-100 rounded-full transition-colors"
                        >
                            <X className="w-6 h-6 text-gray-600" />
                        </button>
                    </div>

                    <div className="flex-1 px-6 pb-6 pt-10">
                        <div className="space-y-8">
                            <div>
                                <h2 className="text-2xl font-bold text-gray-900 mb-2">
                                    Recuperar Contraseña
                                </h2>
                                <p className="text-gray-600">
                                    Ingresa tu correo electrónico y te enviaremos las instrucciones para restablecer tu contraseña.
                                </p>
                            </div>

                            {!success ? (
                                <form onSubmit={handleSubmit} className="space-y-6">
                                    <div>
                                        <label htmlFor="email" className="block text-sm font-medium text-gray-700 mb-1">
                                            Correo Electrónico
                                        </label>
                                        <div className="relative">
                                            <input
                                                id="email"
                                                type="email"
                                                value={email}
                                                onChange={(e) => setEmail(e.target.value)}
                                                className="w-full bg-transparent text-lg text-gray-900 placeholder-gray-400 border-0 border-b border-gray-300 focus:outline-none focus:border-gray-900 transition-colors pb-2 pl-9"
                                                placeholder="tu@email.com"
                                                required
                                            />
                                            <Mail className="absolute left-0 bottom-2.5 w-5 h-5 text-gray-400" />
                                        </div>
                                    </div>

                                    {error && (
                                        <div className="p-3 bg-red-50 border border-red-200 rounded-lg">
                                            <p className="text-sm text-red-600">{error}</p>
                                        </div>
                                    )}

                                    <button
                                        type="submit"
                                        disabled={isLoading || !email}
                                        className="w-full bg-[#83A98A] text-white font-semibold py-4 px-6 rounded-full hover:bg-[#6D8F75] transition-colors flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed"
                                    >
                                        {isLoading ? (
                                            <>
                                                <Loader2 className="w-5 h-5 animate-spin" />
                                                <span>Enviando...</span>
                                            </>
                                        ) : (
                                            <span>Enviar Instrucciones</span>
                                        )}
                                    </button>
                                </form>
                            ) : (
                                <div className="bg-green-50 border border-green-200 rounded-xl p-6 text-center space-y-4">
                                    <div className="w-16 h-16 bg-green-100 rounded-full flex items-center justify-center mx-auto">
                                        <Mail className="w-8 h-8 text-green-600" />
                                    </div>
                                    <h3 className="text-lg font-semibold text-green-900">¡Correo Enviado!</h3>
                                    <p className="text-green-700">
                                        Hemos enviado las instrucciones a <strong>{email}</strong>.
                                        Revisa tu bandeja de entrada (y spam) para continuar.
                                    </p>
                                    <button
                                        onClick={handleClose}
                                        className="mt-4 px-6 py-2 bg-green-600 text-white rounded-full font-medium hover:bg-green-700 transition-colors"
                                    >
                                        Entendido
                                    </button>
                                </div>
                            )}
                        </div>
                    </div>
                </div>
            </div>
        </>
    );
}

'use client';

import Image from 'next/image';
import { useEffect, useRef, useState, useMemo } from 'react';
import { useTranslation } from '@/hooks/useTranslation';
import { useUI } from '@/contexts/UIContext';
import { contentService, type LandingConfigItem } from '@/services/content.service';

// Letras del título principal
const TINCADIA_LETTERS = ['T', 'I', 'N', 'C', 'A', 'D', 'I', 'A'];

interface HeroProps {
  disableAnimations?: boolean;
}

export function Hero({ disableAnimations = false }: HeroProps) {
  const t = useTranslation();
  const videoRef = useRef<HTMLVideoElement>(null);

  const [videoUrl, setVideoUrl] = useState<string>('https://res.cloudinary.com/dzi2p0pqa/video/upload/v1768965559/c7q4e37io3ahtjscooxx.mp4');
  const [alliances, setAlliances] = useState<LandingConfigItem[]>([]);

  // Fetch content from DB
  useEffect(() => {
    const fetchContent = async () => {
      try {
        const configs = await contentService.getLandingConfigs();

        // Find video
        const videoConfig = configs.find(c => c.key === 'hero_video_url');
        if (videoConfig?.value) {
          setVideoUrl(videoConfig.value);
        }

        // Find alliances/logos
        const allianceConfigs = configs.filter(c =>
          c.key.startsWith('logo_') || c.key.startsWith('alliance_')
        );
        setAlliances(allianceConfigs);

      } catch (error) {
        console.error('Error fetching landing content:', error);
      }
    };
    fetchContent();
  }, []);


  const [currentStep, setCurrentStep] = useState(0);
  const [showDescription, setShowDescription] = useState(false);
  const [showTincadia, setShowTincadia] = useState(false);
  const [showWord, setShowWord] = useState(false);
  const [showVideo, setShowVideo] = useState(false);
  const [email, setEmail] = useState('');
  const [isEmailValid, setIsEmailValid] = useState(false);
  const [isSubmitted, setIsSubmitted] = useState(false);

  const { setIsRegistrationPanelOpen, setRegistrationEmail: setGlobalEmail } = useUI();

  // Radio del círculo de letras (responsive)
  const [circleRadius, setCircleRadius] = useState(100);

  // Ángulo global para la órbita de las letras
  const [orbitAngle, setOrbitAngle] = useState(0);

  // Pasos de animación: qué letras resaltar y qué palabra mostrar
  const CONCEPT_STEPS = useMemo(() => [
    {
      highlights: [0], // T
      label: t('hero.concepts.technology'),
    },
    {
      highlights: [1, 2, 3], // INC
      label: t('hero.concepts.inclusion'),
    },
    {
      highlights: [4], // A
      label: t('hero.concepts.accessibility'),
    },
    {
      highlights: [5], // D
      label: t('hero.concepts.disability'),
    },
    {
      highlights: [6, 7], // IA (segunda I y segunda A)
      label: t('hero.concepts.ai'),
    },
  ], [t]);

  // Asegurar que el video se reproduce en loop
  useEffect(() => {
    const video = videoRef.current;
    if (video) {
      video.play().catch((error) => {
        console.log('Video autoplay prevented:', error);
      });
    }
  }, []);

  // Ajustar el radio en base al tamaño de pantalla
  useEffect(() => {
    const handleResize = () => {
      const width = window.innerWidth;

      if (width < 1024) {
        // MÓVIL Y TABLET (hasta 921px)
        setCircleRadius(100);
      } else {
        // DESKTOP
        setCircleRadius(220);
      }
    };

    handleResize(); // calcular al montar
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  // Animación de la órbita de las letras usando requestAnimationFrame para máxima fluidez
  useEffect(() => {
    if (disableAnimations) return;

    let animationFrameId: number;
    let lastTime = 0;
    const targetFPS = 60;
    const frameInterval = 1000 / targetFPS;
    const degreesPerSecond = 360 / 30; // 30 segundos por vuelta completa

    const animate = (currentTime: number) => {
      if (currentTime - lastTime >= frameInterval) {
        setOrbitAngle((prev) => {
          const increment = (degreesPerSecond * frameInterval) / 1000;
          return (prev + increment) % 360;
        });
        lastTime = currentTime;
      }
      animationFrameId = requestAnimationFrame(animate);
    };

    animationFrameId = requestAnimationFrame(animate);

    return () => {
      if (animationFrameId) {
        cancelAnimationFrame(animationFrameId);
      }
    };
  }, [disableAnimations]);


  // Animación inicial: mostrar TINCADIA, video, texto y arrancar ciclo de conceptos
  useEffect(() => {
    let intervalId: NodeJS.Timeout;

    const showTincadiaTimer = setTimeout(() => {
      setShowTincadia(true);
    }, 150);

    const showVideoTimer = setTimeout(() => {
      setShowVideo(true);
    }, 150);

    const showWordAndCycleTimer = setTimeout(() => {
      setShowWord(true);

      if (disableAnimations) return;

      // Iniciar ciclo fluido de conceptos con transición suave
      intervalId = setInterval(() => {
        setCurrentStep((prev) => (prev + 1) % CONCEPT_STEPS.length);
      }, 1750);
    }, 750);

    const showDescTimer = setTimeout(() => {
      setShowDescription(true);
    }, 1500);

    // IMPORTANTE: cleanup
    return () => {
      clearTimeout(showTincadiaTimer);
      clearTimeout(showVideoTimer);
      clearTimeout(showWordAndCycleTimer);
      clearTimeout(showDescTimer);
      if (intervalId) clearInterval(intervalId);
    };
  }, [disableAnimations]);

  const currentConcept = CONCEPT_STEPS[currentStep];

  return (
    <section
      className="relative bg-transparent pt-0 pb-4 lg:pt-20 lg:pb-6 overflow-visible"
      aria-labelledby="hero-heading"
    >
      {/* Contenedor principal */}
      <div className="mx-auto max-w-7xl px-6 lg:px-8 relative z-10">

        <div className="grid lg:grid-cols-2 gap-2 lg:gap-24 items-center">
          {/* Columna de texto */}
          <div className="text-center lg:text-left z-10 order-2 lg:order-1">

            <h1
              id="hero-heading"
              className="flex flex-col items-center text-center gap-2 lg:block lg:text-left"
            >
              {/* TINCADIA en grande, negro, con letras resaltadas en verde */}
              <span
                className={`block font-extrabold tracking-tight ${showTincadia ? 'animate-reveal' : 'opacity-0'
                  }
              text-5xl sm:text-6xl lg:text-7xl`}
                style={{ animationDelay: '0s' }}
              >
                {TINCADIA_LETTERS.map((letter, index) => {
                  const isHighlighted = currentConcept.highlights.includes(index);
                  return (
                    <span
                      key={index}
                      className={`inline-block transition-all ease-in-out ${isHighlighted
                        ? 'text-[#83A98A] scale-110'
                        : 'text-gray-900 scale-100'
                        }`}
                      style={{
                        transitionProperty: 'color, transform',
                        transitionDuration: '350ms',
                      }}
                    >
                      {letter}
                    </span>
                  );
                })}
              </span>

              {/* Palabra / concepto en verde, más pequeño */}
              <span
                className={`block font-semibold text-[#83A98A] text-xl sm:text-2xl lg:text-3xl transition-all ease-in-out ${showWord ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-2'
                  }`}
                style={{ transitionDuration: '250ms' }}
                key={currentStep}
              >
                {currentConcept.label}
              </span>
            </h1>

            <p
              className={`mt-6 text-lg leading-8 text-gray-600 max-w-2xl mx-auto lg:mx-0 transition-all duration-1000 ${showDescription
                ? 'opacity-100 translate-y-0'
                : 'opacity-0 translate-y-8'
                }`}
              dangerouslySetInnerHTML={{ __html: t('hero.description') }}
            />

            {/* Input + Botón fusionado */}
            <div
              className={`mt-10 flex flex-col sm:flex-row gap-0 justify-center lg:justify-start transition-all duration-1000 delay-300 ${showDescription
                ? 'opacity-100 translate-y-0'
                : 'opacity-0 translate-y-8'
                }`}
            >
              <input
                type="email"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                placeholder={t('hero.emailPlaceholder')}
                className="flex-1 px-4 py-3.5 text-base bg-white border border-gray-300 rounded-l-lg sm:rounded-r-none rounded-r-lg sm:border-r-0 focus:outline-none focus:ring-2 focus:ring-[#83A98A] focus:border-transparent transition-all"
                aria-label={t('hero.emailLabel')}
              />
              <button
                onClick={() => {
                  setGlobalEmail(email);
                  setIsRegistrationPanelOpen(true);
                  setIsSubmitted(true);
                }}
                className="rounded-r-lg sm:rounded-l-none rounded-l-lg sm:rounded-r-lg bg-white px-8 py-3.5 text-base font-semibold text-gray-900 shadow-sm ring-1 ring-inset ring-gray-300 hover:bg-gray-50 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-[#83A98A] transition-colors whitespace-nowrap"
                aria-label={t('hero.startButtonLabel')}
              >
                {t('hero.startButton')}
              </button>
            </div>
          </div>

          {/* Columna de video / círculo */}
          <div
            className={`relative lg:h-[500px] flex items-center justify-center transition-all duration-1000 overflow-visible order-1 lg:order-2 ${showVideo ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-8'
              }`}
          >
            <div className="relative w-[300px] h-[300px] lg:w-[750px] lg:h-[750px] flex items-center justify-center overflow-visible">
              {/* Círculo del video */}
              <div className="relative w-[160px] h-[160px] lg:w-[450px] lg:h-[450px] z-0">
                <div
                  className="absolute inset-0 bg-[#83A98A]/20 rounded-full blur-3xl"
                  aria-hidden="true"
                />

                <div className="relative w-full h-full rounded-full overflow-hidden bg-[#83A98A] shadow-2xl ring-8 ring-white">
                  <video
                    key={videoUrl}
                    ref={videoRef}
                    className="w-full h-full object-cover scale-100"
                    style={{ objectPosition: 'center center' }}
                    autoPlay
                    loop
                    muted
                    playsInline
                    aria-label="Video de presentación de Tincadia"
                  >
                    <source
                      src={videoUrl}
                      type="video/mp4"
                    />
                    Tu navegador no soporta el elemento de video.
                  </video>
                </div>
              </div>

              {/* Letras orbitando alrededor del círculo */}
              <div className="absolute inset-0 z-10 overflow-visible">
                {['T', 'E', 'C', 'N', 'O', 'L', 'O', 'G', 'I', 'A'].map(
                  (letter, index) => {
                    const totalLetters = 10;
                    const baseAngle = (index * 360) / totalLetters - 90;
                    const totalAngle = baseAngle + orbitAngle;
                    const radius = circleRadius;
                    const animationDelay = (index * 20) / totalLetters;

                    return (
                      <span
                        key={index}
                        className="absolute text-xl sm:text-3xl lg:text-4xl font-bold text-black transition-transform duration-75 ease-linear"
                        style={{
                          left: '50%',
                          top: '50%',
                          width: '1em',
                          height: '1em',
                          marginLeft: '-0.5em',
                          marginTop: '-0.5em',
                          transform: `rotate(${totalAngle}deg) translateX(${radius}px) rotate(${-totalAngle}deg)`,
                          transformOrigin: 'center center',
                          animationDelay: `${-animationDelay}s`,
                          willChange: 'transform',
                        }}
                      >
                        {letter}
                      </span>
                    );
                  }
                )}
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Sección de Logos */}
      <div className="mt-16 lg:mt-20 py-12 bg-white border-y border-gray-100">
        <div className="mx-auto max-w-7xl px-6 lg:px-8 mb-8">
          <h2 className="text-center text-2xl sm:text-3xl lg:text-4xl font-bold text-gray-900 tracking-tight">
            En nosotros{' '}
            <span className="text-[#5A7A62] relative inline-block">
              confían
              <span
                className="absolute bottom-0 left-0 w-full h-1 bg-[#5A7A62]/30"
                aria-hidden="true"
              />
            </span>
          </h2>
        </div>

        <div className="relative overflow-hidden w-full">
          <div
            className="absolute left-0 top-0 bottom-0 w-24 md:w-32 lg:w-40 bg-gradient-to-r from-white via-white/80 to-transparent z-10 pointer-events-none"
            aria-hidden="true"
          />
          <div
            className="absolute right-0 top-0 bottom-0 w-24 md:w-32 lg:w-40 bg-gradient-to-l from-white via-white/80 to-transparent z-10 pointer-events-none"
            aria-hidden="true"
          />
          <div className="relative overflow-hidden">
            <div className="flex items-center animate-scroll py-4 gap-8 md:gap-10 w-max">
              {alliances.length > 0 ? (
                // Seamless Loop: Render the list multiple times (even number) to ensure the total width is large enough.
                // We repeat 12 times. The animation 'animate-scroll' moves -50% (shifting 6 sets).
                // As long as 6 sets are wider than the screen, the loop is invisible.
                Array(12).fill(alliances).flat().map((alliance, index) => (
                  <div
                    // Use index in key because we have duplicates
                    key={`${index}-${alliance.key}`}
                    className="relative h-6 w-20 md:h-8 md:w-24 lg:h-10 lg:w-28 flex-shrink-0 grayscale hover:grayscale-0 transition-all duration-300 opacity-60 hover:opacity-100"
                    title={alliance.description || ''}
                  >
                    <Image
                      src={alliance.value}
                      alt={alliance.description || "Alianza"}
                      fill
                      className="object-contain"
                      sizes="(max-width: 768px) 80px, (max-width: 1024px) 96px, 112px"
                    />
                  </div>
                ))
              ) : (
                // Skeleton loading state or empty
                <div className="flex items-center justify-center w-full h-10">
                  <span className="text-gray-400 text-sm">Cargando alianzas...</span>
                </div>
              )}
            </div>
          </div>
        </div>

        <div className="mx-auto max-w-7xl px-6 lg:px-8 mt-6">
          <p className="text-center text-sm text-gray-500 italic">
            Pasa el cursor sobre los logos para verlos a color
          </p>
        </div>
      </div>

      {/* Registration Panel removed from here as it is now global in page.tsx */}
    </section>
  );
}

'use client';

import { useState, useEffect, useRef, useMemo } from 'react';
import { Mic, FileText, Video, PenTool } from 'lucide-react';
import { useTranslation } from '@/hooks/useTranslation';
import { contentService } from '@/services/content.service';

interface LandingConfigItem {
  key: string;
  value: string;
  description?: string;
}

export function HowToStart() {
  const t = useTranslation();
  const [mediaConfigs, setMediaConfigs] = useState<Record<string, string>>({});

  useEffect(() => {
    const fetchConfigs = async () => {
      try {
        const configs = await contentService.getLandingConfigs();
        const mediaMap: Record<string, string> = {};
        // Iterate over the array since getLandingConfigs returns LandingConfigItem[]
        if (Array.isArray(configs)) {
          configs.forEach((item: any) => {
            if (item.key && item.key.startsWith('how_to_start_step_')) {
              mediaMap[item.key] = item.value;
            }
          });
        }
        setMediaConfigs(mediaMap);
      } catch (error) {
        console.error('Error fetching landing configs:', error);
      }
    };
    fetchConfigs();
  }, []);

  const features = useMemo(() => {
    const getSteps = (key: string): string[] => {
      const steps = t(key);
      return Array.isArray(steps) ? steps : [];
    };

    return [
      {
        id: 1,
        title: t('howToStart.features.voiceToText.title'),
        subtitle: t('howToStart.features.voiceToText.subtitle'),
        description: t('howToStart.features.voiceToText.description'),
        icon: Mic,
        videoLabel: t('howToStart.features.voiceToText.title'),
        steps: getSteps('howToStart.features.voiceToText.steps'),
        color: 'from-blue-500 to-blue-600',
        bgColor: 'bg-blue-50',
      },
      {
        id: 2,
        title: t('howToStart.features.translation.title'),
        subtitle: t('howToStart.features.translation.subtitle'),
        description: t('howToStart.features.translation.description'),
        icon: FileText,
        videoLabel: t('howToStart.features.translation.title'),
        steps: getSteps('howToStart.features.translation.steps'),
        color: 'from-green-500 to-green-600',
        bgColor: 'bg-green-50',
      },
      {
        id: 3,
        title: t('howToStart.features.interpretation.title'),
        subtitle: t('howToStart.features.interpretation.subtitle'),
        description: t('howToStart.features.interpretation.description'),
        icon: Video,
        videoLabel: t('howToStart.features.interpretation.title'),
        steps: getSteps('howToStart.features.interpretation.steps'),
        color: 'from-purple-500 to-purple-600',
        bgColor: 'bg-purple-50',
      },
      {
        id: 4,
        title: t('howToStart.features.writingAssistant.title'),
        subtitle: t('howToStart.features.writingAssistant.subtitle'),
        description: t('howToStart.features.writingAssistant.description'),
        icon: PenTool,
        videoLabel: t('howToStart.features.writingAssistant.title'),
        steps: getSteps('howToStart.features.writingAssistant.steps'),
        color: 'from-orange-500 to-orange-600',
        bgColor: 'bg-orange-50',
      },
    ];
  }, [t]);
  const [activeTab, setActiveTab] = useState(1);
  const [isTransitioning, setIsTransitioning] = useState(false);
  const [displayTab, setDisplayTab] = useState(1);
  const [progress, setProgress] = useState(0);
  const [isManualChange, setIsManualChange] = useState(false);
  const sectionRef = useRef<HTMLElement>(null);
  const contentRef = useRef<HTMLDivElement>(null);

  const handleTabChange = (newTab: number) => {
    if (newTab === activeTab) return;

    setIsManualChange(true);
    setIsTransitioning(true);
    setProgress(0); // Reiniciar progreso inmediatamente

    // Después de la animación de salida, cambiar el contenido
    setTimeout(() => {
      setDisplayTab(newTab);
      setActiveTab(newTab);
      setIsTransitioning(false);

      // Permitir que el scroll vuelva a controlar después de un tiempo
      setTimeout(() => {
        setIsManualChange(false);
      }, 1000);
    }, 300);
  };

  // Scroll parallax effect
  useEffect(() => {
    const handleScroll = () => {
      if (!sectionRef.current) return;

      const section = sectionRef.current;

      // Obtener posición de la sección
      const rect = section.getBoundingClientRect();
      const windowHeight = window.innerHeight;
      const scrollY = window.scrollY;

      // Calcular cuando la sección entra en viewport
      // Empezamos cuando el top de la sección está en el viewport
      const sectionTop = scrollY + rect.top;
      const sectionBottom = sectionTop + rect.height;

      // Calcular el rango de scroll efectivo (desde que entra hasta que sale)
      const scrollStart = sectionTop - windowHeight * 0.5; // Empezar cuando está a mitad de pantalla
      const scrollEnd = sectionBottom - windowHeight * 0.5;
      const scrollRange = scrollEnd - scrollStart;

      if (scrollRange <= 0) return;

      // Calcular el progreso del scroll dentro de la sección
      const currentScroll = scrollY - scrollStart;
      const scrollProgress = Math.max(0, Math.min(1, currentScroll / scrollRange));

      // Dividir el progreso entre las features
      // Cada feature ocupa 1/n del scroll total
      const featureProgress = scrollProgress * features.length;
      const currentFeatureIndex = Math.min(
        Math.floor(featureProgress),
        features.length - 1
      );
      const featureLocalProgress = (featureProgress - currentFeatureIndex) * 100;

      const newActiveTab = currentFeatureIndex + 1;
      const newProgress = Math.max(0, Math.min(100, featureLocalProgress));

      // Solo actualizar si cambió el tab y no es un cambio manual
      if (newActiveTab !== activeTab && !isManualChange) {
        setIsTransitioning(true);
        setTimeout(() => {
          setDisplayTab(newActiveTab);
          setActiveTab(newActiveTab);
          setIsTransitioning(false);
        }, 300);
      }

      // Actualizar progreso dinámicamente solo si no es un cambio manual
      if (!isManualChange) {
        setProgress(newProgress);
      } else {
        // Si es cambio manual, mantener el progreso en 0
        setProgress(0);
      }
    };

    window.addEventListener('scroll', handleScroll, { passive: true });
    window.addEventListener('resize', handleScroll, { passive: true });
    handleScroll(); // Llamar una vez para inicializar

    return () => {
      window.removeEventListener('scroll', handleScroll);
      window.removeEventListener('resize', handleScroll);
    };
  }, [activeTab, features.length, isManualChange]);

  return (
    <section
      ref={sectionRef}
      id="how-to-start"
      className="py-12 lg:py-16 bg-transparent"
      aria-labelledby="how-to-start-heading"
    >
      <div className="mx-auto max-w-7xl px-6 lg:px-8">
        {/* Encabezado */}
        <div className="text-center mb-16">
          <h2
            id="how-to-start-heading"
            className="text-3xl sm:text-4xl lg:text-5xl font-bold text-gray-900 mb-4 tracking-tight"
          >
            {t('howToStart.title')}{' '}
            <span className="text-[#83A98A]">{t('howToStart.titleHighlight')}</span>
          </h2>
          <p className="text-lg text-gray-600 max-w-3xl mx-auto">
            {t('howToStart.subtitle')}
          </p>
        </div>

        {/* Timeline de pestañas (Desktop) - Sticky */}
        <div className="hidden lg:block mb-8 lg:sticky lg:top-[68px] lg:z-20 lg:bg-white/90 lg:backdrop-blur-sm lg:py-3 lg:pb-4">
          <div className="relative">
            {/* Línea de conexión horizontal */}
            <div className="absolute top-1/2 left-0 right-0 h-0.5 bg-gray-200 -translate-y-1/2" aria-hidden="true" />
            <div
              className="absolute top-1/2 left-0 h-0.5 bg-gradient-to-r from-[#83A98A] to-[#6D8F75] transition-all duration-500 -translate-y-1/2"
              style={{ width: `${((activeTab - 1) / (features.length - 1)) * 100}%` }}
              aria-hidden="true"
            />

            {/* Pestañas tipo slides */}
            <div className="relative flex justify-between items-center gap-4">
              {features.map((feature) => {
                const FeatureIcon = feature.icon;
                const isActive = activeTab === feature.id;
                const isPassed = feature.id < activeTab;

                return (
                  <button
                    key={feature.id}
                    onClick={() => handleTabChange(feature.id)}
                    className="flex-1 flex flex-col items-center group focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-[#83A98A] rounded-xl p-4"
                    aria-label={`Ver ${feature.title}`}
                    aria-pressed={isActive}
                  >
                    {/* Cuadrado/Rectángulo tipo slide */}
                    <div
                      className={`
                        relative w-full max-w-[100px] h-20 rounded-xl flex flex-col items-center justify-center transition-all duration-300 mb-2
                        ${isActive || isPassed
                          ? 'bg-gradient-to-br from-[#83A98A] to-[#6D8F75] shadow-xl scale-[1.02]'
                          : 'bg-white border-2 border-gray-300 group-hover:border-[#83A98A] group-hover:shadow-md'}
                      `}
                    >
                      <FeatureIcon
                        className={`transition-colors duration-300 mb-1 ${isActive || isPassed ? 'text-white' : 'text-gray-400 group-hover:text-[#83A98A]'
                          }`}
                        size={24}
                        strokeWidth={2}
                      />

                      {/* Número del paso */}
                      <span
                        className={`
                          text-xs font-bold transition-colors duration-300
                          ${isActive || isPassed ? 'text-white/80' : 'text-gray-400'}
                        `}
                      >
                        {feature.id}
                      </span>

                      {/* Barra de progreso dentro del cuadrado (solo activa) */}
                      {isActive && (
                        <div className="absolute bottom-0 left-0 right-0 h-1 bg-white/30 overflow-hidden rounded-b-xl">
                          <div
                            className="h-full bg-white transition-all duration-100 ease-linear"
                            style={{ width: `${progress}%` }}
                          />
                        </div>
                      )}
                    </div>

                    {/* Etiqueta */}
                    <span
                      className={`
                        text-xs font-semibold text-center transition-colors duration-300
                        ${isActive ? 'text-[#83A98A]' : 'text-gray-600 group-hover:text-gray-900'}
                      `}
                    >
                      {feature.title.split(' ').slice(0, 2).join(' ')}
                    </span>
                  </button>
                );
              })}
            </div>
          </div>
        </div>

        {/* Pestañas móviles */}
        <div className="lg:hidden mb-8 flex gap-2 overflow-x-auto pb-2">
          {features.map((feature) => {
            const FeatureIcon = feature.icon;
            const isActive = activeTab === feature.id;

            return (
              <button
                key={feature.id}
                onClick={() => handleTabChange(feature.id)}
                className={`
                  flex-shrink-0 px-4 py-3 rounded-lg font-semibold text-sm transition-all duration-300
                  ${isActive
                    ? 'bg-gradient-to-r from-[#83A98A] to-[#6D8F75] text-white shadow-lg scale-105'
                    : 'bg-gray-100 text-gray-600 hover:bg-gray-200'}
                `}
                aria-label={`Ver ${feature.title}`}
                aria-pressed={isActive}
              >
                <FeatureIcon className="inline-block mr-2" size={18} />
                {feature.id}
              </button>
            );
          })}
        </div>

        {/* Contenido con scroll parallax */}
        <div
          ref={contentRef}
          className="grid lg:grid-cols-2 gap-12 items-start"
        >
          {/* Video placeholder - Sticky (solo desktop) */}
          <div
            className="hidden lg:block lg:sticky lg:top-[220px] relative rounded-2xl overflow-hidden shadow-2xl h-[550px] flex items-center justify-center transition-all duration-500 bg-gray-100"
          >
            {features.map((feature) => {
              const FeatureIcon = feature.icon;
              const isActive = displayTab === feature.id;
              const mediaUrl = mediaConfigs[`how_to_start_step_${feature.id}`];
              const isVideo = mediaUrl && mediaUrl.match(/\.(mp4|webm|mov|avi)$/i);

              return (
                <div
                  key={feature.id}
                  className={`absolute inset-0 rounded-2xl ${feature.bgColor} flex items-center justify-center transition-opacity duration-500 ${isActive ? 'opacity-100 z-10' : 'opacity-0 z-0'
                    }`}
                >
                  {mediaUrl ? (
                    isVideo ? (
                      <video
                        src={mediaUrl}
                        className="w-full h-full object-cover"
                        autoPlay
                        muted
                        loop
                        playsInline
                      />
                    ) : (
                      <img
                        src={mediaUrl}
                        alt={feature.title}
                        className="w-full h-full object-cover"
                      />
                    )
                  ) : (
                    <>
                      <div className="absolute inset-0 flex items-center justify-center">
                        <FeatureIcon size={80} className="text-gray-300" strokeWidth={1.5} />
                      </div>
                      <div className="relative z-10 text-center p-8">
                        <div className="inline-block px-6 py-3 bg-white rounded-full shadow-lg">
                          <span className="text-2xl font-bold bg-gradient-to-r from-[#83A98A] to-[#6D8F75] bg-clip-text text-transparent">
                            {feature.videoLabel}
                          </span>
                        </div>
                      </div>
                    </>
                  )}
                </div>
              );
            })}
          </div>

          {/* Card de contenido mobile */}
          <div className="lg:hidden mb-8">
            {features.map((feature) => {
              const FeatureIcon = feature.icon;
              const isActive = displayTab === feature.id;

              if (!isActive) return null;

              return (
                <div
                  key={feature.id}
                  className={`rounded-2xl ${feature.bgColor} p-8 shadow-xl transition-all duration-500`}
                >
                  <div className="flex flex-col items-center text-center mb-6">
                    <div className="w-20 h-20 rounded-full bg-white shadow-lg flex items-center justify-center mb-4">
                      <FeatureIcon size={40} className="text-gray-600" strokeWidth={2} />
                    </div>
                    <span className="text-2xl font-bold bg-gradient-to-r from-[#83A98A] to-[#6D8F75] bg-clip-text text-transparent">
                      {feature.videoLabel}
                    </span>
                  </div>
                </div>
              );
            })}
          </div>

          {/* Información */}
          <div className="space-y-0">
            {features.map((feature) => {
              const isActive = displayTab === feature.id;
              const FeatureIcon = feature.icon;

              return (
                <div
                  key={feature.id}
                  className={`
                    transition-all duration-500
                    ${isActive ? 'block' : 'hidden lg:block'}
                    ${isActive ? 'lg:opacity-100' : 'lg:opacity-30'}
                    lg:min-h-[80vh] flex flex-col justify-center py-12
                  `}
                >
                  <div className="space-y-6">
                    <div>
                      <h3 className="text-3xl font-bold text-gray-900 mb-2">
                        {feature.title}
                      </h3>
                      <p className="text-xl text-[#5A7A62] font-semibold mb-4">
                        {feature.subtitle}
                      </p>
                      <p className="text-lg text-gray-600 leading-relaxed">
                        {feature.description}
                      </p>
                    </div>

                    {/* Pasos */}
                    <div>
                      <h4 className="text-lg font-bold text-gray-900 mb-4">
                        ¿Cómo usarlo?
                      </h4>
                      <ol className="space-y-3">
                        {feature.steps.map((step, stepIndex) => (
                          <li key={stepIndex} className="flex items-start gap-3">
                            <span className="flex-shrink-0 w-8 h-8 rounded-full bg-gradient-to-br from-[#83A98A] to-[#6D8F75] text-white font-bold flex items-center justify-center text-sm">
                              {stepIndex + 1}
                            </span>
                            <span className="text-gray-700 pt-1">{step}</span>
                          </li>
                        ))}
                      </ol>
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      </div>
    </section>
  );
}

