'use client';

import { useState } from 'react';
import { X, Loader2, Eye, EyeOff } from 'lucide-react';
import { type CredentialResponse } from '@react-oauth/google';
import { appleAuthHelpers } from 'react-apple-signin-auth';
import { useTranslation } from '@/hooks/useTranslation';
import { GridBackground } from '@/components/ui/GridBackground';
import { useAuth } from '@/contexts/AuthContext';
import { SocialLoginButtons } from '@/components/auth/SocialLoginButtons';

interface LoginPanelProps {
    isOpen: boolean;
    onClose: () => void;
    onSignUpClick?: (email?: string) => void;
    onForgotPasswordClick?: () => void;
}

export function LoginPanel({ isOpen, onClose, onSignUpClick, onForgotPasswordClick }: LoginPanelProps) {
    const t = useTranslation();
    const { login, loginWithOAuth, isLoading, error, clearError } = useAuth();
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [showPassword, setShowPassword] = useState(false);
    const [localError, setLocalError] = useState<string | null>(null);
    const [oauthLoading, setOauthLoading] = useState(false);

    const handleGoogleSuccess = async (credentialResponse: CredentialResponse) => {
        if (!credentialResponse.credential) {
            alert('Error: No se recibió token de Google');
            setLocalError('No se recibió el token de Google');
            return;
        }

        /* Debugging for Mobile */
        // alert('Token de Google recibido, enviando al backend...');

        setLocalError(null);
        clearError();
        setOauthLoading(true);

        try {
            await loginWithOAuth('google', credentialResponse.credential);
            // alert('Login exitoso, cerrando panel...');
            onClose();
        } catch (err) {
            alert('Error en loginWithOAuth: ' + (err instanceof Error ? err.message : String(err)));
            setLocalError(err instanceof Error ? err.message : 'Error al iniciar sesión con Google');
        } finally {
            setOauthLoading(false);
        }
    };

    const handleGoogleError = () => {
        setLocalError('Error al conectar con Google. Intenta de nuevo.');
    };

    const handleAppleLogin = async () => {
        setLocalError(null);
        clearError();
        setOauthLoading(true);

        try {
            const response = await appleAuthHelpers.signIn({
                authOptions: {
                    clientId: process.env.NEXT_PUBLIC_APPLE_CLIENT_ID || '',
                    scope: 'email name',
                    redirectURI: process.env.NEXT_PUBLIC_APP_URL || '',
                    usePopup: true,
                },
                onError: (error: any) => {
                    console.error('Apple Sign In Error:', error);
                    throw new Error(error.error || 'Error en inicio de sesión con Apple');
                },
            });

            if (response && response.authorization && response.authorization.id_token) {
                await loginWithOAuth('apple', response.authorization.id_token);
                onClose();
            } else {
                throw new Error('No se recibió el token de Apple');
            }
        } catch (err) {
            console.error(err);
            setLocalError(err instanceof Error ? err.message : 'Error al iniciar sesión con Apple');
        } finally {
            setOauthLoading(false);
        }
    };

    const handleOtherSocialLogin = () => {
        setLocalError('OAuth con este proveedor aún no está disponible.');
    };

    const handleEmailLogin = async (e: React.FormEvent) => {
        e.preventDefault();
        setLocalError(null);
        clearError();

        try {
            await login({ email, password });
            onClose();
        } catch (err) {
            setLocalError(err instanceof Error ? err.message : 'Error al iniciar sesión');
        }
    };

    const displayError = localError || error;

    return (
        <>
            {isOpen && (
                <div
                    className="fixed inset-0 bg-black/50 z-40 lg:bg-black/30 transition-opacity"
                    onClick={onClose}
                    aria-hidden="true"
                />
            )}

            <div
                className={`fixed top-0 right-0 h-full w-full lg:w-1/3 bg-white shadow-2xl z-50 transform transition-transform duration-300 ease-out ${isOpen ? 'translate-x-0' : 'translate-x-full'
                    } overflow-hidden`}
            >
                <GridBackground className="absolute inset-0 -z-10" />
                <div className="h-full flex flex-col overflow-y-auto relative z-10">
                    <div className="flex items-center justify-between p-6">
                        <button
                            onClick={onClose}
                            className="p-2 hover:bg-gray-100 rounded-full transition-colors"
                            aria-label={t('login.closeLabel')}
                        >
                            <X className="w-6 h-6 text-gray-600" />
                        </button>
                    </div>

                    <div className="flex-1 px-6 pb-6">
                        <div className="space-y-8">
                            <div>
                                <h2 className="text-2xl font-bold text-gray-900 mb-2">
                                    {t('login.title')}
                                </h2>
                                <p className="text-gray-600">{t('login.subtitle')}</p>
                            </div>

                            <form onSubmit={handleEmailLogin} className="space-y-6">
                                <div>
                                    <input
                                        type="email"
                                        value={email}
                                        onChange={(e) => setEmail(e.target.value)}
                                        className="w-full bg-transparent text-lg text-gray-900 placeholder-gray-400 border-0 border-b border-gray-300 focus:outline-none focus:border-gray-900 transition-colors pb-2"
                                        placeholder={t('login.emailPlaceholder')}
                                        required
                                    />
                                </div>

                                <div className="relative">
                                    <input
                                        type={showPassword ? "text" : "password"}
                                        value={password}
                                        onChange={(e) => setPassword(e.target.value)}
                                        className="w-full bg-transparent text-lg text-gray-900 placeholder-gray-400 border-0 border-b border-gray-300 focus:outline-none focus:border-gray-900 transition-colors pb-2 pr-10"
                                        placeholder={t('login.passwordPlaceholder')}
                                        required
                                    />
                                    <button
                                        type="button"
                                        onClick={() => setShowPassword(!showPassword)}
                                        className="absolute right-0 top-0 pb-2 text-gray-400 hover:text-gray-600 transition-colors"
                                    >
                                        {showPassword ? (
                                            <EyeOff className="w-5 h-5" />
                                        ) : (
                                            <Eye className="w-5 h-5" />
                                        )}
                                    </button>
                                </div>

                                <div className="text-right">
                                    <button
                                        type="button"
                                        onClick={() => onForgotPasswordClick?.()}
                                        className="text-sm text-[#83A98A] hover:underline"
                                    >
                                        {t('login.forgotPassword')}
                                    </button>
                                </div>

                                {displayError && (
                                    <div className="p-3 bg-red-50 border border-red-200 rounded-lg">
                                        <p className="text-sm text-red-600">{displayError}</p>
                                    </div>
                                )}

                                <button
                                    type="submit"
                                    disabled={isLoading}
                                    className="w-full bg-[#111827] text-white font-semibold py-4 px-6 rounded-full hover:bg-black transition-colors flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed"
                                >
                                    {isLoading ? (
                                        <>
                                            <Loader2 className="w-5 h-5 animate-spin" />
                                            <span>Iniciando sesión...</span>
                                        </>
                                    ) : (
                                        <>
                                            {t('login.loginButton')}
                                            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" />
                                            </svg>
                                        </>
                                    )}
                                </button>
                            </form>

                            <div className="pt-6">
                                <p className="text-sm text-gray-500 text-center mb-4">{t('login.orContinueWith')}</p>
                                <SocialLoginButtons
                                    onGoogleSuccess={handleGoogleSuccess}
                                    onGoogleError={handleGoogleError}
                                    onAppleClick={handleAppleLogin}
                                    disabled={oauthLoading}
                                    googleText="continue_with"
                                />
                            </div>

                            <div className="text-center pt-4">
                                <p className="text-sm text-gray-600">
                                    {t('login.noAccount')}{' '}
                                    <button
                                        onClick={() => {
                                            onClose();
                                            onSignUpClick?.(email);
                                        }}
                                        className="text-[#83A98A] hover:underline font-semibold"
                                    >
                                        {t('login.signUp')}
                                    </button>
                                </p>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </>
    );
}

'use client';

import { useState, useEffect, useCallback } from 'react';
import { useRouter } from 'next/navigation';
import { Users, CreditCard, Crown, Check, X, Loader2, Shield, ChevronRight, Lock, Info, PiggyBank } from 'lucide-react';
import { useTranslation } from '@/hooks/useTranslation';
import { DOCUMENT_TYPES } from '@/types/auth.types';
import { useAuth } from '@/contexts/AuthContext';
import { useUI } from '@/contexts/UIContext';
import { paymentsService, PaymentPlan, InitiatePaymentResponse } from '@/services/payments.service';
import { pricingService, PricingPlan as ApiPricingPlan } from '@/services/content.service';
import { useWompiWidget } from '@/hooks/useWompiWidget';
import { CreditCardForm } from '@/components/landing/CreditCardForm';

type UserType = 'personal' | 'empresa';
type BillingCycle = 'mensual' | 'anual';

interface Plan {
    id: string;
    name: string;
    price: string;
    priceAnnual?: string;
    priceInCents: number;
    description: string;
    buttonText: string;
    includes: string[];
    excludes: string[];
    planType?: PaymentPlan;
    isFree?: boolean;
}

// Iconos por tipo de plan (memoizado)
const PLAN_ICONS: Record<string, React.ReactNode> = {
    free: <Users className="w-4 h-4" />,
    premium: <CreditCard className="w-4 h-4" />,
    corporate: <Crown className="w-4 h-4" />,
};

function getPlanIcon(name: string): React.ReactNode {
    const lowerName = name.toLowerCase();
    if (lowerName.includes('free') || lowerName.includes('gratis')) return PLAN_ICONS.free;
    if (lowerName.includes('premium') || lowerName.includes('negocios')) return PLAN_ICONS.premium;
    return PLAN_ICONS.corporate;
}

export function Pricing() {
    const t = useTranslation();
    const router = useRouter();
    const { isAuthenticated, user } = useAuth();
    const { openLoginPanel } = useUI();
    const [userType, setUserType] = useState<UserType>('personal');
    const [billingCycle, setBillingCycle] = useState<BillingCycle>('mensual');
    const [plans, setPlans] = useState<Record<UserType, Plan[]>>({ personal: [], empresa: [] });
    const [isLoading, setIsLoading] = useState(true);
    const [processingPlan, setProcessingPlan] = useState<string | null>(null);
    const [error, setError] = useState<string | null>(null);

    const [showCardForm, setShowCardForm] = useState(false);
    const [currentPaymentData, setCurrentPaymentData] = useState<any>(null);
    const [paymentStep, setPaymentStep] = useState<'selector' | 'form'>('selector');
    const [cardType, setCardType] = useState<'credit' | 'debit'>('credit'); // New state for card type

    // Use Wompi Widget hook for card-only payments
    const { openWidget } = useWompiWidget({
        onSuccess: (result: any) => {
            console.log('✅ Payment successful:', result);
            console.log('💰 Amount Charged:', currentPaymentData?.amountInCents);
            if (result.error) {
                console.error('❌ Wompi API Error:', result.error);
                setError(`Error del sistema: ${result.error.type || 'Desconocido'} - ${result.error.reason || JSON.stringify(result.error)}`);
                setProcessingPlan(null);
                return;
            }

            if (!result.data?.id && !result.id) {
                console.error('❌ Invalid Response:', result);
                setError('Error invalido: No se recibió ID de transacción.');
                setProcessingPlan(null);
                return;
            }

            if (result.data?.status === 'DECLINED') {
                console.error('❌ Decline Reason:', result.data?.status_message);
            }
            setProcessingPlan(null);

            const txId = result.data?.id || result.id || 'approved';
            const status = (result.data?.status === 'APPROVED' || result.status === 'APPROVED') ? 'success' : 'failed';
            const reason = result.data?.status_message || result.status_message || 'Desconocido';

            router.push(`/pagos/respuesta?id=${txId}&status=${status}&reason=${encodeURIComponent(reason)}`);
        },
        onError: (err) => {
            console.error('❌ Payment error:', err);
            setError('Error en el pago. Intenta de nuevo.');
            setProcessingPlan(null);
        },
        onClose: () => {
            setProcessingPlan(null);
        }
    });

    // Manejar click en plan - SEGURIDAD: El precio viene del backend, no del frontend
    const handlePlanClick = useCallback(async (plan: Plan) => {
        // Redirigir a contacto si es Enterprise o precio personalizado
        if (
            plan.name?.toLowerCase().includes('enterprise') ||
            (typeof plan.price === 'string' && plan.price.toLowerCase().includes('personalizado'))
        ) {
            router.push('/contacto');
            return;
        }

        // Plan gratuito - redirigir a inicio
        if (plan.isFree) {
            router.push('/');
            return;
        }

        // Check Authentication - User must be logged in to purchase
        if (!isAuthenticated) {
            openLoginPanel();
            return;
        }

        // Validación: plan debe tener tipo definido
        if (!plan.planType || !plan.id) {
            setError('Plan no configurado correctamente');
            return;
        }

        setProcessingPlan(plan.id);
        setError(null);

        try {
            /*
             * SEGURIDAD: Solo enviamos el ID del plan y el ciclo de facturación.
             * El backend determina el precio real basado en estos datos.
             * La firma de integridad (signature:integrity) asegura que nadie
             * pueda manipular el monto en la URL del checkout.
             */
            const response: InitiatePaymentResponse = await paymentsService.initiatePayment({
                planId: plan.id,
                planType: plan.planType,
                billingCycle,
                redirectUrl: `${window.location.origin}/pagos/respuesta`,
                userId: user?.id,
                customerEmail: user?.email,
                customerName: user ? `${user.firstName} ${user.lastName}`.trim() : undefined,
                customerPhone: user?.phone,
                customerLegalId: user?.documentNumber,
                customerLegalIdType: user?.documentTypeId
                    ? DOCUMENT_TYPES.find(d => d.id === user.documentTypeId)?.name || user.documentType
                    : user?.documentType,
            });

            if (!response.widgetConfig?.signatureIntegrity) {
                throw new Error('Respuesta de pago inválida');
            }

            setCurrentPaymentData({
                ...response.widgetConfig,
                reference: response.reference,
            });
            setPaymentStep('selector'); // Always start at selector
            setShowCardForm(true);
        } catch (err) {
            console.error('Error initiating payment:', err);
            setError('Error al iniciar el pago. Intenta de nuevo.');
            setProcessingPlan(null);
        }
    }, [billingCycle, router, openWidget]);

    const handleDirectPaymentSuccess = (result: any) => {
        setShowCardForm(false);
        setProcessingPlan(null);
        setCurrentPaymentData(null);

        const txId = result.data?.id || 'approved';
        // Use the actual status from Wompi (APPROVED, DECLINED, PENDING)
        const wompiStatus = result.data?.status || 'PENDING';

        let status = 'pending';
        if (wompiStatus === 'APPROVED') status = 'success';
        else if (wompiStatus === 'DECLINED') status = 'failed';
        else if (wompiStatus === 'PENDING') status = 'pending';

        router.push(`/pagos/respuesta?id=${txId}&status=${status}`);
    };

    // Callback used by CreditCardForm
    const processPaymentResult = async (token: string, acceptanceToken: string, installments: number = 1) => {
        if (!currentPaymentData) throw new Error('No payment data');
        return paymentsService.processCardPayment({
            reference: currentPaymentData.reference,
            cardToken: token,
            acceptanceToken,
            email: currentPaymentData.customerData?.email || 'test@example.com',
            installments
        });
    };

    const handleDirectPaymentError = (errorMsg: string) => {
        setError(errorMsg);
        // No cerramos el modal inmediatamente para dejar ver el error
    };

    // Cargar planes del backend
    useEffect(() => {
        let isMounted = true;

        const fetchPlans = async () => {
            try {
                const data = await pricingService.getAll(true); // true = solo planes activos

                if (!isMounted) return;
                if (!Array.isArray(data)) throw new Error('Formato de datos inválido');

                const apiPlans: Record<UserType, Plan[]> = { personal: [], empresa: [] };

                data.forEach((p: ApiPricingPlan) => {
                    // Validar datos mínimos requeridos
                    if (!p.id || !p.name || !p.type) return;

                    const mapped: Plan = {
                        id: p.id,
                        name: p.name,
                        price: p.price_monthly || 'Gratis',
                        priceAnnual: p.price_annual,
                        priceInCents: p.price_monthly_cents || 0,
                        description: p.description || '',
                        buttonText: p.button_text || 'Empezar',
                        includes: Array.isArray(p.includes) ? p.includes : [],
                        excludes: Array.isArray(p.excludes) ? p.excludes : [],
                        planType: p.plan_type as PaymentPlan,
                        isFree: p.is_free || p.price_monthly === 'Gratis',
                    };

                    if (p.type === 'personal') apiPlans.personal.push(mapped);
                    else if (p.type === 'empresa') apiPlans.empresa.push(mapped);
                });

                // Sort each category: free first, then by price, corporate/personalized last
                const sortPlans = (a: Plan, b: Plan) => {
                    // Corporate/personalized plans always last
                    const aIsCorp = a.planType?.includes('corporate') || a.name?.toLowerCase().includes('personalizad');
                    const bIsCorp = b.planType?.includes('corporate') || b.name?.toLowerCase().includes('personalizad');
                    if (aIsCorp && !bIsCorp) return 1;
                    if (!aIsCorp && bIsCorp) return -1;
                    // Free plans first
                    if (a.isFree && !b.isFree) return -1;
                    if (!a.isFree && b.isFree) return 1;
                    // Then by price ascending
                    return a.priceInCents - b.priceInCents;
                };
                apiPlans.personal.sort(sortPlans);
                apiPlans.empresa.sort(sortPlans);

                setPlans(apiPlans);
            } catch (err) {
                if (isMounted) {
                    console.error('Error loading plans:', err);
                    setError('No se pudieron cargar los planes');
                }
            } finally {
                if (isMounted) setIsLoading(false);
            }
        };

        fetchPlans();
        return () => { isMounted = false; };
    }, []);

    // Planes actuales según tipo de usuario seleccionado
    const currentPlans = plans[userType];

    // Componente Skeleton para carga
    function PlanSkeleton() {
        return (
            <div className="bg-gray-800 rounded-2xl p-8 border border-gray-700 animate-pulse">
                <div className="h-8 bg-gray-700 rounded w-3/4 mb-4" />
                <div className="h-12 bg-gray-700 rounded w-1/2 mb-4" />
                <div className="h-4 bg-gray-700 rounded w-full mb-6" />
                <div className="h-12 bg-gray-700 rounded w-full mb-8" />
                <div className="space-y-3">
                    <div className="h-4 bg-gray-700 rounded w-full" />
                    <div className="h-4 bg-gray-700 rounded w-5/6" />
                    <div className="h-4 bg-gray-700 rounded w-4/6" />
                </div>
            </div>
        );
    }

    return (
        <div className="min-h-screen bg-gradient-to-br from-gray-900 via-gray-800 to-gray-900 py-12 px-4 sm:px-6 lg:px-8 relative">
            {/* Custom Credit Card Form Modal */}
            {showCardForm && currentPaymentData && (
                <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-sm p-4 animate-in fade-in duration-200">

                    {/* Step 1: Method Selector (Netflix Style) */}
                    {paymentStep === 'selector' && (
                        <div className="bg-white rounded-2xl max-w-lg w-full p-8 relative shadow-2xl animate-in zoom-in-95 duration-200 font-sans">
                            <button
                                onClick={() => {
                                    setShowCardForm(false);
                                    setProcessingPlan(null);
                                    setCurrentPaymentData(null);
                                }}
                                className="absolute top-4 right-4 text-gray-400 hover:text-gray-600 p-2 rounded-full hover:bg-gray-100 transition-colors"
                            >
                                <X className="w-5 h-5" />
                            </button>

                            <div className="text-center mb-8">
                                <div className="inline-flex p-3 rounded-full bg-red-50 text-red-500 mb-4 ring-1 ring-red-100">
                                    <Lock className="w-6 h-6" />
                                </div>
                                <h3 className="text-xl font-bold text-gray-900">Añade un método de pago</h3>
                                <p className="text-sm text-gray-500 mt-3 max-w-xs mx-auto leading-relaxed">
                                    Configura tu tarjeta para asegurar la activación inmediata y la renovación automática de tu plan Premium.
                                </p>
                            </div>

                            <div className="space-y-4">
                                {/* Credit Card Option */}
                                <button
                                    onClick={() => {
                                        setCardType('credit');
                                        setPaymentStep('form');
                                    }}
                                    className="w-full border-2 border-gray-200 rounded-xl p-4 flex items-center justify-between hover:border-[#83A98A] hover:bg-gray-50/50 transition-all group active:scale-[0.99]"
                                >
                                    <div className="flex items-center gap-4">
                                        <div className="h-10 w-10 rounded-lg bg-blue-50 flex items-center justify-center text-blue-600 group-hover:text-[#83A98A]">
                                            <CreditCard className="w-6 h-6" />
                                        </div>
                                        <div className="text-left">
                                            <span className="block font-semibold text-gray-900 group-hover:text-[#83A98A]">Tarjeta de Crédito</span>
                                            <div className="flex gap-2 mt-1.5 opacity-80">
                                                <img src="https://res.cloudinary.com/do1mvhvms/image/upload/v1768520243/VISA-Logo_zhllqu.png" alt="Visa" className="h-5 w-auto object-contain" />
                                                <img src="https://res.cloudinary.com/do1mvhvms/image/upload/v1768520242/mastercard-logo_kecgyl.png" alt="Mastercard" className="h-5 w-auto object-contain" />
                                                <img src="https://res.cloudinary.com/do1mvhvms/image/upload/v1768520242/american-logo_muhxps.png" alt="Amex" className="h-5 w-auto object-contain" />
                                            </div>
                                        </div>
                                    </div>
                                    <ChevronRight className="text-gray-300 group-hover:text-[#83A98A] w-5 h-5" />
                                </button>

                                {/* Debit Card Option */}
                                <button
                                    onClick={() => {
                                        setCardType('debit');
                                        setPaymentStep('form');
                                    }}
                                    className="w-full border-2 border-gray-200 rounded-xl p-4 flex items-center justify-between hover:border-[#83A98A] hover:bg-gray-50/50 transition-all group active:scale-[0.99]"
                                >
                                    <div className="flex items-center gap-4">
                                        <div className="h-10 w-10 rounded-lg bg-green-50 flex items-center justify-center text-green-600 group-hover:text-[#83A98A]">
                                            <PiggyBank className="w-6 h-6" />
                                        </div>
                                        <div className="text-left">
                                            <span className="block font-semibold text-gray-900 group-hover:text-[#83A98A]">Tarjeta Débito / Ahorros</span>
                                            <div className="flex gap-2 mt-1.5 opacity-80">
                                                <img src="https://res.cloudinary.com/do1mvhvms/image/upload/v1768520243/VISA-Logo_zhllqu.png" alt="Visa" className="h-5 w-auto object-contain" />
                                                <img src="https://res.cloudinary.com/do1mvhvms/image/upload/v1768520242/mastercard-logo_kecgyl.png" alt="Mastercard" className="h-5 w-auto object-contain" />
                                            </div>
                                        </div>
                                    </div>
                                    <ChevronRight className="text-gray-300 group-hover:text-[#83A98A] w-5 h-5" />
                                </button>
                            </div>

                            <div className="mt-8 text-center bg-gray-50 p-3 rounded-lg border border-gray-100">
                                <p className="text-[11px] text-gray-500 flex items-start justify-center gap-2 text-left">
                                    <Info className="w-3 h-3 flex-shrink-0 mt-0.5 text-blue-500" />
                                    <span>
                                        Este es el <strong>único método de pago habilitado</strong> para suscripciones recurrentes.
                                        Tus datos son procesados de forma segura con cifrado bancario.
                                    </span>
                                </p>
                            </div>

                            <div className="mt-6 flex justify-center">
                                <p className="text-[10px] text-gray-400 flex items-center gap-1">
                                    <Lock className="w-3 h-3" /> Cifrado de extremo a extremo
                                </p>
                            </div>
                        </div>
                    )}

                    {/* Step 2: Payment Form */}
                    {paymentStep === 'form' && (
                        <div className="w-full max-w-4xl">
                            <CreditCardForm
                                publicKey={currentPaymentData.publicKey}
                                reference={currentPaymentData.reference}
                                email={currentPaymentData.customerData?.email || 'test@example.com'}
                                amountInCents={currentPaymentData.amountInCents}
                                currency={currentPaymentData.currency}
                                planName={
                                    [...plans.personal, ...plans.empresa].find(p => p.id === processingPlan)?.name || 'Suscripción Tincadia'
                                }
                                period={billingCycle}
                                onSuccess={handleDirectPaymentSuccess}
                                onError={handleDirectPaymentError}
                                onCancel={() => setPaymentStep('selector')}
                                processPaymentResult={processPaymentResult}
                                cardType={cardType}
                            />
                        </div>
                    )}
                </div>
            )}

            <div className="max-w-7xl mx-auto">
                {/* Header */}
                <header className="text-center mb-16">
                    <h1 className="text-4xl sm:text-5xl lg:text-6xl font-bold text-white mb-4">
                        {t('pricing.title')}
                    </h1>
                    <p className="text-xl text-gray-300 max-w-2xl mx-auto">
                        {t('pricing.subtitle')}
                    </p>
                </header>

                {/* Error global */}
                {error && (
                    <div className="max-w-md mx-auto mb-8 bg-red-500/10 border border-red-500/30 rounded-lg p-4 text-center">
                        <p className="text-red-400 text-sm">{error}</p>
                    </div>
                )}

                {/* Selector de tipo de usuario */}
                <div className="flex justify-center mb-8">
                    <div className="inline-flex rounded-lg bg-gray-800 p-1 border border-gray-700">
                        {(['personal', 'empresa'] as const).map((type) => (
                            <button
                                key={type}
                                type="button"
                                onClick={() => setUserType(type)}
                                className={`px-6 py-2 rounded-md text-sm font-semibold transition-all ${userType === type
                                    ? 'bg-[#83A98A] text-white shadow-lg'
                                    : 'text-gray-300 hover:text-white'
                                    }`}
                            >
                                {t(`pricing.${type}`)}
                            </button>
                        ))}
                    </div>
                </div>

                {/* Toggle de facturación */}
                <div className="flex justify-center items-center gap-4 mb-12">
                    <span className={`text-sm font-medium ${billingCycle === 'mensual' ? 'text-white' : 'text-gray-400'}`}>
                        {t('pricing.mensual')}
                    </span>
                    <button
                        type="button"
                        onClick={() => setBillingCycle(prev => prev === 'mensual' ? 'anual' : 'mensual')}
                        className="relative inline-flex h-6 w-11 items-center rounded-full bg-gray-700 transition-colors focus:outline-none focus:ring-2 focus:ring-[#83A98A] focus:ring-offset-2 focus:ring-offset-gray-900"
                        role="switch"
                        aria-checked={billingCycle === 'anual'}
                    >
                        <span className={`inline-block h-4 w-4 transform rounded-full bg-white transition-transform ${billingCycle === 'anual' ? 'translate-x-6' : 'translate-x-1'}`} />
                    </button>
                    <div className="relative flex items-center">
                        <span className={`text-sm font-medium min-w-[50px] ${billingCycle === 'anual' ? 'text-white' : 'text-gray-400'}`}>
                            {t('pricing.anual')}
                        </span>
                        {billingCycle === 'anual' && (
                            <span className="absolute left-full ml-2 px-2 py-0.5 text-xs font-semibold text-white bg-[#83A98A] rounded whitespace-nowrap">
                                {t('pricing.save20')}
                            </span>
                        )}
                    </div>
                </div>

                {/* Cards de planes */}
                {isLoading ? (
                    <div className="flex flex-wrap justify-center gap-8">
                        {[1, 2, 3].map((i) => (
                            <div key={i} className="w-full max-w-sm"><PlanSkeleton /></div>
                        ))}
                    </div>
                ) : currentPlans.length === 0 ? (
                    <div className="text-center py-12">
                        <p className="text-gray-400 text-lg">No hay planes disponibles en este momento.</p>
                    </div>
                ) : (
                    <div className="flex flex-wrap justify-center gap-8">
                        {currentPlans.map((plan) => {
                            const displayPrice = billingCycle === 'anual' && plan.priceAnnual ? plan.priceAnnual : plan.price;
                            const isProcessing = processingPlan === plan.id;

                            return (
                                <article
                                    key={plan.id}
                                    className="w-full max-w-sm bg-gray-800 rounded-2xl p-8 border border-gray-700 hover:border-[#83A98A] transition-all hover:shadow-2xl hover:shadow-[#83A98A]/20"
                                >
                                    {/* Header del plan */}
                                    <div className="mb-6">
                                        <h3 className="text-2xl font-bold text-white mb-2">{plan.name}</h3>
                                        <div className="mb-4">
                                            {plan.isFree ? (
                                                <p className="text-3xl font-bold text-white">{plan.price}</p>
                                            ) : (
                                                <div>
                                                    <span className="text-4xl font-bold text-white">
                                                        {displayPrice.includes('$') ? displayPrice : `$${displayPrice}`}
                                                    </span>
                                                    <span className="text-gray-400 ml-2">
                                                        {billingCycle === 'anual' ? t('pricing.perYear') : t('pricing.perMonth')}
                                                    </span>
                                                </div>
                                            )}
                                        </div>
                                        <p className="text-gray-300 text-sm">{plan.description}</p>
                                    </div>

                                    {/* Botones CTA - Single Button */}
                                    <div className="mt-8 mb-4">
                                        <button
                                            onClick={() => handlePlanClick(plan)}
                                            disabled={isProcessing}
                                            className={`w-full py-3.5 rounded-xl font-bold text-base shadow-lg transition-all ${isProcessing
                                                ? 'bg-gray-600 cursor-not-allowed opacity-70'
                                                : plan.isFree
                                                    ? 'bg-white text-gray-900 hover:bg-gray-100'
                                                    : 'bg-[#83A98A] text-white hover:bg-[#6e9175] hover:scale-[1.01]'
                                                }`}
                                        >
                                            {isProcessing ? (
                                                <div className="flex items-center justify-center gap-2">
                                                    <Loader2 className="w-5 h-5 animate-spin" /> Procesando...
                                                </div>
                                            ) : (
                                                <div className="flex items-center justify-center gap-2">
                                                    {plan.isFree ? <Users className="w-5 h-5" /> : <Crown className="w-5 h-5" />}
                                                    {plan.buttonText}
                                                </div>
                                            )}
                                        </button>
                                        {!plan.isFree && (
                                            <p className="text-center text-[10px] text-gray-400 mt-2">
                                                Cancela cuando quieras. Pago seguro SSL.
                                            </p>
                                        )}
                                    </div>

                                    {/* Incluye */}
                                    {plan.includes.length > 0 && (
                                        <div className="mb-6">
                                            <h4 className="text-sm font-semibold text-gray-400 mb-3 uppercase tracking-wide">
                                                {t('pricing.includes')}
                                            </h4>
                                            <ul className="space-y-3">
                                                {plan.includes.map((item, idx) => (
                                                    <li key={idx} className="flex items-start gap-3">
                                                        <Check className="w-5 h-5 text-[#83A98A] flex-shrink-0 mt-0.5" />
                                                        <span className="text-gray-300 text-sm">{item}</span>
                                                    </li>
                                                ))}
                                            </ul>
                                        </div>
                                    )}

                                    {/* No incluye */}
                                    {plan.excludes.length > 0 && (
                                        <div>
                                            <h4 className="text-sm font-semibold text-gray-400 mb-3 uppercase tracking-wide">
                                                {t('pricing.notIncludes')}
                                            </h4>
                                            <ul className="space-y-3">
                                                {plan.excludes.map((item, idx) => (
                                                    <li key={idx} className="flex items-start gap-3">
                                                        <X className="w-5 h-5 text-red-400 flex-shrink-0 mt-0.5" />
                                                        <span className="text-gray-400 text-sm">{item}</span>
                                                    </li>
                                                ))}
                                            </ul>
                                        </div>
                                    )}
                                </article>
                            );
                        })}
                    </div>
                )}

                {/* Texto de seguridad */}
                <footer className="mt-12 text-center">
                    <p className="text-gray-400 text-sm flex items-center justify-center gap-2">
                        <Shield className="w-4 h-4" />
                        Pagos seguros procesados por Wompi. Todos los datos están encriptados.
                    </p>
                </footer>
            </div>
        </div>
    );
}

'use client';

import { useState, useEffect } from 'react';
import { X } from 'lucide-react';
import Link from 'next/link';
import { type CredentialResponse } from '@react-oauth/google';
import { appleAuthHelpers } from 'react-apple-signin-auth';
import { useTranslation } from '@/hooks/useTranslation';
import { GridBackground } from '@/components/ui/GridBackground';
import { useAuth } from '@/contexts/AuthContext';
import { SocialLoginButtons } from '@/components/auth/SocialLoginButtons';
import { RegistrationForm, type RegistrationFormData } from '@/components/auth/RegistrationForm';

interface RegistrationPanelProps {
  isOpen: boolean;
  onClose: () => void;
  initialEmail?: string;
}

export function RegistrationPanel({ isOpen, onClose, initialEmail = '' }: RegistrationPanelProps) {
  const t = useTranslation();
  const { register, loginWithOAuth, isLoading, error, clearError } = useAuth();

  const [email, setEmail] = useState('');
  const [showEmailForm, setShowEmailForm] = useState(false);
  const [formError, setFormError] = useState<string | null>(null);
  const [oauthLoading, setOauthLoading] = useState(false);

  useEffect(() => {
    if (isOpen) {
      setEmail(initialEmail || '');
      setShowEmailForm(false);
      clearError();
      setFormError(null);
    }
  }, [isOpen, initialEmail, clearError]);

  const handleClose = () => {
    setEmail('');
    setShowEmailForm(false);
    setFormError(null);
    onClose();
  };

  const handleGoogleSuccess = async (credentialResponse: CredentialResponse) => {
    if (!credentialResponse.credential) {
      setFormError('No se recibió el token de Google');
      return;
    }

    setFormError(null);
    clearError();
    setOauthLoading(true);

    try {
      await loginWithOAuth('google', credentialResponse.credential);
      handleClose();
    } catch (err) {
      setFormError(err instanceof Error ? err.message : 'Error al registrarse con Google');
    } finally {
      setOauthLoading(false);
    }
  };

  const handleGoogleError = () => {
    setFormError('Error al conectar con Google. Intenta de nuevo.');
  };

  const handleAppleLogin = async () => {
    setFormError(null);
    clearError();
    setOauthLoading(true);

    try {
      const response = await appleAuthHelpers.signIn({
        authOptions: {
          clientId: process.env.NEXT_PUBLIC_APPLE_CLIENT_ID || '',
          scope: 'email name',
          redirectURI: process.env.NEXT_PUBLIC_APP_URL || '',
          usePopup: true,
        },
        onError: (error: any) => {
          console.error('Apple Sign In Error:', error);
          throw new Error(error.error || 'Error en inicio de sesión con Apple');
        },
      });

      if (response && response.authorization && response.authorization.id_token) {
        await loginWithOAuth('apple', response.authorization.id_token);
        handleClose();
      } else {
        throw new Error('No se recibió el token de Apple');
      }
    } catch (err) {
      console.error(err);
      setFormError(err instanceof Error ? err.message : 'Error al registrarse con Apple');
    } finally {
      setOauthLoading(false);
    }
  };

  const handleFormSubmit = async (formData: RegistrationFormData) => {
    try {
      await register({
        email,
        password: formData.password,
        firstName: formData.nombre,
        lastName: formData.apellido,
        documentTypeId: formData.tipoDocumento ? Number(formData.tipoDocumento) : undefined,
        documentNumber: formData.numeroDocumento || undefined,
        phone: formData.telefono || undefined,
      });
      handleClose();
    } catch (err) {
      console.error('Registration error:', err);
    }
  };

  return (
    <>
      {isOpen && (
        <div
          className="fixed inset-0 bg-black/50 z-40 lg:bg-black/30 transition-opacity"
          onClick={handleClose}
          aria-hidden="true"
        />
      )}

      <div
        className={`fixed top-0 right-0 h-full w-full lg:w-1/3 bg-white shadow-2xl z-50 transform transition-transform duration-300 ease-out ${isOpen ? 'translate-x-0' : 'translate-x-full'
          } overflow-hidden`}
      >
        <GridBackground className="absolute inset-0 -z-10" />
        <div className="h-full flex flex-col overflow-y-auto relative z-10">
          <div className="flex items-center justify-between p-6">
            <button
              onClick={handleClose}
              className="p-2 hover:bg-gray-100 rounded-full transition-colors"
              aria-label={t('registration.panel.closeLabel')}
            >
              <X className="w-6 h-6 text-gray-600" />
            </button>
          </div>

          <div className="flex-1 px-6 pb-6">
            {!showEmailForm ? (
              <div className="space-y-8">
                <h2 className="text-2xl font-bold text-gray-900 mb-8">
                  {t('registration.panel.title')}
                </h2>

                <div className="space-y-6">
                  <input
                    type="email"
                    value={email}
                    onChange={(e) => setEmail(e.target.value)}
                    className="w-full bg-transparent text-lg text-gray-900 placeholder-gray-400 border-0 border-b border-gray-300 focus:outline-none focus:border-gray-900 transition-colors pb-2"
                    placeholder={t('registration.panel.emailPlaceholder')}
                  />

                  <button
                    onClick={() => email && setShowEmailForm(true)}
                    disabled={!email}
                    className="w-full bg-[#83A98A] text-white font-semibold py-4 px-6 rounded-full hover:bg-[#6D8F75] transition-colors disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2"
                  >
                    {t('registration.panel.continueButton')}
                    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" />
                    </svg>
                  </button>
                </div>

                {formError && (
                  <div className="bg-red-50 border border-red-200 text-red-700 px-4 py-3 rounded-lg text-sm">
                    {formError}
                  </div>
                )}

                <div className="pt-6">
                  <p className="text-sm text-gray-500 text-center mb-4">
                    {t('registration.panel.orContinueWith')}
                  </p>
                  <SocialLoginButtons
                    onGoogleSuccess={handleGoogleSuccess}
                    onGoogleError={handleGoogleError}
                    onAppleClick={handleAppleLogin}
                    disabled={oauthLoading}
                    googleText="signup_with"
                  />
                </div>

                <p className="mt-8 text-xs text-gray-500 text-center">
                  {t('registration.panel.terms')}{' '}
                  <Link href="/terminos" target="_blank" className="text-[#83A98A] hover:underline">
                    {t('registration.panel.termsLink')}
                  </Link>{' '}
                  {t('registration.panel.and')}{' '}
                  <Link href="/privacidad" target="_blank" className="text-[#83A98A] hover:underline">
                    {t('registration.panel.privacyLink')}
                  </Link>
                </p>
              </div>
            ) : (
              <RegistrationForm
                email={email}
                onEmailChange={setEmail}
                onSubmit={handleFormSubmit}
                onBack={() => setShowEmailForm(false)}
                isLoading={isLoading}
                error={error}
              />
            )}
          </div>
        </div>
      </div>
    </>
  );
}

'use client';

import { useEffect, useRef, useCallback, useState } from 'react';

// ─── Configuration ──────────────────────────────────────────────
const TOTAL_FRAMES = 140;
const FRAME_PATH = '/frames/frame_';
const FRAME_EXT = '.jpg';
const FRAME_WIDTH = 1280;
const FRAME_HEIGHT = 720;

/** Lerp factor: 0.08 = very smooth, 0.15 = snappy */
const LERP_FACTOR = 0.08;

function getFrameSrc(index: number): string {
  const num = String(Math.min(Math.max(index, 1), TOTAL_FRAMES)).padStart(4, '0');
  return `${FRAME_PATH}${num}${FRAME_EXT}`;
}

/** Ease-out cubic for smooth deceleration */
function easeOutCubic(t: number): number {
  return 1 - Math.pow(1 - t, 3);
}

/** Ease-in-out cubic for Apple-like smooth S-curve transitions */
function easeInOutCubic(t: number): number {
  return t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;
}

interface ScrollAnimationProps {
  className?: string;
  /** Render prop: receives scroll progress (0–1) */
  children?: (progress: number) => React.ReactNode;
}

export function ScrollAnimation({ className = '', children }: ScrollAnimationProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const imagesRef = useRef<HTMLImageElement[]>([]);
  const [loadProgress, setLoadProgress] = useState(0);
  const [isLoaded, setIsLoaded] = useState(false);
  const [progress, setProgress] = useState(0);

  // Lerp state
  const targetFrameRef = useRef(0);
  const currentFrameRef = useRef(0);
  const drawnFrameRef = useRef(-1);
  const progressRef = useRef(0);
  const lerpRafRef = useRef<number | null>(null);

  // ─── Preload ───────────────────────────────────────────────
  useEffect(() => {
    let mounted = true;
    let loaded = 0;
    const images: HTMLImageElement[] = new Array(TOTAL_FRAMES);

    const onLoad = () => {
      loaded++;
      if (mounted) setLoadProgress(Math.round((loaded / TOTAL_FRAMES) * 100));
      if (loaded === TOTAL_FRAMES && mounted) setIsLoaded(true);
    };

    for (let i = 0; i < TOTAL_FRAMES; i++) {
      const img = new Image();
      img.src = getFrameSrc(i + 1);
      img.onload = onLoad;
      img.onerror = onLoad;
      images[i] = img;
    }
    imagesRef.current = images;
    return () => { mounted = false; };
  }, []);

  // ─── Draw frame with dynamic scale & position ─────────────
  // Instead of CSS transform (pixelates!), we scale the image
  // INSIDE the canvas draw call for crisp rendering at any size.
  const drawFrame = useCallback((frameIndex: number) => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    const img = imagesRef.current[frameIndex];
    if (!img || !img.complete || img.naturalWidth === 0) return;

    const dpr = window.devicePixelRatio || 1;
    const displayW = canvas.clientWidth * dpr;
    const displayH = canvas.clientHeight * dpr;

    if (canvas.width !== displayW || canvas.height !== displayH) {
      canvas.width = displayW;
      canvas.height = displayH;
    }

    // White background
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(0, 0, displayW, displayH);

    // ─── Scale-in animation tied to actual frame ─────────
    const p = frameIndex / (TOTAL_FRAMES - 1);
    const growPhase = Math.min(1, p / 0.50);  // Growth over first 50% of scroll
    const eased = easeInOutCubic(growPhase);

    const isVertical = displayW < displayH;
    const isMobile = displayW < 1024;

    // Scale to COVER the canvas (prevents letterboxing cuts on taller screens)
    const scaleX = displayW / FRAME_WIDTH;
    const scaleY = displayH / FRAME_HEIGHT;
    const coverScale = isVertical ? scaleX : Math.max(scaleX, scaleY);

    // Scale animation: 50% of full size -> 100% of full size (no extra margin)
    const currentScale = coverScale * (0.50 + 0.50 * eased);

    const drawW = FRAME_WIDTH * currentScale;
    const drawH = FRAME_HEIGHT * currentScale;

    // Position X: Desktop starts right (65%) -> moves to center (50%); Mobile: centered
    const offsetX = isMobile ? 0.50 : (0.65 - 0.15 * eased);

    // Position Y: centered (50%) -> slightly lower (58%)
    const startY = isMobile ? 0.70 : 0.50;
    const endY   = isMobile ? 0.85 : 0.58;
    const offsetY = startY + (endY - startY) * eased;

    const drawX = displayW * offsetX - drawW / 2;
    const drawY = displayH * offsetY - drawH / 2;

    ctx.drawImage(img, drawX, drawY, drawW, drawH);
  }, []);

  // ─── Scroll → target frame + progress ──────────────────────
  useEffect(() => {
    if (!isLoaded) return;

    const handleScroll = () => {
      const container = containerRef.current;
      if (!container) return;

      const rect = container.getBoundingClientRect();
      const windowH = window.innerHeight;
      const totalScrollable = rect.height - windowH;
      const scrolled = -rect.top;
      const p = Math.max(0, Math.min(1, scrolled / totalScrollable));

      targetFrameRef.current = Math.min(
        TOTAL_FRAMES - 1,
        Math.max(0, Math.floor(p * (TOTAL_FRAMES - 1)))
      );
      progressRef.current = p;
      setProgress(p);
    };

    window.addEventListener('scroll', handleScroll, { passive: true });
    handleScroll();
    return () => window.removeEventListener('scroll', handleScroll);
  }, [isLoaded]);

  // ─── Lerp loop ─────────────────────────────────────────────
  useEffect(() => {
    if (!isLoaded) return;
    drawFrame(0);
    drawnFrameRef.current = 0;

    const animate = () => {
      const target = targetFrameRef.current;
      const current = currentFrameRef.current;
      const diff = target - current;

      if (Math.abs(diff) > 0.1) {
        currentFrameRef.current += diff * LERP_FACTOR;
      } else {
        currentFrameRef.current = target;
      }

      const frameInt = Math.round(currentFrameRef.current);
      // Always redraw to update scale/position even if frame didn't change
      drawnFrameRef.current = frameInt;
      drawFrame(frameInt);

      lerpRafRef.current = requestAnimationFrame(animate);
    };

    lerpRafRef.current = requestAnimationFrame(animate);
    return () => { if (lerpRafRef.current !== null) cancelAnimationFrame(lerpRafRef.current); };
  }, [isLoaded, drawFrame]);

  // ─── Resize ────────────────────────────────────────────────
  useEffect(() => {
    if (!isLoaded) return;
    const handleResize = () => drawFrame(Math.round(currentFrameRef.current));
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, [isLoaded, drawFrame]);

  return (
    <div ref={containerRef} className={`relative h-[250vh] ${className}`}>
      <div className="sticky top-0 h-screen w-full overflow-hidden bg-white">
        {/* Loading */}
        {!isLoaded && (
          <div className="absolute inset-0 z-30 flex flex-col items-center justify-center bg-white">
            <div className="relative w-48 h-1.5 bg-gray-200 rounded-full overflow-hidden">
              <div
                className="absolute inset-y-0 left-0 bg-[#83A98A] rounded-full transition-all duration-300 ease-out"
                style={{ width: `${loadProgress}%` }}
              />
            </div>
            <span className="mt-3 text-sm text-gray-400 font-medium tracking-wide">
              {loadProgress}%
            </span>
          </div>
        )}

        {/* Canvas — no CSS transform, scaling is done inside drawImage */}
        <canvas
          ref={canvasRef}
          className="absolute inset-0 w-full h-full"
          aria-hidden="true"
        />

        {/* Overlay content */}
        {children && (
          <div className="absolute inset-0 z-10">
            {children(progress)}
          </div>
        )}
      </div>
    </div>
  );
}

'use client';

import Link from 'next/link';
import { GraduationCap, Languages, PenTool } from 'lucide-react';
import { useTranslation } from '@/hooks/useTranslation';
import { useState, useEffect, useMemo } from 'react';
import { api } from '@/lib/api-client';
import { ServiceCard } from './ServiceCard';

export function Services() {
  const t = useTranslation();
  const [config, setConfig] = useState<Record<string, string>>({});

  useEffect(() => {
    const fetchConfig = async () => {
      try {
        const data = await api.get<any[]>('/content/landing-config');
        const configMap = data.reduce((acc, item) => ({ ...acc, [item.key]: item.value }), {});
        setConfig(configMap);
      } catch (error) {
        console.error('Failed to fetch landing config:', error);
      }
    };
    fetchConfig();
  }, []);

  const services = useMemo(() => [
    {
      id: 'clases-lengua-senas',
      icon: GraduationCap,
      badge: t('services.signLanguage.badge'),
      title: t('services.signLanguage.title'),
      subtitle: t('services.signLanguage.subtitle'),
      description: t('services.signLanguage.description'),
      primaryAction: { text: t('services.signLanguage.primaryAction'), href: '/cursos' },
      secondaryAction: { text: t('services.signLanguage.secondaryAction'), href: '/cursos' },
      backgroundImage: config['service_1_bg'] || '',
    },
    {
      id: 'traductor-senas',
      icon: Languages,
      badge: t('services.translator.badge'),
      title: t('services.translator.title'),
      subtitle: t('services.translator.subtitle'),
      description: t('services.translator.description'),
      primaryAction: { text: t('services.translator.primaryAction'), href: '/descargar' },
      secondaryAction: { text: t('services.translator.secondaryAction'), href: '/descargar' },
      backgroundImage: config['service_2_bg'] || '',
    },
    {
      id: 'asistente-redaccion',
      icon: PenTool,
      badge: t('services.writingAssistant.badge'),
      title: t('services.writingAssistant.title'),
      subtitle: t('services.writingAssistant.subtitle'),
      description: t('services.writingAssistant.description'),
      primaryAction: { text: t('services.writingAssistant.primaryAction'), href: '/descargar' },
      secondaryAction: { text: t('services.writingAssistant.secondaryAction'), href: '/descargar' },
      backgroundImage: config['service_3_bg'] || '',
    },
  ], [t, config]);

  return (
    <section
      className="py-12 lg:py-16 bg-transparent"
      aria-labelledby="services-heading"
    >
      <div className="mx-auto max-w-7xl px-6 lg:px-8">
        {/* Encabezado de la sección */}
        <div className="text-center mb-16">
          <h2
            id="services-heading"
            className="text-3xl sm:text-4xl lg:text-5xl font-bold text-gray-900 mb-6 tracking-tight"
          >
            {t('services.title')}
          </h2>
          <p className="text-lg text-gray-600 max-w-3xl mx-auto">
            {t('services.subtitle')}
          </p>
        </div>

        {/* Grid de tarjetas de servicios */}
        <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-8 justify-items-center">
          {services.map((service) => (
            <ServiceCard
              key={service.id}
              title={service.title}
              subtitle={service.subtitle}
              description={service.description}
              backgroundImage={service.backgroundImage}
              primaryAction={service.primaryAction}
              secondaryAction={service.secondaryAction}
            />
          ))}
        </div>
      </div>
    </section>
  );
}

