'use client';

import { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import esTranslations from '@/locales/es';
import enTranslations from '@/locales/en';
import ptTranslations from '@/locales/pt';

export type Locale = 'es' | 'en' | 'pt';

type Translations = typeof esTranslations;

interface I18nContextType {
  locale: Locale;
  setLocale: (locale: Locale) => void;
  t: (key: string) => any;
  translations: Translations;
}

const I18nContext = createContext<I18nContextType | undefined>(undefined);

const translationsMap: Record<Locale, Translations> = {
  es: esTranslations,
  en: enTranslations,
  pt: ptTranslations,
};

interface I18nProviderProps {
  children: ReactNode;
  defaultLocale?: Locale;
}

export function I18nProvider({ children, defaultLocale = 'es' }: I18nProviderProps) {
  const [locale, setLocaleState] = useState<Locale>(defaultLocale);

  // Cargar el idioma guardado en localStorage al iniciar
  useEffect(() => {
    const savedLocale = localStorage.getItem('tincadia-locale') as Locale | null;
    if (savedLocale && (savedLocale === 'es' || savedLocale === 'en' || savedLocale === 'pt')) {
      setLocaleState(savedLocale);
    }
  }, []);

  // Guardar el idioma en localStorage cuando cambie
  const setLocale = (newLocale: Locale) => {
    setLocaleState(newLocale);
    localStorage.setItem('tincadia-locale', newLocale);
  };

  // Función para obtener traducciones usando notación de punto (ej: "hero.title")
  const t = (key: string): any => {
    const keys = key.split('.');
    let value: any = translationsMap[locale];

    for (const k of keys) {
      if (value && typeof value === 'object' && k in value) {
        value = value[k];
      } else {
        // Si no se encuentra la clave, intentar con español como fallback
        value = translationsMap.es;
        for (const fallbackKey of keys) {
          if (value && typeof value === 'object' && fallbackKey in value) {
            value = value[fallbackKey];
          } else {
            return key; // Devolver la clave si no se encuentra
          }
        }
        break;
      }
    }

    // Devolver el valor tal cual (puede ser string, array, objeto, etc.)
    return value !== undefined ? value : key;
  };

  return (
    <I18nContext.Provider
      value={{
        locale,
        setLocale,
        t,
        translations: translationsMap[locale],
      }}
    >
      {children}
    </I18nContext.Provider>
  );
}

export function useI18n() {
  const context = useContext(I18nContext);
  if (context === undefined) {
    throw new Error('useI18n must be used within an I18nProvider');
  }
  return context;
}

'use client';

import React, { createContext, useContext, useState, ReactNode, useEffect } from 'react';

interface UIContextType {
    isRegistrationPanelOpen: boolean;
    setIsRegistrationPanelOpen: (isOpen: boolean) => void;
    registrationEmail: string;
    setRegistrationEmail: (email: string) => void;
    isLoginPanelOpen: boolean;
    setIsLoginPanelOpen: (isOpen: boolean) => void;
    openLoginPanel: () => void;
    isForgotPasswordPanelOpen: boolean;
    setIsForgotPasswordPanelOpen: (isOpen: boolean) => void;
    openForgotPasswordPanel: () => void;
}

const UIContext = createContext<UIContextType | undefined>(undefined);

export function UIProvider({ children }: { children: ReactNode }) {
    const [isRegistrationPanelOpen, setIsRegistrationPanelOpen] = useState(false);
    const [registrationEmail, setRegistrationEmail] = useState('');
    const [isLoginPanelOpen, setIsLoginPanelOpen] = useState(false);
    const [isForgotPasswordPanelOpen, setIsForgotPasswordPanelOpen] = useState(false);

    const openLoginPanel = () => setIsLoginPanelOpen(true);
    const openForgotPasswordPanel = () => setIsForgotPasswordPanelOpen(true);

    // Expose login panel function globally for Navbar (legacy support if needed, but context is better)
    useEffect(() => {
        (window as any).openLoginPanel = openLoginPanel;
        return () => {
            delete (window as any).openLoginPanel;
        };
    }, []);

    return (
        <UIContext.Provider value={{
            isRegistrationPanelOpen,
            setIsRegistrationPanelOpen,
            registrationEmail,
            setRegistrationEmail,
            isLoginPanelOpen,
            setIsLoginPanelOpen,
            openLoginPanel,
            isForgotPasswordPanelOpen,
            setIsForgotPasswordPanelOpen,
            openForgotPasswordPanel
        }}>
            {children}
        </UIContext.Provider>
    );
}

export function useUI() {
    const context = useContext(UIContext);
    if (context === undefined) {
        throw new Error('useUI must be used within a UIProvider');
    }
    return context;
}

