'use client';

import { useEffect, useCallback, useRef } from 'react';
import { WompiWidgetConfig } from '@/services/payments.service';

declare global {
    interface Window {
        WidgetCheckout: any;
    }
}

export interface WompiResult {
    transaction: {
        id: string;
        status: string;
        reference: string;
        amount_in_cents: number;
        currency: string;
        payment_method_type: string;
        customer_email: string;
    };
}

interface UseWompiWidgetOptions {
    onSuccess?: (result: WompiResult) => void;
    onError?: (error: any) => void;
    onClose?: () => void;
}

export function useWompiWidget(options: UseWompiWidgetOptions = {}) {
    const scriptLoaded = useRef(false);
    const checkoutRef = useRef<any>(null);

    // Cargar el script de Wompi
    useEffect(() => {
        if (typeof window === 'undefined' || scriptLoaded.current) return;

        const existingScript = document.querySelector('script[src="https://checkout.wompi.co/widget.js"]');

        if (existingScript) {
            scriptLoaded.current = true;
            return;
        }

        const script = document.createElement('script');
        script.src = 'https://checkout.wompi.co/widget.js';
        script.async = true;
        script.onload = () => {
            scriptLoaded.current = true;
        };
        script.onerror = () => {
            console.error('Failed to load Wompi widget script');
            options.onError?.({ message: 'Failed to load payment widget' });
        };

        document.head.appendChild(script);

        return () => {
            // No removemos el script para evitar problemas de recarga
        };
    }, [options]);

    // Abrir el widget de Wompi
    const openWidget = useCallback((config: WompiWidgetConfig) => {
        console.log('🔓 Opening Wompi widget...');
        console.log('🌐 Window.WidgetCheckout:', typeof window !== 'undefined' ? !!window.WidgetCheckout : 'SSR');

        if (typeof window === 'undefined' || !window.WidgetCheckout) {
            console.error('❌ Wompi widget not loaded');
            options.onError?.({ message: 'Payment widget not ready' });
            return;
        }

        try {
            console.log('📦 Widget config received:', config);
            // Crear configuración del checkout
            const checkoutConfig: any = {
                currency: config.currency,
                amountInCents: config.amountInCents,
                reference: config.reference,
                publicKey: config.publicKey,
                signature: { integrity: config.signatureIntegrity },
            };

            // Redirect URL for when payment completes
            if (config.redirectUrl) {
                checkoutConfig.redirectUrl = config.redirectUrl;
            }

            if (config.expirationTime) {
                checkoutConfig.expirationTime = config.expirationTime;
            }

            if (config.customerData) {
                checkoutConfig.customerData = {
                    email: config.customerData.email,
                    fullName: config.customerData.fullName,
                    phoneNumber: config.customerData.phoneNumber,
                    phoneNumberPrefix: config.customerData.phoneNumberPrefix || '+57',
                    legalId: config.customerData.legalId,
                    legalIdType: config.customerData.legalIdType,
                };
            }

            // Crear instancia del checkout
            checkoutRef.current = new window.WidgetCheckout(checkoutConfig);

            // Abrir el widget
            checkoutRef.current.open((result: WompiResult) => {
                if (result.transaction) {
                    const { status } = result.transaction;

                    if (status === 'APPROVED') {
                        options.onSuccess?.(result);
                    } else if (status === 'DECLINED' || status === 'ERROR' || status === 'VOIDED') {
                        options.onError?.(result);
                    }
                }

                options.onClose?.();
            });
        } catch (error) {
            console.error('Error opening Wompi widget:', error);
            options.onError?.(error);
        }
    }, [options]);

    return {
        openWidget,
        isReady: scriptLoaded.current,
    };
}

/**
 * API Client
 * 
 * HTTP client with interceptors for authentication, error handling,
 * and automatic token refresh.
 */

import { apiConfig, API_BASE_URL, API_TIMEOUT, AUTH_STORAGE_PREFIX } from '@/config/api.config';
import type { ApiResponse, ApiError } from '@/types/api.types';
import type { AuthTokens } from '@/types/auth.types';

// ===========================================
// Types
// ===========================================

export interface RequestConfig extends RequestInit {
    timeout?: number;
    skipAuth?: boolean;
}

export class ApiClientError extends Error {
    constructor(
        message: string,
        public statusCode: number,
        public code: string,
        public details?: Record<string, string[]>
    ) {
        super(message);
        this.name = 'ApiClientError';
    }
}

// ===========================================
// Token Management
// ===========================================

const STORAGE_KEYS = {
    ACCESS_TOKEN: `${AUTH_STORAGE_PREFIX}access_token`,
    REFRESH_TOKEN: `${AUTH_STORAGE_PREFIX}refresh_token`,
} as const;

export const tokenStorage = {
    getAccessToken: (): string | null => {
        if (typeof window === 'undefined') return null;
        return localStorage.getItem(STORAGE_KEYS.ACCESS_TOKEN);
    },

    getRefreshToken: (): string | null => {
        if (typeof window === 'undefined') return null;
        return localStorage.getItem(STORAGE_KEYS.REFRESH_TOKEN);
    },

    setTokens: (tokens: AuthTokens): void => {
        if (typeof window === 'undefined') return;
        localStorage.setItem(STORAGE_KEYS.ACCESS_TOKEN, tokens.accessToken);
        if (tokens.refreshToken) {
            localStorage.setItem(STORAGE_KEYS.REFRESH_TOKEN, tokens.refreshToken);
        }
    },

    clearTokens: (): void => {
        if (typeof window === 'undefined') return;
        localStorage.removeItem(STORAGE_KEYS.ACCESS_TOKEN);
        localStorage.removeItem(STORAGE_KEYS.REFRESH_TOKEN);
    },

    hasTokens: (): boolean => {
        return !!tokenStorage.getAccessToken();
    },
};

// ===========================================
// Token Refresh Logic
// ===========================================

let isRefreshing = false;
let refreshSubscribers: Array<(token: string) => void> = [];

const subscribeTokenRefresh = (callback: (token: string) => void) => {
    refreshSubscribers.push(callback);
};

const onTokenRefreshed = (newToken: string) => {
    refreshSubscribers.forEach((callback) => callback(newToken));
    refreshSubscribers = [];
};

/**
 * Attempt to refresh the access token
 * Note: Backend doesn't have a refresh token endpoint, so this just clears tokens
 * and returns null, requiring user to re-login
 */
const refreshAccessToken = async (): Promise<string | null> => {
    // Backend doesn't support token refresh, clear tokens and require re-login
    tokenStorage.clearTokens();
    return null;
};

// ===========================================
// API Client
// ===========================================

/**
 * Make an HTTP request to the API
 * 
 * @param endpoint - API endpoint (e.g., '/auth/login')
 * @param config - Request configuration
 * @returns Promise with the response data
 * 
 * @example
 * // Simple GET request
 * const user = await apiClient<User>('/auth/me');
 * 
 * @example
 * // POST request with body
 * const response = await apiClient<LoginResponse>('/auth/login', {
 *   method: 'POST',
 *   body: JSON.stringify({ email, password }),
 * });
 */
export async function apiClient<T>(
    endpoint: string,
    config: RequestConfig = {}
): Promise<T> {
    const { timeout = API_TIMEOUT, skipAuth = false, ...fetchConfig } = config;

    // Build headers
    const headers = new Headers(fetchConfig.headers);

    if (!headers.has('Content-Type')) {
        headers.set('Content-Type', 'application/json');
    }

    // Add authorization header if not skipped
    if (!skipAuth) {
        const accessToken = tokenStorage.getAccessToken();
        if (accessToken) {
            headers.set('Authorization', `Bearer ${accessToken}`);
        }
    }

    // Create abort controller for timeout
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), timeout);

    try {
        const response = await fetch(`${API_BASE_URL}${endpoint}`, {
            ...fetchConfig,
            headers,
            signal: controller.signal,
        });

        clearTimeout(timeoutId);

        // Handle 401 Unauthorized - try to refresh token
        if (response.status === 401 && !skipAuth) {
            if (!isRefreshing) {
                isRefreshing = true;
                const newToken = await refreshAccessToken();
                isRefreshing = false;

                if (newToken) {
                    onTokenRefreshed(newToken);
                    // Retry original request with new token
                    headers.set('Authorization', `Bearer ${newToken}`);
                    const retryResponse = await fetch(`${API_BASE_URL}${endpoint}`, {
                        ...fetchConfig,
                        headers,
                    });

                    if (!retryResponse.ok) {
                        const errorData = await retryResponse.json().catch(() => ({}));
                        throw new ApiClientError(
                            errorData.message || 'Request failed',
                            retryResponse.status,
                            errorData.code || 'UNKNOWN_ERROR',
                            errorData.details
                        );
                    }

                    return retryResponse.json() as Promise<T>;
                } else {
                    // Refresh failed, clear tokens and throw
                    throw new ApiClientError(
                        'Session expired. Please login again.',
                        401,
                        'SESSION_EXPIRED'
                    );
                }
            } else {
                // Wait for token refresh
                return new Promise((resolve, reject) => {
                    subscribeTokenRefresh(async (newToken) => {
                        try {
                            headers.set('Authorization', `Bearer ${newToken}`);
                            const retryResponse = await fetch(`${API_BASE_URL}${endpoint}`, {
                                ...fetchConfig,
                                headers,
                            });
                            resolve(retryResponse.json() as Promise<T>);
                        } catch (err) {
                            reject(err);
                        }
                    });
                });
            }
        }

        // Handle other errors
        if (!response.ok) {
            const errorData: ApiError = await response.json().catch(() => ({
                message: 'An error occurred',
                code: 'UNKNOWN_ERROR',
            }));

            throw new ApiClientError(
                errorData.message,
                response.status,
                errorData.code,
                errorData.details
            );
        }

        // Handle empty responses (204 No Content)
        if (response.status === 204) {
            return {} as T;
        }

        return response.json() as Promise<T>;
    } catch (error) {
        clearTimeout(timeoutId);

        if (error instanceof ApiClientError) {
            throw error;
        }

        if (error instanceof Error) {
            if (error.name === 'AbortError') {
                throw new ApiClientError('Request timeout', 408, 'TIMEOUT');
            }
            throw new ApiClientError(error.message, 500, 'NETWORK_ERROR');
        }

        throw new ApiClientError('An unexpected error occurred', 500, 'UNKNOWN_ERROR');
    }
}

// ===========================================
// Convenience Methods
// ===========================================

export const api = {
    get: <T>(endpoint: string, config?: RequestConfig) =>
        apiClient<T>(endpoint, { ...config, method: 'GET' }),

    post: <T>(endpoint: string, data?: unknown, config?: RequestConfig) =>
        apiClient<T>(endpoint, {
            ...config,
            method: 'POST',
            body: data ? JSON.stringify(data) : undefined,
        }),

    put: <T>(endpoint: string, data?: unknown, config?: RequestConfig) =>
        apiClient<T>(endpoint, {
            ...config,
            method: 'PUT',
            body: data ? JSON.stringify(data) : undefined,
        }),

    patch: <T>(endpoint: string, data?: unknown, config?: RequestConfig) =>
        apiClient<T>(endpoint, {
            ...config,
            method: 'PATCH',
            body: data ? JSON.stringify(data) : undefined,
        }),

    delete: <T>(endpoint: string, config?: RequestConfig) =>
        apiClient<T>(endpoint, { ...config, method: 'DELETE' }),
};

export default api;

import { api } from '@/lib/api-client';
import { CONTENT_ENDPOINTS, buildUrl } from '@/config/api.config';

// ===========================================
// Interfaces
// ===========================================

export interface Course {
    id: string;
    title: string;
    description: string;
    thumbnailUrl: string;
    categoryId: string;
    category?: {
        id: string;
        name: string;
    };
    isPublished: boolean;
    accessScope?: 'course' | 'module' | 'lesson';
    isPaid?: boolean;
    priceInCents?: number;
    priceLabel?: string;
    learningPoints?: string[];
    features?: string[];
    previewLimit?: number | null;
    modules?: any[];
}

export interface LandingConfigItem {
    key: string;
    value: string;
    description: string;
    updatedAt: string;
}

export const contentService = {
    /**
     * Get all courses
     */
    getAllCourses: async (): Promise<Course[]> => {
        return api.get<Course[]>(CONTENT_ENDPOINTS.COURSES);
    },

    /**
     * Get course by ID
     */
    getCourseById: async (id: string, opts?: { hasAccess?: boolean }): Promise<Course> => {
        const query = opts?.hasAccess ? `?hasAccess=${opts.hasAccess}` : '';
        const endpoint = CONTENT_ENDPOINTS.DETAILS.replace(':id', id) + query;
        return api.get<Course>(endpoint);
    },

    /**
     * Create a new course
     */
    createCourse: async (data: Partial<Course>): Promise<Course> => {
        try {
            const response = await fetch(buildUrl(CONTENT_ENDPOINTS.CREATE), {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(data),
            });

            if (!response.ok) throw new Error('Failed to create course');
            return await response.json();
        } catch (error) {
            console.error('Error creating course:', error);
            throw error;
        }
    },

    /**
     * Update a course
     */
    updateCourse: async (id: string, data: Partial<Course>): Promise<Course> => {
        try {
            const url = buildUrl(CONTENT_ENDPOINTS.UPDATE).replace(':id', id);
            const response = await fetch(url, {
                method: 'PUT',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(data),
            });

            if (!response.ok) throw new Error('Failed to update course');
            return await response.json();
        } catch (error) {
            console.error('Error updating course:', error);
            throw error;
        }
    },

    /**
     * Create a new module
     */
    deleteCourse: async (id: string): Promise<void> => {
        const url = buildUrl(CONTENT_ENDPOINTS.DELETE).replace(':id', id);
        await fetch(url, { method: 'DELETE' });
    },

    // --- Module ---

    createModule: async (courseId: string, data: { title: string; description?: string; isPaid?: boolean }): Promise<any> => {
        try {
            const url = buildUrl(CONTENT_ENDPOINTS.CREATE_MODULE).replace(':courseId', courseId);
            const response = await fetch(url, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(data),
            });
            if (!response.ok) throw new Error('Failed to create module');
            return await response.json();
        } catch (error) {
            console.error('Error creating module:', error);
            throw error;
        }
    },

    updateModule: async (id: string, data: { title?: string; description?: string; isPaid?: boolean }): Promise<any> => {
        const url = buildUrl(CONTENT_ENDPOINTS.UPDATE_MODULE).replace(':id', id);
        const response = await fetch(url, {
            method: 'PUT',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(data),
        });
        if (!response.ok) throw new Error('Failed to update module');
        return await response.json();
    },

    deleteModule: async (id: string): Promise<void> => {
        const url = buildUrl(CONTENT_ENDPOINTS.DELETE_MODULE).replace(':id', id);
        await fetch(url, { method: 'DELETE' });
    },

    // --- Lesson ---

